BIBLIOTECA.textos({
"bocage-soneto-incultas-producoes-da-mocidade": {"t":["Incultas produções da mocidade\nExponho a vossos olhos, oh leitores:\nVede-as com mágoa, vede-as com piedade,\nQue elas buscam piedade, e não louvores:\n\nPonderai da Fortuna a variedade\nNos meus suspiros, lágrimas, e amores;\nNotai dos males seus a imensidade,\nA curta duração de seus favores:\n\nE se entre versos mil de sentimento\nEncontrardes alguns, cuja aparência\nIndique festival contentamento,\n\nCrede, oh mortais, que foram com violência\nEscritos pela mão do Fingimento,\nCantados pela voz da Dependência."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 1, «Proposição das rimas do Poeta»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 8: «de seus favores» na ed. de 1875; «dos seus favores» na ed. de 1853.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-chorosos-versos-meus-desentoados": {"t":["Chorosos versos meus desentoados,\nSem arte, sem beleza, e sem brandura,\nUrdidos pela mão da Desventura,\nPela baça Tristeza envenenados:\n\nVede a luz, não busqueis, desesperados,\nNo mudo esquecimento a sepultura;\nSe os ditosos vos lerem sem ternura,\nLer-vos-ão com ternura os desgraçados:\n\nNão vos inspire, oh versos, cobardia\nDa sátira mordaz o furor louco,\nDa maldizente voz e tirania:\n\nDesculpa tendes, se valeis tão pouco;\nQue não pode cantar com melodia\nUm peito, de gemer cansado e rouco."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 2, «O autor aos seus versos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nMesóclise do original mantida (ler-vos-hão > ler-vos-ão).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-suspirar-em-vao-ja-fatigado": {"t":["De suspirar em vão já fatigado,\nDando trégua a meus males eu dormia;\nEis que junto de mim sonhei que via\nDa Morte o gesto lívido, e mirrado:\n\nCurva fouce no punho descarnado\nSustentava a cruel, e me dizia:\n«Eu venho terminar tua agonia;\nMorre, não penes mais, oh desgraçado!»\n\nQuis ferir-me, e de Amor foi atalhada,\nQue armado de cruentos passadores\nAparece, e lhe diz com voz irada:\n\nEmprega n'outro objeto os teus rigores;\n«Que esta vida infeliz está guardada\nPara vítima só de meus furores.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 3, «Sonho»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-raios-nao-peco-ao-criador-do-mundo": {"t":["Raios não peço ao criador do mundo,\nTormentas não suplico ao rei dos mares,\nVulcões à terra, furacões aos ares,\nNegros monstros ao báratro profundo:\n\nNão rogo ao deus d'amor, que furibundo\nTe arremesse do pé de seus altares;\nOu que a peste mortal voe a teus lares,\nE murche o teu semblante rubicundo:\n\nNada imploro em teu dano, ainda que os laços\nUrdidos pela fé, com vil mudança\nFizeste, ingrata Nise, em mil pedaços:\n\nNão quero outro despique, outra vingança,\nMais que ver-te em poder de indignos braços,\nE dizer quem te perde, e quem te alcança."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 4, «Contra a ingratidão de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-sobre-o-coche-d-ebano-estrelado": {"t":["Já sobre o coche d'ébano estrelado\nDeu meio giro a noute escura e feia;\nQue profundo silêncio me rodeia\nN'este deserto bosque, à luz vedado!\n\nJaz entre as folhas Zéfiro abafado,\nO Tejo adormeceu na lisa areia;\nNem o mavioso rouxinol gorjeia,\nNem pia o mocho, às trevas costumado:\n\nSó eu velo, só eu, pedindo à sorte\nQue o fio, com que está minha alma presa\nÀ vil matéria lânguida, me corte:\n\nConsola-me este horror, esta tristeza;\nPorque a meus olhos se afigura a morte\nNo silêncio total da natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 5, «Insônia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-mavorte-porque-em-perfida-cilada": {"t":["Mavorte, porque em pérfida cilada\nO cruel moço alígero o ferira,\nNão faz caso da mãe, que chora e brada,\nQuer punir o traidor, que lhe fugira:\n\nNa sinistra o pavês, na destra a espada,\nNos ígneos olhos fuzilante a ira,\nPula à negra carroça ensanguentada,\nQue Belona infernal co'as Fúrias tira:\n\nAssim parte, assim voa; eis que vê posto\nNo colo de Marília o deus alado,\nNo colo aonde tem mimoso encosto:\n\nJá Marte arroja as armas, e aplacado\nDiz, inclinando o formidável rosto:\n«Valha-te, Amor, esse lugar sagrado!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 6, «O colo de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ao-templo-do-propicio-desengano": {"t":["Ao templo do propício Desengano\nA próvida Razão guiou meus passos;\nPor ver-me, louco já, mordendo os laços,\nOs duros laços de um amor profano:\n\nAjoelho ante o númen soberano,\nMostro-lhe os roxos, os cativos braços,\nDizendo-lhe: — «Gran deus, faze em pedaços\nOs ferros, que me pôs Amor tirano!»\n\nA deidade, inimiga da Esperança,\nMe responde: — «Eu te livro do flagelo\nQue oprime os corações; mortal, descansa.»\n\nEis que, brandindo um lúcido cutelo,\nMeus ferros corta, logo da lembrança\nMe escapa de Marfida o rosto belo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 7, «O Poeta livre das prisões d'Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-marilia-teu-gesto-vergonhoso": {"t":["Não, Marília, teu gesto vergonhoso,\nA luz dos olhos teus, serena e pura,\nTeu riso, que enche as almas de ternura,\nAgora meigo, agora desdenhoso:\n\nTua cândida mão, teu pé mimoso,\nTuas mil perfeições, crer que a ventura\nAs guarda para mim, fora loucura;\nNem sou digno de ti, nem sou ditoso:\n\nE que mortal enfim, que peito humano\nMerece os braços teus, oh ninfa amada?\nQue Narciso? Que herói? Que soberano?\n\nMas que lê minha mente iluminada!...\nCéus!... Penetro o futuro!... Ah, não me engano;\nDe Jove para o toro estás guardada."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 8, «Celebra as perfeições de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-a-loura-filis-na-estacao-das-flores": {"t":["A loura Fílis, na estação das flores,\nComigo passeou por este prado\nMil vezes, por sinal trazia ao lado\nAs Graças, os Prazeres, e os Amores.\n\nQuantos mimos então, quantos favores,\nQue inocente afeição, que puro agrado\nMe não viram gozar (oh doce estado!)\nMordendo-se de inveja os mais pastores!\n\nPorém, segundo o feminil costume,\nJá Fílis se esqueceu do amor mais terno,\nE com Jônio se ri de meu queixume.\n\nAh! se nos corações fosses eterno,\nTormento abrasador, negro ciúme,\nSerias tão cruel como os do inferno!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 9, «Recordações de Fílis»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Filis > Fílis.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-marilia-nos-teus-olhos-bulicosos": {"t":["Marília, nos teus olhos buliçosos\nOs Amores gentis seu facho acendem;\nA teus lábios voando os ares fendem\nTerníssimos desejos sequiosos:\n\nTeus cabelos sutis e luminosos\nMil vistas cegam, mil vontades prendem;\nE em arte aos de Minerva se não rendem\nTeus alvos curtos dedos melindrosos:\n\nReside em teus costumes a candura,\nMora a firmeza no teu peito amante,\nA razão com teus risos se mistura:\n\nÉs dos céus o composto mais brilhante;\nDeram-se as mãos Virtude e Formosura\nPara criar tua alma, e teu semblante."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 10, «Louvando as graças de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-negra-fera-que-a-tudo-as-garras-lancas": {"t":["Negra fera, que a tudo as garras lanças;\nJá murchaste, insensível a clamores,\nNas faces de Tirsália as rubras flores,\nEm meu peito as viçosas esperanças:\n\nMonstro, que nunca em teus estragos cansas,\nVê as três Graças, vê os nus Amores\nComo praguejam teus cruéis furores,\nFerindo os rostos, arrancando as tranças!\n\nDomicílio da noute, horror sagrado,\nOnde jaz destruída a formosura,\nAbre-te, dá lugar a um desgraçado:\n\nEis desço... eis cinzas palpo... Ah Morte dura!\nAh Tirsália! Ah meu bem, resto adorado!...\nTorna, torna a fechar-te, oh sepultura!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 11, «Sobre a sepultura de Tirsália»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Tirsalia > Tirsália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-pafos-o-menino-ardendo-em-ira": {"t":["De Pafos o menino ardendo em ira,\nPorque uma ingrata as suas leis detesta,\nTão grave insulto despicar protesta,\nE a domar-lhe a altivez, teimoso, aspira:\n\nDormindo encontra a desdenhosa Elmira,\nSobre a mão reclinada a nívea testa:\n«Teu gênio (diz) amansarei com esta\nFarpa sutil» — e do carcás a tira:\n\nMas a bela Acidália, a quem somente\nRende o travesso infante vassalagem,\nLhe aparece, e lhe grita: «Amor, detém-te!\n\n«Tu, filho, que não sofres que me ultrajem,\nElmira vens ferir, irreverente!\nN'ela de tua mãe não vês a imagem?»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 12, «Vênus protege Elmira contra a vingança d'Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-trancas-de-que-amor-prisoes-me-tece": {"t":["Oh tranças, de que Amor prisões me tece,\nOh mãos de neve, que regeis meu fado!\nOh tesouro! oh mistério! oh par sagrado,\nOnde o menino alígero adormece!\n\nOh ledos olhos, cuja luz parece\nTênue raio do sol! Oh gesto amado,\nDe rosas e açucenas semeado,\nPor quem morrera esta alma, se podesse!\n\nOh lábios, cujo riso a paz me tira,\nE por cujos dulcíssimos favores\nTalvez o próprio Júpiter suspira!\n\nOh perfeições! oh dons encantadores!\nDe quem sois?... Sois de Vênus? — É mentira;\nSois de Marília, sois de meus amores."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 13, «Vênus excedida por Marília em formosura»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-se-afastou-de-nos-o-inverno-agreste": {"t":["Já se afastou de nós o Inverno agreste\nEnvolto nos seus úmidos vapores;\nA fértil Primavera, a mãe das flores\nO prado ameno de boninas veste:\n\nVarrendo os ares o sutil Nordeste\nOs torna azuis; as aves de mil cores\nAdejam entre Zéfiros, e Amores,\nE toma o fresco Tejo a cor celeste:\n\nVem, oh Marília, vem lograr comigo\nD'estes alegres campos a beleza,\nD'estas copadas árvores o abrigo:\n\nDeixa louvar da corte a vã grandeza:\nQuanto me agrada mais estar contigo\nNotando as perfeições da Natureza!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 14, «Convite a Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-grato-silencio-tremulo-arvoredo": {"t":["Grato silêncio, trêmulo arvoredo,\nSombra propícia aos crimes, e aos amores,\nHoje serei feliz! — Longe, temores,\nLonge, fantasmas, ilusões do medo.\n\nSabei, amigos Zéfiros, que cedo\nEntre os braços de Nise, entre estas flores\nFurtivas glórias, tácitos favores\nHei de enfim possuir: porém segredo!\n\nNas asas frouxos ais, brandos queixumes\nNão leveis, não façais isto patente,\nQue nem quero que o saiba o pai dos numes:\n\nCale-se o caso a Jove omnipotente,\nPorque se ele o souber, terá ciúmes,\nVibrará contra mim seu raio ardente."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 15, «Esperança amorosa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-temo-que-a-minha-ausencia-e-desventura": {"t":["Temo que a minha ausência e desventura\nVão na tua alma, docemente acesa,\nApoucando os excessos da firmeza,\nRebatendo os assaltos da ternura:\n\nTemo que a tua singular candura\nLeve o Tempo fugaz nas asas presa,\nQue é quase sempre o vício da beleza\nGênio mudável, condição perjura:\n\nTemo; e se o fado mau, fado inimigo,\nConfirmar impiamente este receio,\nSpectro perseguidor, que anda comigo,\n\nCom rosto, alguma vez de mágoa cheio,\nRecorda-te de mim, dize contigo:\n«Era fiel, amava-me, e deixei-o.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 16, «Receios de mudança no objeto amado»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSpectro: aférese de «espectro», como na fonte (o metro a pede), mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-enquanto-o-sabio-arreiga-o-pensamento": {"t":["Enquanto o sábio arreiga o pensamento\nNos fenômenos teus, oh Natureza,\nOu solta árduo problema, ou sobre a mesa\nVolve o sutil geométrico instrumento:\n\nEnquanto, alçando a mais o entendimento,\nEstuda os vastos céus, e com certeza\nReconhece dos astros a grandeza,\nA distância, o lugar, e o movimento:\n\nEnquanto o sábio, enfim, mais sabiamente\nSe remonta nas asas do sentido\nÀ corte do Senhor omnipotente:\n\nEu louco, eu cego, eu mísero, eu perdido\nDe ti só trago cheia, oh Jônia, a mente;\nDo mais, e de mim mesmo ando esquecido."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 17, «Achando-se avassalado pela formosura de Jônia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nArreiga: forma antiga de «arraiga», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aflito-coracao-que-o-teu-tormento": {"t":["Aflito coração, que o teu tormento,\nQue os teus desejos tácito devoras,\nE ao doce objeto, às perfeições que adoras,\nSó te vás explicar c'o pensamento:\n\nInfeliz coração, recobra alento,\nSeca as inúteis lágrimas, que choras;\nTu cevas o teu mal, porque demoras\nOs voos ao ditoso atrevimento.\n\nInflama surdos ais, que o medo esfria;\nUm bem tão suspirado, e tão subido,\nComo se há de ganhar sem ousadia?\n\nAo vencedor afoute-se o vencido;\nLonge o respeito, longe a cobardia;\nMorres de fraco? Morre de atrevido."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 18, «Incitando-se a ganhar pela ousadia a posse da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-por-esta-solidao-que-nao-consente": {"t":["Por esta solidão, que não consente\nNem do sol, nem da lua a claridade,\nRalado o peito já pela saudade\nDou mil gemidos a Marília ausente:\n\nDe seus crimes a mancha inda recente\nLava Amor, e triunfa da verdade;\nA beleza, apesar da falsidade,\nMe ocupa o coração, me ocupa a mente:\n\nLembram-me aqueles olhos tentadores,\nAquelas mãos, aquele riso, aquela\nBoca suave, que respira amores...\n\nAh! Trazei-me, ilusões, a ingrata, a bela!\nPintai-me vós, oh sonhos, entre flores\nSuspirando outra vez nos braços d'ela!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 19, «Recordações de Marília ausente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-marilia-se-em-teus-olhos-atentara": {"t":["Marília, se em teus olhos atentara,\nDo estelífero sólio reluzente\nAo vil mundo outra vez o omnipotente,\nO fulminante Júpiter baixara:\n\nSe o deus, que assanha as Fúrias, te avistara\nAs mãos de neve, o colo transparente,\nSuspirando por ti, do caos ardente\nSurgira à luz do dia, e te roubara:\n\nSe a ver-te de mais perto o sol descera,\nNo áureo carro veloz dando-te assento\nAté da esquiva Dafne se esquecera:\n\nE se a força igualasse o pensamento,\nOh alma da minha alma, eu te ofrecera\nCom ela a terra, o mar, e o firmamento."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 20, «Descrevendo os encantos de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-o-corvo-grasnador-e-o-mocho-feio": {"t":["O corvo grasnador, e o mocho feio\nO sapo berrador, e a rã molesta,\nSão meus únicos sócios na floresta,\nOnde carpindo estou, de angústia cheio;\n\nPerdi todo o prazer, todo o recreio...\nAh malfadado amor, paixão funesta!\nUrselina perdi, nada me resta;\nMadre terra! Agasalha-me em teu seio:\n\nDa víbora mordaz permite, oh Sorte,\nQue nos matos aspérrimos que piso\nAs plantas me envenene o tênue corte!\n\nAh! Que é das graças? Que é do paraíso?\nA minha alma onde está? Quem logra... oh Morte,\nQuem logra de Urselina o doce riso?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 21, «Lamenta solitário a perda da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-guiou-me-ao-templo-do-letal-ciume": {"t":["Guiou-me ao templo do letal Ciúme\nA Desesperação, que em mim fervia;\nO cabelo de horror se me arrepia\nAo recordar o formidável nume:\n\nFumegava-lhe aos pés tartáreo lume,\nCrespa serpe as entranhas lhe roía;\nEram ministros seus a Aleivosia,\nO Susto, a Morte, a Cólera, o Queixume:\n\n«Cruel! (grito em frenético transporte)\nDos sócios teus, no báratro gerados,\nDá-me um só, que te invejo, a Morte, a Morte:\n\n— «Cessa (diz) os teus rogos são baldados:\nQuerem ter-te no mundo Amor, e a Sorte,\nPara consolação dos desgraçados.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 22, «O Templo do Ciúme»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ansias-terriveis-intimos-tormentos": {"t":["Ânsias terríveis, íntimos tormentos,\nNegras imagens, hórridas lembranças,\nAmargosas, mortais desconfianças,\nDeixai-me sossegar alguns momentos:\n\nSofrei que logre os vãos contentamentos\nQue sonham minhas doudas esperanças;\nA posse de alvo rosto, e louras tranças,\nOnde presos estão meus pensamentos:\n\nDeixai-me confiar na formosura,\nCruéis! Deixai-me crer n'um doce engano,\nBlasonar de fantástica ventura.\n\nQue mais mal me quereis, que maior dano\nDo que vagar nas trevas da loucura,\nAborrecendo a luz do desengano?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 23, «Pungido da realidade, procura alívio nas ilusões»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-olha-marilia-as-flautas-dos-pastores": {"t":["Olha, Marília, as flautas dos pastores\nQue bem que soam, como estão cadentes!\nOlha o Tejo a sorrir-se! Olha, não sentes\nOs Zéfiros brincar por entre as flores?\n\nVê como ali beijando-se os Amores\nIncitam nossos ósculos ardentes!\nEi-las de planta em planta as inocentes,\nAs vagas borboletas de mil cores!\n\nN'aquele arbusto o rouxinol suspira,\nOra nas folhas a abelhinha para,\nOra nos ares sussurrando gira:\n\nQue alegre campo! Que manhã tão clara!\nMas ah! Tudo o que vês, se eu te não vira,\nMais tristeza que a morte me causara."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 24, «Recreios campestres na companhia de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-fiei-me-nos-sorrisos-da-ventura": {"t":["Fiei-me nos sorrisos da ventura,\nEm mimos feminis, como fui louco!\nVi raiar o prazer; porém tão pouco\nMomentâneo relâmpago não dura:\n\nNo meio agora d'esta selva escura,\nDentro d'este penedo úmido e ouco,\nPareço, até no tom lúgubre, e rouco\nTriste sombra a carpir na sepultura:\n\nQue estância para mim tão própria é esta!\nCausais-me um doce, e fúnebre transporte,\nÁridos matos, lôbrega floresta!\n\nAh! não me roubou tudo a negra sorte:\nInda tenho este abrigo, inda me resta\nO pranto, a queixa, a solidão e a morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 25, «Desenganado do Amor, e da Fortuna»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nOuco: forma antiga de «oco» (rima com louco, pouco, rouco), mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-arde-em-vao-por-elisa-em-vao-porfia": {"t":["Arde em vão por Elisa, em vão porfia\nContra a constância da heroína augusta\nO bárbaro senhor d'África adusta.\nQue do sangue de Jove se gloria:\n\nEm vão lhe ofrece a vasta monarquia,\nAonde a espádua atlântica robusta\nSustenta os céus, o caminhante assusta,\nE hórridos monstros indomáveis cria:\n\nNão cede Elisa; e vendo que furioso\nUsa da força o líbico tirano,\nEla intrépida escolhe um fim glorioso.\n\nMentes, mentes, injusto mantuano!\nDido infeliz foi vítima do esposo,\nFoi vítima da fé, não do troiano."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 26, «À constância de Dido»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ha-pouco-a-mae-das-gracas-dos-amores": {"t":["Há pouco a mãe das Graças, dos Amores,\nGerada pela espuma cristalina,\nBaixou da etérea região divina\nNas asas dos Favônios voadores:\n\n«Oh das margens do Tejo habitadores!\nHoje torna a luzir (disse Ericina)\nO ledo instante em que nasceu Marina,\nÍnclito fruto de ínclitos maiores:\n\n«Do céu, do mar, da terra os soberanos\nImprimindo-lhe encantos a milhares,\nCriaram n'ela a glória dos humanos:\n\n«Eia, cantai-lhe os dotes singulares,\nLouvai seus olhos, aplaudi seus anos,\nQueimai-lhe aromas, erigi-lhe altares."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 27, «Aos anos da senhora D. Maria Joaquina de Melo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-a-teus-mimosos-pes-meu-bem-rendido": {"t":["A teus mimosos pés, meu bem, rendido,\nConfirmo os votos, que a traição manchara;\nFumam de novo incensos sobre a ara,\nQue a vil ingratidão tinha abatido:\n\nDe novo sobre as asas de um gemido\nTe ofreço o coração, que te agravara;\nSaudoso torno a ti, qual torna à cara\nPerdida pátria o mísero banido:\n\nRenovemos o nó por mim desfeito,\nQue eu já maldigo o tempo desgraçado\nEm que a teus olhos não vivi sujeito;\n\nConcede-me outra vez o antigo agrado;\nQue mais queres? Eu choro, e no meu peito\nO punhal do remorso está cravado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 28, «Volvendo a amar de novo uma dama desprezada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-os-suaves-efluvios-que-respira": {"t":["Os suaves eflúvios, que respira\nA flor de Vênus, a melhor das flores,\nExalas de teus lábios tentadores,\nOh doce, oh bela, oh desejada Elmira;\n\nA que nasceu das ondas, se te vira,\nA seu pesar cantara os teus louvores;\nDitoso quem por ti morre d'amores!\nDitoso quem por ti, meu bem, suspira!\n\nE mil vezes ditoso o que merece\nUm teu furtivo olhar, um teu sorriso,\nPor quem da mãe formosa Amor se esquece!\n\nO sacrílego ateu, sem lei, sem siso,\nContemple-te uma vez, que então conhece\nQue é força haver um Deus, e um paraíso."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 29, «Celebra as graças de Elmira»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-esses-tesouros-esses-bens-sagrados": {"t":["Esses tesouros, esses bens sagrados\nPara os cegos mortais, bens de que abunda\nÁsia guerreira, América fecunda,\nFilhos da terra, pelo sol gerados:\n\nHonras, grandezas, títulos inchados\nServil incenso, adulação jocunda,\nNão quero, não, que sobre mim difunda\nAmiga destra de risonhos Fados:\n\nQuero que as Fúrias hórridas m'escoltem,\nQuero que contra mim, que em vão deliro,\nOs racionais e irracionais se voltem:\n\nQuero da morte o formidável tiro,\nContanto, oh Jônia, que meus lábios soltem\nN'esses teus lábios o final suspiro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 30, «Antepõe o amor de Jônia às honras e riquezas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-meu-fragil-coracao-para-que-adoras": {"t":["Meu frágil coração, para que adoras,\nPara que adoras, se não tens ventura?\nSe uns olhos, de quem ardes na luz pura,\nFolgando estão das lágrimas que choras?\n\nOs dias vês fugir, voar as horas\nSem achar n'eles visos de ternura;\nE inda a louca esperança te figura\nO prêmio dos martírios, que devoras!\n\nDesfaze as trevas de um funesto engano,\nQue não hás de vencer a inimizade\nDe um gênio contra ti sempre tirano:\n\nA justa, a sacrossanta divindade\nNão força, não violenta o peito humano,\nE queres constranger-lhe a liberdade?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 31, «Consolações na tirania de uma ingrata»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-os-garcos-olhos-em-que-amor-brincava": {"t":["Os garços olhos, em que Amor brincava,\nOs rubros lábios, em que Amor se ria,\nAs longas tranças, de que Amor pendia,\nAs lindas faces, onde Amor brilhava:\n\nAs melindrosas mãos, que Amor beijava,\nOs níveos braços, onde Amor dormia,\nForam dados, Armânia, à terra fria.\nPelo fatal poder que a tudo agrava:\n\nSeguiu-te Amor ao tácito jazigo,\nEntre as irmãs cubertas de amargura;\nE eu que faço (ai de mim!) como os não sigo!\n\nQue há no mundo que ver, se a formosura,\nSe Amor, se as Graças, se o prazer contigo\nJazem no eterno horror da sepultura?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 32, «À morte de uma formosa dama»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Armania > Armânia.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-disfarces-marilia-por-josino": {"t":["Não disfarces, Marília; por Josino\nJá nos teus olhos a paixão flameja;\nE em que parte estará, que se não veja\nO tenro deus, o alígero menino?\n\nInda que ostentes de ânimo ferino,\nHá quem teu níveo peito abrase, e reja;\nPorém, Marília, dize-me qual seja\nA causa justa de um amor tão fino?\n\nN'esse, que as esquivanças te suaviza,\nEncontras uma fervida ternura,\nUm coração brioso, uma alma lisa?\n\nSeus méritos quais são?... Mas oh loucura!\nQuem é feliz, que méritos precisa?\nQue dons há de mister quem tem ventura?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 33, «Queixumes contra um rival preferido»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-urselina-gentil-benigna-e-pura": {"t":["Urselina gentil, benigna, e pura,\nEis nas asas sutis de um ai cansado\nA ti meu coração voa alagado\nEm torrentes de sangue, e de ternura:\n\nPõe-lhe os olhos, meu bem; vê com brandura\nSeu miserável, doloroso estado;\nQue nas garras da morte já cravado\nA fé, que te jurava, inda te jura:\n\nPõe-lhe os olhos, meu bem, suavemente,\nPõe-lhe os mimosos dedos na ferida,\nPalpa de Amor a vítima inocente:\n\nE por milagre d'eles, oh querida,\nVerás cerrar-se o golpe, e de repente\nEm ondas de prazer tornar-lhe a vida."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 34, «A Urselina distante»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-veneno-letifero-nadando": {"t":["Em veneno letífero nadando\nNo roto peito o coração me arqueja;\nE ante meus olhos hórrido negreja\nDe mortais aflições espesso bando:\n\nPor ti, Marília, ardendo, e delirando\nEntre as garras aspérrimas da Inveja,\nAmaldiçoo Amor, que ri, e adeja\nPelos ares, c'os Zéfiros brincando:\n\nRecreia-se o traidor com meus clamores, —\nE meu cioso pranto... oh Jove, oh nume\nQue vibras os coriscos vingadores!\n\nAbafa as ondas do tartáreo lume,\nQue para os que provocam teus furores\nTens inferno pior, tens o ciúme."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 35, «Queixas contra a ingratidão de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-do-arbusto-oh-nise-a-venus-consagrado": {"t":["Do arbusto, oh Nise, a Vênus consagrado\nEnvisquei hoje um trêmulo raminho;\nPousou n'ele este incauto passarinho,\nE pelos tenros pés ficou pegado:\n\nEntão, depois de o ter na mão fechado,\nCorri, dizendo alegre: — Eu adivinho\nQue há de Nise estimar, que o meu carinho\nLhe dedique este músico do prado.\n\nDisse; e no mesmo instante a simples ave\nDesata a linda voz, e principia\nUm canto harmonioso, agudo, e grave:\n\nAh! Por ser tua, entendo que dizia\nQue a prisão mais gostosa, e mais suave\nQue a própria liberdade encontraria!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 36, «Oferenda a Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-retrato-da-morte-oh-noute-amiga": {"t":["Oh retrato da morte, oh Noute amiga\nPor cuja escuridão suspiro há tanto!\nCalada testemunha de meu pranto,\nDe meus desgostos secretária antiga!\n\nPois manda Amor, que a ti somente os diga,\nDá-lhes pio agasalho no teu manto;\nOuve-os, como costumas, ouve, enquanto\nDorme a cruel, que a delirar me obriga:\n\nE vós, oh cortesãos da escuridade,\nFantasmas vagos, mochos piadores,\nInimigos, como eu, da claridade!\n\nEm bandos acudi aos meus clamores;\nQuero a vossa medonha sociedade,\nQuero fartar meu coração de horrores."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 37, «Insônia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vinde-prazeres-que-por-entre-as-flores": {"t":["Vinde, Prazeres, que por entre as flores\nNos jardins de Citera andais brincando,\nE vós, despidas Graças, que dançando\nTrinais alegres sons encantadores:\n\nDeusa dos gostos, deusa dos amores,\nAh! dos filhinhos teus ajunta o bando,\nE vem nas asas de Favônio brando\nDar força, dar beleza a meus louvores.\n\nDa linda Anarda minha voz aspira\nA cantar o natal; tu, por clemência,\nO teu fiel cantor, deidade, inspira:\n\nDo trácio vate empresta-me a cadência,\nE faze que mereça a minha lira\nOs cândidos sorrisos da inocência."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 38, «Festejando o dia natalício de Anarda»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-canta-ao-som-dos-grilhoes-o-prisioneiro": {"t":["Canta ao som dos grilhões o prisioneiro,\nAo som da tempestade o nauta ousado,\nUm, porque espera o fim do cativeiro,\nOutro, antevendo o porto desejado:\n\nExposta a vida ao tigre mosqueado\nGira sertões o sôfrego mineiro,\nDa esperança dos lucros encantado,\nQue anima o peito vil, e interesseiro:\n\nPor entre armadas hostes destemido\nRompe o sequaz do horrífico Mavorte,\nC'o triunfo, co'a glória no sentido:\n\nSó eu (tirano Amor! tirana sorte!)\nSó eu por Nise ingrata aborrecido\nPara ter fim meu pranto espero a morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 39, «Lastimando-se da ingratidão de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB BABA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-entre-as-tartareas-forjas-sempre-acesas": {"t":["Entre as tartáreas forjas, sempre acesas,\nJaz aos pés do tremendo, estígio nume,\nO carrancudo, o rábido Ciúme,\nEnsanguentadas as corruptas presas:\n\nTraçando o plano de cruéis empresas,\nFervendo em ondas de sulfúreo lume,\nVibra das fauces o letal cardume\nDe hórridos males, de hórridas tristezas;\n\nPelas terríveis Fúrias instigado\nLá sai do inferno, e para mim se avança\nO negro monstro, de áspides toucado:\n\nOlhos em brasa de revés me lança;\nOh dor! Oh raiva! Oh morte!... Ei-lo a meu lado,\nFerrando as garras na vipérea trança."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 40, «O Ciúme»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-pela-porta-de-ferro-onde-ululando": {"t":["Pela porta de ferro, onde ululando\nO cão trifauce está perpetuamente\nEntraste, Orfeu, co'a cítara eloquente\nOs monstros infernais domesticando:\n\nPenedos com teus sons amontoando\nLá ergues Tebas, Anfion cadente;\nPulsa Arion a lira, e de repente\nVê delfins, vê tritões no mar dançando:\n\nTu, linguagem do céu, tu, melodia,\nA tudo encantas, para tudo és forte,\nMenos para aplacar a ingrata Armia:\n\nMais fácil te há de ser, domando a sorte,\nIr de novo à tartárea monarquia\nVer outra vez o cárcere da morte!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 41, «A esquivança de Armia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nAmphion > Anfion (grafia atualizada do nome, como em «Anfião»).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-triste-quem-ama-cego-quem-se-fia": {"t":["Triste quem ama, cego quem se fia\nDa feminina voz na vã promessa!\nAspira a vê-la estável! Mais depressa\nO facho apagará, que espalha o dia:\n\nAlada exalação, que na sombria\nTácita noute os ares atravessa,\nFoi comigo a paixão volúvel d'essa\nQue o peito me afagava, e me feria:\n\nDo desengano o bálsamo lhe aplico,\nE a teus laços, Amor, sem medo exponho\nDos benéficos céus o dom mais rico:\n\nVejo mil Circes plácido, risonho;\nE se fé me prometem, ouço, e fico\nComo quem despertou de aéreo sonho."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 42, «Desengano de Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-busquei-n-um-ermo-algania-feiticeira": {"t":["Busquei n'um ermo Algânia feiticeira,\nQue de abrasado feixe a par jazia;\nFui ver se atro conjuro me extorquia\nDo laço antigo esta alma prisioneira:\n\nExpus-lhe minha fé, minha cegueira,\nTracei meus males, e a rugosa estria\nCedendo às ternas mágoas, que me ouvia,\nCuspiu três vezes na voraz fogueira:\n\nTrêmulas preces murmurou, e eu mudo;\nEis que as melenas em sinal d'espanto\nEriça com semblante carrancudo:\n\n«Meu rito é vão (me diz) e é vão teu pranto;\nO poderoso Amor zomba de tudo,\nNão vence encanto algum d'Amor o encanto.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 43, «Amor triunfando da Magia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Algania > Algânia.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-importuna-razao-nao-me-persigas": {"t":["Importuna Razão, não me persigas;\nCesse a ríspida voz que em vão murmura;\nSe a lei de Amor, se a força da ternura\nNem domas, nem contrastas, nem mitigas:\n\nSe acusas os mortais, e os não abrigas,\nSe (conhecendo o mal) não dás a cura,\nDeixa-me apreciar minha loucura,\nImportuna Razão, não me persigas.\n\nÉ teu fim, teu projeto encher de pejo\nEsta alma, frágil vítima d'aquela\nQue, injusta e vária, n'outros laços vejo:\n\nQueres que fuja de Marília bela,\nQue a maldiga, a desdenhe; e o meu desejo\nÉ carpir, delirar, morrer por ela."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 44, «A Razão dominada pela Formosura»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 13: a ed. de 1875 traz «desdenho»; adotada a lição «desdenhe» da ed. de 1853 (paralela a «maldiga»).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-trevas-que-enlutais-a-natureza": {"t":["Oh trevas, que enlutais a natureza,\nLongos ciprestes d'esta selva anosa,\nMochos de voz sinistra, e lamentosa,\nQue dissolveis dos fados a incerteza:\n\nManes, surgidos da morada acesa\nOnde de horror sem fim Plutão se goza,\nNão aterreis esta alma dolorosa,\nQue é mais triste que vós minha tristeza:\n\nPerdi o galardão da fé mais pura,\nEsperanças frustrei do amor mais terno,\nA posse de celeste formosura:\n\nVolvei pois, sombras vãs, ao fogo eterno;\nE lamentando a minha desventura\nMovereis a piedade o mesmo inferno."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 45, «Queixumes contra os desprezos da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-no-carro-de-marfim-sentada-a-lua": {"t":["No carro de marfim sentada a Lua\nDa antiga mãe das sombras triunfava,\nQuando a furtivos gostos me guiava\nAmor, a quem me entrega a sorte crua:\n\n«Hoje (me disse o nume) há de ser tua\nA ninfa mais gentil, que o Tejo lava;\nNão deram tanta glória à minha aljava\nNem Vênus a carpir, nem Tétis nua:\n\n«Ali dorme o teu bem... vê, que momento!...»\nOlho, corro anelante, aos pés lhe caio,\nMas tentando abraçá-la, abraço o vento:\n\nMeu peito arqueja em súbito desmaio;\nEis que soa esta voz de horrendo acento:\n«Profano! Expia o crime, e teme o raio!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 46, «Visão amorosa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-inda-em-meu-fragil-coracao-fumega": {"t":["Inda em meu frágil coração fumega\nA cinza d'esse fogo em que ele ardia;\nA memória da tua aleivosia\nMeu sossego inda aqui desassossega:\n\nA vil traição, que as almas nos despega,\nNão tem cabal poder na simpatia;\nGasta o mar importuno a rocha fria,\nMelhor que o desengano a paixão cega:\n\nBem como o flavo sol, que a terra abraça,\nPor mais que o veja densamente oposto,\nAtraído vapor fere, e repassa:\n\nTal, para misturar gosto e desgosto,\nNa sombra de teus crimes brilha a graça,\nCom que o pródigo céu criou teu rosto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 47, «Recordações de uma ingrata»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-o-inverno-espremendo-as-cans-nevosas": {"t":["Já o Inverno, espremendo as cans nevosas,\nGeme, de horrendas nuvens carregado;\nLuz o aéreo fuzil, e o mar inchado\nInveste ao polo em serras escumosas;\n\nOh benignas manhãs! tardes saudosas,\nEm que folga o pastor, medrando o gado,\nEm que brincam no ervoso e fértil prado\nNinfas, e Amores, Zéfiros e Rosas!\n\nVoltai, retrocedei, formosos dias:\nOu antes vem, vem tu, doce beleza\nQue n'outros campos mil prazeres crias;\n\nE ao ver-te sentirá minha alma acesa\nOs perfumes, o encanto, as alegrias\nDa estação, que remoça a natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 48, «Desejos da presença do objeto amado»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-mimosa-linda-anarda-atende-atende": {"t":["Mimosa, linda Anarda, atende, atende\nÀs doces mágoas do rendido Elmano;\nCo'um meigo riso, co'um suave engano\nConsola o triste amor, que não te ofende:\n\nDe teus cabelos ondeados pende\nMeu coração, fiel para seu dano;\nCo'a luz dos olhos teus Cupido ufano\nSustenta o puro fogo, em que me acende:\n\nCausa gentil das lágrimas que choro,\nA tudo te antepõe minha ternura,\nE quanto adoro o céu, teu rosto adoro:\n\nO golpe, que me deste, amima e cura...\nMas ai! Que em vão suspiro, em vão te imploro:\nNão pertence a piedade à formosura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 49, «Conjuros a Anarda, para que retribua o seu amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-meus-olhos-atentai-no-meu-jazigo": {"t":["Meus olhos, atentai no meu jazigo,\nQue o momento da morte está chegado;\nLá soa o corvo, intérprete do fado;\nBem o entendo, bem sei, fala comigo:\n\nTriunfa, Amor, glória-te inimigo;\nE tu, que vês com dor meu duro estado,\nVolve à terra o cadáver macerado,\nO despojo mortal do triste amigo:\n\nNa campa, que o cubrir, piedoso Albano,\nMinistra aos corações, que Amor flagela,\nTerror, piedade, aviso, e desengano:\n\nAbre em meu nome este epitáfio n'ela:\n«Eu fui, ternos mortais, o terno Elmano;\nMorri d'ingratidões, matou-me Isbela.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 50, «Delírio amoroso»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-no-calado-monumento-escuro": {"t":["Já no calado monumento escuro\nEm cinzas se desfez teu corpo brando;\nE pude eu ver, oh Nise, o doce, o puro\nLume dos olhos teus ir-se apagando!\n\nHórridas brenhas, solidões procuro,\nGrutas sem luz frenético demando,\nOnde maldigo o fado acerbo e duro,\nTeu riso, teus afagos suspirando:\n\nDarei da minha dor contínua prova,\nEm sombras cevarei minha saudade,\nInsaciável sempre, e sempre nova:\n\nTé que torne a gozar da claridade\nDa luz, que me inflamou, que se renova\nNo seio da brilhante eternidade."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 51, «Deplorando a morte de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oleno-meia-noute-esta-caindo": {"t":["Oleno, meia-noute está caindo:\nAcende a vela azul, queima as verbenas,\nTorra os ossos de rã, chamusca as penas\nDa esquerda gralha, que apanhei dormindo:\n\nC'o pé, co'a vara o ar, e o chão ferindo\nEnquanto o filtro portentoso ordenas,\nEu irei, e a meu brado ouvido apenas\nVirão do inferno as Górgonas surgindo:\n\nEia, avante o prestígio, não cessemos\nDa irresistível mágica porfia,\nContra quem vê sem dó nossos extremos;\n\nQue se hoje o fel tragamos da agonia,\nAmanhã doce néctar libaremos\nTu nos braços de Nise, eu nos de Armia."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 52, «Emprega o poder da magia para domar a resistência da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vai-te-fera-cruel-vai-te-inimiga": {"t":["Vai-te, fera cruel, vai-te, inimiga,\nHorror do mundo, escândalo da gente,\nQue um férreo peito, uma alma que não sente,\nNão merece a paixão, que me afadiga:\n\nO céu te falte, a terra te persiga,\nNegras fúrias o inferno te apresente,\nE da baça tristeza o voraz dente\nMorda o vil coração, que Amor não liga:\n\nDisfarçados, mortíferos venenos\nEntre liquor suave em áurea taça\nMão vingativa te prepare ao menos:\n\nE seja, seja tal tua desgraça,\nQue ainda por mais leves, mais pequenos\nOs meus tormentos invejar te faça."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 53, «Imprecações contra uma ingrata (Improvisado)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-temas-oh-ritalia-que-o-choroso": {"t":["Não temas, oh Ritália, que o choroso,\nO desvelado Elmano a fé quebrante,\nNão desconfies do singelo amante,\nQue tu podes, tu só, fazer ditoso:\n\nSerena o coração terno e cioso,\nQue inda minh'alma te há de ser constante\nSe, primeiro que a tua, andar errante\nPelas margens do Letes preguiçoso:\n\nN'aquela ao sol inaccessível parte,\nDos manes taciturnos entre o bando\nAo negro esquecimento hei de furtar-te:\n\nE o pensamento alígero voando\nPor abafados ares, visitar-te\nD'ali virá, meu bem, de quando em quando."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 54, «Protestos de constância eterna»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Ritalia > Ritália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-deusa-que-proteges-dos-amantes": {"t":["Oh deusa, que proteges dos amantes\nO destro Furto, o crime deleitoso,\nAbafa com teu manto pavoroso\nOs importunos astros vigilantes:\n\nQuero adoçar meus lábios anelantes\nNo seio de Ritália melindroso;\nEstorva que os maus olhos do invejoso\nTurbem d'amor os sôfregos instantes:\n\nTétis formosa, tal encanto inspire\nAo namorado sol teu níveo rosto,\nQue nunca de teus braços se retire!\n\nTarde ao menos o carro à Noute oposto,\nAté que eu desfaleça, até que expire\nNas ternas ânsias, no inefável gosto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 55, «Invocação à Noute»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Ritalia > Ritália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aquela-que-na-esfera-luminosa": {"t":["Aquela, que na esfera luminosa\nPrecedendo a manhã, qual astro brilha,\nMãe dos Amores, das espumas filha,\nQue o mar na concha azul passeia airosa:\n\nApenas viu sorrir Nise formosa,\nA quem dos corações o deus se humilha,\nDo cinto desatando a áurea presilha,\nNo regaço lh'o pôs, leda e mimosa:\n\n«Não te é, bem sei (lhe diz) não te é preciso;\nPara atrair vontades à ternura\nBasta-te um gesto, basta-te um sorriso:\n\n«Mas deves possuí-lo, oh ninfa pura,\nComo troféu, que dê ao mundo aviso\nDe que Vênus te cede em formosura.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 56, «Vênus reconhecendo a superioridade da beleza de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sonhei-que-a-mim-correndo-o-gnideo-nume": {"t":["Sonhei que a mim correndo o gnídeo nume\nVinha co'a Morte, c'o Ciúme ao lado,\nE me bradava: — «Escolhe, desgraçado,\nQueres a Morte, ou queres o Ciúme?\n\n«Não é pior d'aquela fouce o gume,\nQue a ponta dos farpões, que tens provado;\nMas o monstro voraz, por mim criado,\nQuanto horror há no inferno em si resume.»\n\nDisse; — e eu dando um suspiro: «Ah! não m'espantes\nCo'a vista d'essa fúria!... Amor, clemência!\nAntes mil mortes, mil infernos antes!»\n\nN'isto acordei com dor, com impaciência;\nE não vos encontrando, olhos brilhantes,\nVi que era a minha morte a vossa ausência!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 57, «Visão realizada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-ceus-que-sinto-n-alma-que-tormento": {"t":["Oh céus! Que sinto n'alma! Que tormento!\nQue repentino frenesi me anseia!\nQue veneno a ferver de veia em veia\nMe gasta a vida, me desfaz o alento!\n\nTal era, doce amada, o meu lamento;\nEis que esse deus, que em prantos se recreia,\nMe diz: — «A que se expõe quem não receia\nContemplar Urselina um só momento!\n\n«Insano! Eu bem te vi d'entre a luz pura\nDe seus olhos travessos, e co'um tiro\nPuni tua sacrílega loucura:\n\n«De morte, por piedade hoje te firo;\nVai pois, vai merecer na sepultura\nÀ tua linda ingrata algum suspiro.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 58, «O poeta asseteado por Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-da-minha-ingrata-flerida-gentil": {"t":["Da minha ingrata Flérida gentil\nOs verdes olhos esmeraldas são;\nÉ de cândida prata a lisa mão,\nOnde eu d'um beijo passaria a mil:\n\nA trança, cor do sol, rede sutil\nEm que se foi prender meu coração,\nÉ d'ouro, o pai da túmida ambição,\nProle fatal do cálido Brasil:\n\nSeu peito delicado e tentador\nÉ porção de alabastro, a quem jamais\nPenetraram farpões do deus traidor:\n\nMas como há de a tirana ouvir meus ais,\nComo há de esta cruel sentir amor,\nSe é composta de pedras, e metais!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 59, «Retrato de uma formosura esquiva (Improvisado)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tragado-o-peito-de-crueis-pesares": {"t":["Tragado o peito de cruéis pesares,\nEm doloroso e rábido transporte,\nContra Amor, de quem pende a minha sorte,\nVoavam meus queixumes a milhares:\n\nEis que, desde os azuis serenos ares,\nMe grita o deus: — «Tua alma se conforte,\nQue nem sempre o Furor, o Estrago, a Morte\nMinistros hão de ser dos meus altares:\n\n«Aquela paz, aquele gosto, aquela\nVentura, que até agora te hei negado,\nGuardei nos olhos de Ritália bela.»\n\nDisse, e limpando o rosto amargurado,\nCorro da ninfa aos pés, encontro n'ela\nQuanto Amor pode dar, e o Céu, e o Fado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 60, «Predição cumprida»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Ritalia > Ritália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-desprega-as-asas-timida-esperanca": {"t":["Desprega as asas, tímida Esperança,\nMinha consolação, não desanimes:\nAdeja, voa; os cultos não são crimes,\nNem Jove a quem o adora os raios lança:\n\nCom ais de um coração que não descansa,\nTerno, benigno dó vai ver se imprimes\nNa formosa Urselina, ou se reprimes\nTênue porção de ríspida esquivança:\n\nChorosas preces, trêmulo respeito\nExercita com ela, e tu, mimoso\nCândido Amor, que escravo me tens feito,\n\nPara adoçar-lhe o gênio desdenhoso\nDeixa-lhe os olhos, salta-lhe no peito,\nNão perdes nada, e fazes-me ditoso."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 61, «Pretendendo abrandar a esquivança de Urselina»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nise-das-gracas-e-de-amor-tesouro": {"t":["Nise, das Graças e de Amor tesouro,\nVoto implorado me firmava um dia,\nNa face meiga a cândida alegria,\nAos ventos derramada a trança d'ouro:\n\nEis que junto de nós ave de agouro\nTrês vezes esvoaça, pousa, e pia;\nOs ares prenhe sombra enluta, esfria,\nE o raio estragador cai sobre um louro.\n\nNo repentino horror, que a cena altera,\nQuereria talvez dizer-me o fado\nQue não tinha o meu bem alma sincera?\n\nAh! Só quis persuadir um desgraçado\nQue de o felicitar capaz não era\nNem a glória de ser por Nise amado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 62, «Desesperança»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-que-estado-meu-bem-por-ti-me-vejo": {"t":["Em que estado, meu bem, por ti me vejo,\nEm que estado infeliz, penoso, e duro!\nDelido o coração de um fogo impuro,\nMeus pesados grilhões adoro e beijo:\n\nQuando te logro mais, mais te desejo,\nQuando te encontro mais, mais te procuro,\nQuando m'o juras mais, menos seguro\nJulgo esse doce amor, que adorna o pejo,\n\nAssim passo, assim vivo, assim meus fados\nMe desarreigam d'alma a paz, e o riso,\nSendo só meu sustento os meus cuidados:\n\nE, de todo apagada a luz do siso,\nEsquecem-me (ai de mim!) por teus agrados\n«Morte, Juízo, Inferno e Paraíso.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 63, «Glosando o mote: «Morte, Juízo, Inferno e Paraíso»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nDesarreigam: forma antiga de «desarraigam», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-eu-deliro-gertruria-eu-desespero": {"t":["Eu deliro, Gertrúria, eu desespero\nNo inferno de suspeitas e temores;\nEu da morte as angústias, e os horrores\nPor ti mil vezes sem morrer tolero:\n\nPelo céu, por teus olhos te assevero\nQue ferve esta alma em cândidos amores;\nLonge o prazer de ilícitos favores!\nQuero o teu coração, mais nada quero.\n\nAh! Não sejas também qual é comigo\nA cega divindade, a Sorte dura,\nA vária deusa, que me nega abrigo!\n\nTudo perdi; mas valha-me a ternura,\nAmor me valha, e pague-me contigo\n«Os roubos, que me fez a má ventura.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 64, «Glosando o mote: «Os roubos, que me fez a má ventura»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-o-ledo-passarinho-que-gorjeia": {"t":["O ledo passarinho, que gorjeia\nD'alma exprimindo a cândida ternura,\nO rio transparente, que murmura,\nE por entre pedrinhas serpenteia:\n\nO sol, que o céu diáfano passeia,\nA lua, que lhe deve a formosura,\nO sorriso da aurora alegre e pura,\nA rosa, que entre os zéfiros ondeia:\n\nA serena, amorosa primavera,\nO doce autor das glórias que consigo,\nA deusa das paixões, e de Citera:\n\nQuanto digo, meu bem, quanto não digo,\nTudo em tua presença degenera,\n«Nada se pode comparar contigo.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 65, «Glosando o mote: «Nada se pode comparar contigo»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-terra-onde-os-seus-dons-os-seus-favores": {"t":["Oh terra, onde os seus dons, os seus favores\nDerrama de áureo cofre a Natureza,\nQue na estação de gelo, e da tristeza\nBorda teus prados de verdura, e flores:\n\nOh clima dos heróis, e dos amores,\nEsmalte e perfeição da redondeza,\nTu, que abrigas em ti tanta beleza,\nTantos olhos gentis, e encantadores:\n\nTu, que do grego errante e cauteloso,\nDa mão que ao nada reduziu Dardânia,\nTens em teus campos monumento honroso:\n\nD'eles todos, oh pátria, oh Lusitânia,\nO do Tejo é mais ledo, é mais viçoso;\nGraças ao riso da celeste Armânia."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 66, «Encarecendo as perfeições d'Armânia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Armania > Armânia.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-perverso-estragador-da-formosura": {"t":["Perverso estragador da formosura,\nAlma corrupta, desleal, impia,\nOnde interesse, amor, e aleivosia\nJazem com feia, e sórdida mistura:\n\nO fruto que produz tua ternura\nSão (que assombro!) a vileza, a tirania;\nSacrificas a tua idolatria\nCom tuas próprias mãos em ara impura:\n\nQue bruto coração, que torpe amante\nVende o seu gosto? Ah mísera beleza,\nEu te choro, eu te choro, outrem te cante:\n\nExcedeu-se em formar-te a Natureza;\nDivina te julguei pelo semblante,\nHumana vejo que és pela fraqueza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 67, «Convícios a um sedutor interesseiro, e a uma beleza ingrata»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nImpía (1875) marca a pronúncia grave (im-pí-a); mantida na grafia atual «impia».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vendo-o-soberbo-amor-que-eu-resistia": {"t":["Vendo o soberbo Amor, que eu resistia\nAo seu poder com ânimo arrogante,\nMostrou-me um doce, angélico semblante,\nQue a própria Vênus invejar devia:\n\nMinha néscia altivez, minha ousadia\nEm submissão troquei no mesmo instante;\nE o deus tirano, achando-se triunfante,\nCom voz insultadora me dizia:\n\n«Tu, que escapar às minhas setas queres,\nVil mortal, satisfaze o teu desejo,\nVê, vê Corina, e foge, se poderes.»\n\n«Amor, (lhe respondi) rendido a vejo;\nAdoro os olhos seus, com que me feres,\nVenero as tuas leis, teus ferros beijo.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 68, «O poeta avassalado pelos olhos de Corina»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-honroso-louro-o-capitao-valente": {"t":["Honroso louro o capitão valente\nGanhe embora na fervida peleja;\nSeu nome a fama espalhe, e geralmente\nCom pasmo, e com respeito ouvido seja:\n\nEmbora o torpe avaro, o vil demente,\nQue para os ferrolhar mil bens deseja,\nDe ricas peças de metal fulgente\nSeus amplos cofres atulhados veja:\n\nEmbora de lisonjas incensado\nTenha o monarca às suas leis sujeito\nO povo mais feliz, mais afamado:\n\nQue a mim, para que viva satisfeito,\nMe basta possuir teu doce agrado,\nTer lugar, oh Marília, no teu peito."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 69, «Prefere aos bens do mundo os agrados de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-deitado-sobre-a-relva-amor-estava": {"t":["Deitado sobre a relva Amor estava\nDormindo ao pé d'uma árvore sombria,\nE n'um dos troncos pendurado havia\nPrenhe de setas a danosa aljava:\n\nFlora então, que d'isenta blasonava,\nE do infeliz Dorindo escarnecia,\nCom soberba, sacrílega ousadia,\nQuis partir os farpões, que detestava:\n\nMas apenas lhe toca, a mão ferindo\nNo bico de um dos ferros penetrantes,\nGrita, lavado em pranto o gesto lindo:\n\n«Ai de mim! Firme exemplo dos amantes,\nOnde estás? Vem, não temas, vem, Dorindo,\nQue eu já não sou cruel como era d'antes.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 70, «Uma esquivança vencida pelo poder de Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nD'exempta > d'isenta (grafia atual).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-cima-d-estas-penhas-escabrosas": {"t":["De cima d'estas penhas escabrosas,\nQue pouco a pouco as ondas têm minado,\nDa lua c'o reflexo prateado\nDistingo de Marília as mãos formosas:\n\nAh! Que lindas que são, que melindrosas!\nSinto-me louco, sinto-me encantado;\nAh! Quando elas vos colhem lá no prado,\nNem vós, lírios, brilhais, nem vós, oh rosas!\n\nDeuses! Céus! Tudo o mais que tendes feito\nVendo tão belas mãos, me dá desgosto;\nNada, onde elas estão, nada é perfeito.\n\nOh quem podéra uni-las ao meu rosto!\nQuem podéra apertá-las no meu peito!\nDar-lhe mil beijos, e expirar de gosto!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 71, «Às mãos de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-antes-eu-visse-matador-cutelo": {"t":["Antes eu visse matador cutelo\nPor mão ferina contra mim vibrado,\nOu perecesse o peito esmigalhado\nPelos golpes de rígido martelo:\n\nAntes das Fúrias o infernal flagelo\nSentisse, como Orestes malfadado,\nE não das sombras d'aflição turbado\nO céu, Marília, de teu rosto belo!\n\nDas faces orvalhada a neve pura,\nRouca a voz, e na terra a vista presa,\nTe observo, sem que morra d'amargura!\n\nTu d'esta sorte, angelical beleza?\nAi de mim! Quem terá prazer, ventura,\nSe até pode no céu caber tristeza?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 72, «Ao ver o semblante da sua amada anuviado de tristeza»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-emaranhadas-cans-o-rosto-cheio": {"t":["De emaranhadas cans o rosto cheio,\nDe açacalada fouce armado o braço,\nGiganteia estatura, aspecto baço,\nUm velho em sonhos vi, medonho e feio:\n\n«Não tenhas, oh mortal, de mim receio;\nO Tempo sou (me diz) eu despedaço\nOs colossos, os mármores desfaço,\nProstro a vaidade, a formosura afeio:\n\n«Mas sabendo a razão de teus pesares,\nPela primeira vez enternecido,\nA falar-te baixei dos tênues ares:\n\n«Sofre, por ora, o jugo de Cupido;\nQue eu farei, quando menos o cuidares,\nQue te escape Natércia do sentido.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 73, «O Tempo oferece ao poeta seu auxílio contra Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-debalde-um-veu-cioso-oh-nise-encobre": {"t":["Debalde um véu cioso, oh Nise, encobre\nIntactas perfeições ao meu desejo;\nTudo o que escondes, tudo o que não vejo\nA mente audaz e alígera descobre:\n\nPor mais e mais que as sentinelas dobre\nA sisuda Modéstia, o cauto Pejo,\nTeus braços logro, teus encantos beijo,\nPor milagre da ideia afouta, e nobre:\n\nInda que prêmio teu rigor me negue,\nDo pensamento a indômita porfia\nAo mais doce prazer me deixa entregue:\n\nQue pode contra Amor a tirania,\nSe as delícias, que a vista não consegue,\nConsegue a temerária fantasia?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 74, «Gozo fantástico»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-das-faixas-infantis-despido-apenas": {"t":["Das faixas infantis despido apenas,\nSentia o sacro fogo arder na mente;\nMeu tenro coração inda inocente,\nIam ganhando as plácidas Camenas:\n\nFaces gentis, angélicas, serenas,\nDe olhos suaves o volver fulgente,\nDa ideia me extraíam de repente\nMil simples, maviosas cantilenas.\n\nO tempo me soprou fervor divino,\nE as Musas me fizeram desgraçado,\nDesgraçado me fez o deus menino:\n\nA Amor quis esquivar-se, e ao dom sagrado:\nMas vendo no meu gênio o meu destino,\nQue havia de fazer? Cedi ao fado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 75, «Cedendo a seu pesar à violência do Destino»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 12: «esquivar-se» na ed. de 1875; a ed. de 1853 traz «esquivar-me».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-enquanto-muda-jaz-e-jaz-vencida": {"t":["Enquanto muda jaz, e jaz vencida\nDo sono, que a restaura, a Natureza,\nAumento de meus males a graveza,\nEu, desgraçado, que aborreço a vida.\n\nVelando está minha alma escurecida\nEnvolta nos horrores da tristeza,\nQual tocha, que entre túmulos acesa,\nEspalha feia luz amortecida:\n\nVelando está minha alma, estão com ela\nVelando Amor, velando a Desventura,\nAlgozes com que a Sorte me flagela:\n\nPreside ao ato acerbo a formosura,\nMarília desleal, Marília, aquela\nQue tão branda me foi, que me é tão dura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 76, «Queixumes contra a mudança de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-incense-da-fortuna-os-vaos-altares": {"t":["Incense da Fortuna os vãos altares\nDestra venal de astuto lisonjeiro;\nRaios vibrando intrépido guerreiro\nDe nuvens de atro fumo assombre os ares:\n\nDomando a fúria de assanhados mares\nSagaz comerciante interesseiro,\nPejado o bojo do baixel veleiro\nOpulento saúde os pátrios lares:\n\nA deusa, que por bocas cem respira\nAclame o sábio que medita, e vela,\nFértil em produções que o mundo admira:\n\nMinha alma só se apraz, só se desvela\nNa glória de cantar ao som da lira\nOs olhos de Felisa, as graças d'ela."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 77, «As graças de Felisa preferíveis às honras e riquezas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-minha-alma-se-reparte-em-pensamentos": {"t":["Minha alma se reparte em pensamentos\nTodos escuros, todos pavorosos;\nPondero quão terríveis, quão penosos\nSão, existência minha, os teus momentos:\n\nDos males que sofri, cruéis, violentos,\nA Amor, e aos Fados contra mim teimosos,\nOutros inda mais tristes, mais custosos\nDeduzo com fatais pressentimentos.\n\nRasgo o véu do futuro, e lá diviso\nNovos danos urdindo Amor, e os Fados,\nPara roubar-me a vida após do siso.\n\nAh! Vem, Marília, vem com teus agrados,\nCom teu sereno olhar, teu brando riso\nFurtar-me a fantasia a mil cuidados."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 78, «Pede a Marília consolações contra a rudeza dos Fados»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-por-industria-de-uns-olhos-mais-brilhantes": {"t":["Por indústria de uns olhos, mais brilhantes\nQue o refulgente sol dos céus no cume,\nJaz preso entre os grilhões do idálio nume\nO mais terno e sensível dos amantes:\n\nUma ingrata, exemplar das inconstantes,\nPor gênio, por sistema, ou por costume,\nTodo o fel da tristeza, e do ciúme\nLhe verte sobre os míseros instantes:\n\nSe com piedoso afago lhe suaviza,\nLhe engana alguma vez a dor, que o mata,\nMil vezes com desdéns o tiraniza:\n\nO laço aperta, e súbito o desata...\nAh doce encanto meu, gentil Felisa,\nO desgraçado eu sou, tu és a ingrata."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 79, «Queixando-se dos desdéns de uma ingrata»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-sonhos-na-escaldada-fantasia": {"t":["Em sonhos na escaldada fantasia\nVi, que torvo dragão de olhos fogosos\nCom afiados dentes sanguinosos\nAs tépidas entranhas me rompia:\n\nAlva ninfa louçã, que parecia\nA mãe dos Amorinhos melindrosos,\nRaivosa contra mim, c'os pés mimosos\nMais o drago faminto embravecia:\n\nDe mármore a meu pranto, a meu queixume,\nD'este mal, d'este horror sem dó, sem pena,\nVia dos olhos meus sumir-se o lume:\n\nAh! Não foi ilusão tão triste cena:\nO monstro devorante era o Ciúme,\nA cruel, que o pungia, era Filena."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 80, «O Ciúme, e Filena conjurados em dano do poeta»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-doce-nume-d-amor-se-a-bela-armia": {"t":["Doce nume d'amor, se à bela Armia\nConsagrei por teu mando a liberdade,\nDoce nume d'amor, se tens piedade\nDo coração, que Elmano em ais te envia:\n\nEntre o calado horror da noute fria\nA minha amada, a minha divindade,\n(Com seus olhos dourando a escuridade)\nPinta-me em ledo sonho à fantasia:\n\nAssome tão risonha, e tão brilhante\nComo a rósea manhã no céu jocundo,\nE as lágrimas enxugue ao triste amante.\n\nContarei ao meu bem meu mal profundo,\nE que vivo sem ela absorto, errante,\nPerdido, amargurado, e só no mundo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 81, «Anelando ver a imagem da amada ausente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-o-ceu-nao-te-dotou-de-formosura": {"t":["O céu não te dotou de formosura,\nDe atrativo exterior, e a Natureza\nTeu peito inficionou co'a vil torpeza\nDe ingrata condição, falaz, e impura:\n\nInfluiu-me os extremos da ternura\nA constância, o fervor, e a singeleza,\nEsses dons mais gentis que a gentileza,\nDons, que o tempo fugaz não desfigura:\n\nApesar da traição, do fingimento\nQue te infama, e desluz, se enleva e para\nEm ti, alma infiel, meu pensamento:\n\nNas paixões a razão nos desampara;\nSe a razão presidisse ao sentimento,\nTu morreras por mim, eu não te amara."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 82, «A paixão triunfante apesar do raciocínio»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-as-margens-do-regaca-cristalino": {"t":["Às margens do Regaça cristalino\nNos olhos de Tirseia ardi contente,\nBrandos olhos gentis, dos quais pendente\nEstava o meu prazer, e o meu destino:\n\nO tenro deus, o cândido menino\nPagava meu fervor puro, inocente;\nMas cedo me impeliu a sorte inclemente\nPara vós, tristes margens, que abomino:\n\nAqui desde que aponta a luz febeia\nDe lugar em lugar deliro, e corro,\nCom suspeitas nutrindo a turva ideia.\n\nNão posso contra Amor achar socorro;\nPerdi todo o meu bem, perdi Tirseia,\nEla vive sem mim, sem ela eu morro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 83, «Na ausência de Tirseia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Tirséa > Tirseia.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sobre-estas-duras-cavernosas-fragas": {"t":["Sobre estas duras, cavernosas fragas,\nQue o marinho furor vai carcomendo,\nMe estão negras paixões n'alma fervendo\nComo fervem no pego as crespas vagas:\n\nRazão feroz, o coração me indagas,\nDe meus erros a sombra esclarecendo,\nE vás n'ele (ai de mim!) palpando, e vendo\nDe agudas ânsias venenosas chagas:\n\nCego a meus males, surdo a teu reclamo,\nMil objetos de horror co'a ideia eu corro,\nSolto gemidos, lágrimas derramo:\n\nRazão, de que me serve o teu socorro?\nMandas-me não amar, eu ardo, eu amo;\nDizes-me que sossegue, eu peno, eu morro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 84, «Insuficiência dos ditames da razão contra o poder de Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-debalde-contra-amor-seu-fel-derrama": {"t":["::epigrafe «Como é no mundo Amor quinto elemento, / Que tem dos gostos uma e outra chave.» (Gabriel Pereira de Castro, Ulisseia)\n\nDebalde contra Amor seu fel derrama\nGênio feroz à natureza oposto;\nCrua esfinge infernal de humano rosto,\nOu fúria acesa na tartárea flama.\n\nEsse, a que astuto engano um vício chama,\nBenigno sentimento em nós disposto,\nBrota o desejo percursor do gosto,\nCria o preciso ardor, que a tudo inflama:\n\nDoura a negra existência ao desgraçado,\nDo peito arranca as serpes da tristeza,\nA que inda o mais feliz não foi vedado:\n\nVentura, ao doce Amor tu andas presa;\nÉ de todo o vivente instinto, e fado,\nE teu quinto elemento, oh Natureza!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 85 (sem título)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSphinge > esfinge.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tu-que-na-fouce-de-sanguineo-gume": {"t":["Tu, que na fouce de sanguíneo gume\nTens fera, estragadora omnipotência,\nComo sofres de Amor a resistência,\nOh Tempo devorante, oh ímpio nume?\n\nE tu, que apagas da ternura o lume,\nQue tornas o desvelo em sonolência,\nFilha do Letes, esquecida Ausência,\nOnde está teu poder, e o teu costume?\n\nNos outros c'o prazer morre a firmeza,\nArrefece a paixão de dia em dia,\nLonge dos olhos por que fora acesa:\n\nMas em mim terno ardor jamais esfria;\nPor glória da constância, ou da beleza,\nTriunfam no meu peito Amor e Armia."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 86, «Amor triunfando da ausência, e do tempo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«porque» (relativo, = pelos quais) > «por que».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-que-ideia-horrenda-te-possui-elmano": {"t":["Que ideia horrenda te possui, Elmano?\nQue ardente frenesi teu peito inflama?\nA razão te alumie, apaga a chama,\nReprime a raiva do ciúme insano:\n\nEsperanças consome, ou vive ufano,\nAh! Foge, ou cinge da vitória a rama;\nAma-te a bela Armia, ou te não ama?\nSeus ais são da ternura, ou são do engano?\n\nSe te ama, não consternem teus queixumes\nOs olhos de que estás enfeitiçado,\nDo puro céu de Amor benignos lumes:\n\nSe outro n'alma d'Armia anda gravado,\nQue fruto hás de colher dos vãos ciúmes?\nSer odioso, além de desgraçado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 87, «Insensatez dos ciúmes»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sobranceiro-ao-poder-e-as-leis-da-sorte": {"t":["Sobranceiro ao poder, e às leis da sorte,\nAmor ouviu meus ais, cumpriu meu gosto:\nJá, já sinto nos olhos, peito, e rosto\nA névoa, as ânsias, o suor da morte:\n\nA terra mão piedosa me transporte,\nE depois que em sepulcro mal composto\nDer ao frio cadáver frio encosto,\nEstes versos por dó na pedra corte:\n\n«Aqui se esconde Elmano; alegre estado\nAlgum tempo deveu à amiga estrela,\nFoi de Armia amador, de Armia amado:\n\n«Desuniu duro caso o triste, e a bela;\nViver sem ela lhe ordenava o fado;\nQuis antes o infeliz morrer por ela.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 88, «Ditado para a campa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aureo-fio-sutil-que-teve-unida": {"t":["Áureo fio sutil, que teve unida\nA corpo imaculado uma alma pura,\nDe mimoso estalou, e a sepultura\nFicou do teu despojo enriquecida:\n\nDe mil graças lustrosa a doce vida\nSubiu ao cume da imortal ventura;\nDous numes — Inocência, e Formosura\nVão dando ao mundo eterna despedida:\n\nLá onde a morte, e a terra te devoram,\nNa estância do silêncio, e da tristeza,\nInda, Marília, corações te adoram:\n\nLonge da tua divinal beleza\nAos olhos que te viram, que te choram,\nUm túmulo parece a natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 89, «À memória de Marília»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vem-suspirada-carinhosa-armia": {"t":["Vem, suspirada, carinhosa Armia,\nRemir o escravo, consolar o amante,\nQue aflito, que saudoso a cada instante\nTe envia um pensamento, um ai te envia.\n\nDá-me nos olhos teus mais puro o dia,\nE flores mais gentis em teu semblante\nQue a flor de citereia, a flor brilhante,\nQue o mesmo Abril prefere a quantas cria:\n\nInimiga de Amor é a tardança:\nNão tardes, não, meu bem, que me flagelas\nEm prolongar-me a sôfrega esperança:\n\nVem olhar n'este rio as faces belas,\nVem, por doce ilusão da semelhança,\nVer enganar-se os Zéfiros com elas."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 90, «A Armia ausente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSimilhança > semelhança.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-do-carcere-materno-em-hora-escura": {"t":["Do cárcere materno em hora escura,\nEm momento infeliz, triste, agourado,\nMe desaferrolhou terrível Fado,\nMeus dias cometendo à Desventura:\n\nPerigosas sementes de ternura\nHavia o deus feroz em mim lançado;\nQue mil azedos frutos têm brotado,\nRegadas pelos prantos da amargura.\n\nEscravo da despótica beleza,\nRemir-me de ímpia lei, que me domina,\nTento, e desmaio ao começar a empresa:\n\nOh poder da paixão, que me alucina!\nOh cego Amor! Oh frágil Natureza!\nN'alma busco a razão, e encontro Alcina."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 91, «O Poeta encadeado a seu pesar em novos laços»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«tem» (plural, sujeito «sementes») > «têm».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-igual-ingratidao-e-igual-vileza": {"t":["Igual ingratidão, e igual vileza\nPoucos hão de encontrar entre as ruínas\nQue Amor prepara: pródiga de Alcinas\nNão é (graças aos céus!) a natureza:\n\nGênio de fúria, monstro de torpeza,\nQue o pejo afogas, que a traição refinas,\nSão as Júlias, as Lais, as Messalinas\nA par de ti modelos de pureza.\n\nNão temas, infiel, que à terra chame\nO raio, que reluz na mão do Eterno,\nPara que em negras cinzas te derrame:\n\nRasguem-te as garras do remorso interno\nO coração corrupto, o peito infame;\nLá tenho um vingador, lá tens o inferno."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 92, «Exprobrando a Alcina a sua ingratidão»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ha-um-medonho-abismo-onde-baqueia": {"t":["Há um medonho abismo, onde baqueia\nA impulsos das paixões a humanidade;\nImpera ali terrível divindade,\nQue de torvos ministros se rodeia:\n\nRubro facho a Discórdia ali meneia,\nQue a mil cenas de horror dá claridade;\nCom seus sócios, Traição, Mordacidade,\nRange os dentes a Inveja escura e feia:\n\nVê-se a Morte cruel no punho alçando\nO ferro de sanguento ervado gume,\nE a toda a natureza ameaçando:\n\nVê-se arder, fumegar sulfúreo lume...\nQue estrondo! Que pavor! Que abismo infando!...\nMortais, não é o inferno, é o Ciúme!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 93, «A Estância do Ciúme»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-as-aguas-e-as-areias-d-este-rio": {"t":["Às águas, e às areias d'este rio\nÀs flores, e aos Favônios d'este prado,\nMeus danos conto, minhas mágoas fio,\nDou queixas contra Ismene, Amor, e o Fado:\n\nA paz do coração posta em desvio,\nO gosto em desenganos sufocado,\nLágrimas com lembranças desafio,\nE pela tarda morte às vezes brado:\n\nTão maviosos são meus ais mesquinhos,\nTanto pode a paixão que em mim suspira,\nQue se esquecem das mães os cordeirinhos:\n\nO vento não se mexe, nem respira;\nDeixam de namorar-se os passarinhos,\nPara me ouvir chorar ao som da Lira."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 94, «Queixas contra Ismene na solidão»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-voai-brandos-meninos-tentadores": {"t":["Voai, brandos meninos tentadores,\nFilhos de Vênus, deuses da ternura,\nAdoçai-me a saudade amarga, e dura,\nLevai-me este suspiro aos meus amores:\n\nDizei-lhe que nasceu dos dissabores\nQue influi nos corações a formosura;\nDizei-lhe que é penhor da fé mais pura,\nPorção do mais leal dos amadores:\n\nSe o fado para mim sempre mesquinho,\nA outro ofrece o bem de que me afasta,\nE em ais lhe envia Ulina o seu carinho:\n\nQuando um d'eles soltar na esfera vasta,\nTrazei-o a mim, torcendo-lhe o caminho;\nEu sou tão infeliz, que isso me basta."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 95, «O suspiro»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-des-encanto-meu-nao-des-armia": {"t":["Não dês, encanto meu, não dês, Armia,\nTernas lamentações ao surdo vento;\nSe amorosa impaciência é um tormento,\nCom ledas esperanças se alivia:\n\nA rigorosa mãe, que te vigia,\nEm vão nos prende o lúcido momento\nEm que solto, adejando o pensamento,\nSobe ao cume da glória, e da alegria:\n\nAs fadigas d'Amor não valem tanto\nComo a doce, a furtiva recompensa\nQue outorga, inda que tarde, aos ais, e ao pranto:\n\nAmantes estorvar, que astúcia pensa?\nTem asas o desejo, a noute um manto,\nObstáculos não há, que Amor não vença."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 96, «Persuadindo Armia a que recompense a sua ternura»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-fatais-memorias-da-traidora-alcina": {"t":["Fatais memórias da traidora Alcina,\nD'aquela que encantou meu pensamento;\nSe vos quero sumir no esquecimento,\nNão o consente Amor, que me domina.\n\nQue é da razão, que as almas ilumina?\nPor que não põe limite a meu tormento?\nAh! que mal que a definem, se exp'rimento\nQue não pode evitar-nos a ruína!\n\nDo que estorvar não sabe ela murmura;\nDeixando-me os efeitos perigosos\nDe amorosa, frenética amargura:\n\nE inda são para mim menos penosos\nOs horrores da minha desventura,\nQue a vista, que o prazer dos venturosos."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 97, «Lutando em vão com as memórias d'uma ingrata»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-o-ceu-de-opacas-sombras-abafado": {"t":["O céu, de opacas sombras abafado,\nTornando mais medonha a noute feia;\nMugindo sobre as rochas, que salteia,\nO mar, em crespos montes levantado:\n\nDesfeito em furacões o vento irado,\nPelos ares zunindo a solta areia,\nO pássaro noturno, que vozeia\nNo agoureiro cipreste além pousado;\n\nFormam quadro terrível, mas aceito,\nMas grato aos olhos meus, grato à fereza\nDo ciúme, e saudade, a que ando afeito:\n\nQuer no horror igualar-me a natureza;\nPorém cansa-se em vão, que no meu peito\nHá mais escuridade, há mais tristeza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 98, «Descrevendo uma noute tempestuosa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sonho-ou-velo-que-imagem-luminosa": {"t":["Sonho, ou velo? Que imagem luminosa,\nEsclarecendo o manto à noute escura,\nA meus olhos pasmados se afigura,\nSopeia a tua dor, alma saudosa!\n\nDe mais vistoso objeto o céu não goza,\nA clareza do sol não é mais pura...\nQue encanto! Que esplendor! Que formosura!...\nCaiu-te um astro, abóbada lustrosa!...\n\nSorrisos da purpúrea madrugada,\nVós tão gratos não sois... Ah! Como inclina\nA face para mim branda, apiedada!\n\nRefulgente visão, tu és de Ulina;\nTu és cópia fiel da minha amada,\nOu reflexo talvez da luz divina."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 99, «À memória de Ulina»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSobpêa (de «sobpear», calcar aos pés) > sopeia.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-verso-torneado-ao-som-da-lira": {"t":["Em verso torneado ao som da lira\nEu canto amor, a formosura eu canto;\nPor teus olhos gentis, que podem tanto,\nArde meu coração, treme, suspira:\n\nAudaz competidor, esse que aspira\nDe teus carinhos ao celeste encanto,\nGrosseiro e carrancudo infunde espanto,\nDa bruta estupidez nas sombras gira.\n\nAo vê-lo assim, e ao ver minha amargura,\nMal que ele a ti dirige a vista acesa,\nTodos ao meu temor chamam loucura:\n\nAh! Vem d'alta razão minha tristeza;\nNão receio o rival, temo a Ventura,\nPorque o pôde vingar da Natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 100, «Receando ser suplantado por um rival»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-vitima-da-ingrata-e-do-tirano": {"t":["Se, vítima da ingrata, e do tirano\nQue fazem lastimosa a tua sorte,\nAo peso de frenético transporte\nCeder teu coração, mísero Elmano:\n\nSe àquele que o teu mal contempla ufano\nQuiser teu fado que o prazer lhe aborte;\nSe nas garras também da turva morte\nConhecer que a ventura é doce engano:\n\nSe o seu despojo enfim se unir contigo,\nPara que nem, oh triste, a paz possuas\nEntre as eternas sombras do jazigo;\n\nZelosas despertando as cinzas tuas,\nRevoltas pelo horror, pelo ódio antigo,\nHão de em negro montão fugir das suas."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 101, «O Ciúme reinando ainda no sepulcro»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-voaste-alma-inocente-alma-querida": {"t":["Voaste, alma inocente, alma querida,\nFoste ver outro sol de luz mais pura,\nFalsos bens d'esta vida, que não dura,\nTrocaste pelos bens da eterna vida:\n\nPor Deus chamada, para Deus nascida\nJá de vãs ilusões vives segura:\nFeliz a fé te crê; mas a ternura\nC'o punhal da saudade está ferida.\n\nDesgraçado o mortal, insano, insano\nEm dar seu pranto aos fados de quem mora\nNo palácio do eterno soberano!\n\nPerdoa, Anarda, ao triste que te adora:\nTal é a condição do peito humano;\nSe a Razão se está rindo, Amor te chora."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 102, «À memória de Anarda»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-de-novo-a-meus-olhos-aparecem": {"t":["Já de novo a meus olhos aparecem\nA graça, o riso, as flores da alegria;\nJá na minha teimosa fantasia\nCuidados que velavam adormecem:\n\nCo'a verdade ilusões se desvanecem,\nQual foge o triste mocho à luz do dia;\nPrevidente Razão, porém tardia,\nJá sobre esta alma teus auxílios descem.\n\nComo, cega paixão, nos persuades!\nQuando em Márcia não vi senão beleza\nJulguei que dava glória às divindades:\n\nMas de sacro fulgor co'a mente acesa\nNoto-lhe o coração, e as falsidades,\nVejo que faz injúria à Natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 103, «Conseguindo libertar-se de uma paixão mal correspondida»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nascemos-para-amar-a-humanidade": {"t":["Nascemos para amar; a Humanidade\nVai tarde, ou cedo aos laços da ternura;\nTu és doce atrativo, oh formosura,\nQue encanta, que seduz, que persuade:\n\nEnleia-se por gosto a liberdade;\nE depois que a paixão n'alma se apura,\nAlguns então lhe chamam desventura,\nChamam-lhe alguns então felicidade:\n\nQual se abisma nas lôbregas tristezas,\nQual em suaves júbilos discorre,\nCom esperanças mil na ideia acesas:\n\nAmor ou desfalece, ou para, ou corre;\nE, segundo as diversas naturezas,\nUm porfia, este esquece, aquele morre."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 104, «Variedade dos efeitos d'Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-a-frouxidao-no-amor-e-uma-ofensa": {"t":["A frouxidão no amor é uma ofensa,\nOfensa que se eleva a grau supremo;\nPaixão requer paixão; fervor, e extremo\nCom extremo e fervor se recompensa.\n\nVê qual sou, vê qual és, vê que dif'rença!\nEu descoro, eu praguejo, eu ardo, eu gemo;\nEu choro, eu desespero, eu clamo, eu tremo,\nEm sombras a razão se me condensa:\n\nTu só tens gratidão, só tens brandura,\nE antes que um coração pouco amoroso\nQuisera ver-te uma alma ingrata, e dura:\n\nTalvez me enfadaria aspecto iroso;\nMas de teu peito a lânguida ternura\nTem-me cativo, e não me faz ditoso."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 105, «Notando insensibilidade na sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nos-torpes-lacos-de-beleza-impura": {"t":["Nos torpes laços de beleza impura\nJazem meu coração, meu pensamento;\nE forçada ao servil abatimento\nContra os sentidos a razão murmura:\n\nEu, que outr'ora incensava a formosura\nDas que enfeita o pudor gentil, e isento,\nA já corrupta ideia hoje apascento\nNos falsos mimos de venal ternura:\n\nSe a vejo repartir prazer, e agrado\nÀquele, a este, co'a fatal certeza\nFermenta o vil desejo envenenado;\n\nCéus! Quem me reduziu a tal baixeza?\nQuem tão cego me pôs?... Ah! Foi meu fado,\nQue tanto não podia a natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 106, «Vendo-se preso nos laços de uma dama venal»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nExempto > isento (grafia atual).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-perdi-tudo-ai-de-mim-perdi-marfida": {"t":["Perdi tudo (ai de mim!) perdi Marfida,\nMarfida, a glória minha, a minha amada;\nTenra flor, a esperança malograda\nDo mimoso matiz caiu despida:\n\nPede meu coração mortal ferida,\nSó aos ditosos a existência agrada;\nVida entre angústias equivale ao nada,\nNo risonho prazer consiste a vida.\n\nEia, amante infeliz, teu fim procura!\nFantástico terror não te reporte,\nNos túmulos não reina a formosura.\n\nDiga triste letreiro a minha sorte;\nDai-me piedosa sombra à sepultura\nTeixos, ciprestes, árvores da morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 107, «Disposto a acompanhar ao jazigo a sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-da-rama-escura-de-letal-cipreste": {"t":["Da rama escura de letal cipreste\nEm sonhos vi c'roada a bela Armia;\nAlvas, mimosas carnes lhe envolvia\nDa negra morte a lutuosa veste:\n\nVagueava o meu bem n'um ermo agreste,\nOnde o mocho agoureiro se carpia,\nNão tão meiga e gentil como algum dia,\nMas inda conservava um ar celeste:\n\n«Esta que vês (me disse em tom magoado)\nQue não creste mortal, mas divindade,\nÉ sombra vã, fantasma inanimado.»\n\nEis ferido de amor, e de saudade,\nGrito, acordo, e seguiu-se (oh duro fado!)\nA funesta visão fatal verdade."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 108, «À morte de Armia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-la-onde-o-fado-impenetravel-mora": {"t":["Lá onde o Fado impenetrável mora,\nVoa o menino Amor entre os Amores;\nLoureja a trança, que matizam flores,\nCintila o facho, que a Razão devora:\n\nEntra, saúda o nume, ao nume implora\nQue de Marília os olhos tentadores\nVejam sempre ante as Graças, e os Louvores\nDe seus anos gentis surgir a aurora:\n\nFronte rugosa vezes três sacode\nO deus, cujo poder tudo atropela,\nE às súplicas d'Amor d'est'arte acode:\n\n«Escape às minhas leis Marília bela,\nSeja, seja imortal: durar não pode\nO mundo sem amor, amor sem ela.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 109, «A Marília, em seu dia natalício»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quantas-vezes-amor-me-tens-ferido": {"t":["Quantas vezes, Amor, me tens ferido?\nQuantas vezes, Razão, me tens curado?\nQuão fácil de um estado a outro estado\nO mortal sem querer é conduzido!\n\nTal, que em grau venerando, alto e luzido,\nComo que até regia a mão do fado,\nOnde o sol, bem de todos, lhe é vedado\nDepois com ferros vis se vê cingido;\n\nPara que o nosso orgulho as asas corte,\nQue variedade inclui esta medida,\nEste intervalo da existência à morte!\n\nTravam-se gosto, e dor; sossego, e lida;\nÉ lei da natureza, é lei da sorte\nQue seja o mal e o bem matiz da vida."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 110, «Refletindo sobre a instabilidade da condição humana»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nQuam > quão.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-tu-consolador-dos-malfadados": {"t":["Oh tu, consolador dos malfadados,\nOh tu, benigno dom da mão divina,\nDas mágoas saborosa medicina,\nTranquilo esquecimento dos cuidados:\n\nAos olhos meus, de prantear cansados,\nCansados de velar, teu voo inclina;\nE vós, sonhos d'amor, trazei-me Alcina,\nDai-me a doce visão de seus agrados:\n\nFilha das trevas, frouxa sonolência,\nDos gostos entre o férvido transporte\nQuanto me foi suave a tua ausência!\n\nAh! findou para mim tão leda sorte;\nAgora é só feliz minha existência\nNo mudo estado, que arremeda a morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 111, «Ao Sono, para que lhe represente a imagem da amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quando-a-que-me-rendeu-jurava-ufano": {"t":["Quando à que me rendeu jurava ufano\nGostar por ela do funéreo instante,\nDizia a doce amada ao terno amante:\n«Inália morrerá, se morre Elmano!»\n\nO Tempo, das paixões, dos bens tirano,\nTornou ferino o divinal semblante,\nE nos lábios gentis voz fulminante\nVibrou, vibrou-me um raio; — o desengano!\n\nEsperanças, murchai; tu, lisonjeiro\nSonho adorável, com que o ser mantive,\nDesfaze-te em meu ponto derradeiro:\n\nMas as cinzas do amante Amor não prive\nDos ais d'escravos seus: triste letreiro\nDiga: — «Elmano morreu, e Inália vive.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 112, «À inconstância de Inália»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Inalia > Inália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-pode-o-tosco-pincel-que-mal-sustento": {"t":["Pode o tosco pincel, que mal sustento,\nPintar ousado divinal beleza?\nOh! Quanto fora temerária empresa!\nPagara icária sorte o louco intento.\n\nNão pinta humana pena um tal portento,\nMilagre da sublime natureza;\nTens mais alto pintor, que não despreza\nPintar-te... a mão, que fez o firmamento:\n\nTanto não posso, oh d'entre as belas bela;\nE baixará dos céus fiel socorro\nP'ra traçar-te a paixão, que me flagela?\n\nDeliro, amável Jônia; em vão discorro;\nConfunde-me a aflição que me atropela,\nMal sei balbuciar que por ti morro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 113, «A uma dama, que lhe pedia quisesse retratá-la (Improvisado)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-fragil-lenho-o-pelago-cruzando": {"t":["Em frágil lenho o pélago cruzando,\nNos turbilhões das vagas envolvido,\nA razão se me esvai, perco o sentido,\nNa triste vida minha imaginando:\n\nCedo a Morfeu: — a mente flutuando\nPõe ante mim o deus, que impera em Gnido,\nDo arco aguda seta enfurecido\nVai ao peito de Anália disparando:\n\nTrêmulo, insano, exausto, delirante,\nBrado ao númen feroz: — «Espera, espera,\nNão firas, poupa um coração constante.»\n\nN'isto o deus mostra o coração da fera;\nVi-te, pérfida, e disse agonizante:\n«Da lembrança riscar-te, ah quem podéra!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 114, «Glosando o mote: «Da lembrança riscar-te, ah quem podéra!»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quis-marilia-gentil-cantar-teu-dia": {"t":["Quis, Marília gentil, cantar teu dia,\nTeu dia grato a Amor, grato à ventura,\nPintar-te a graça, o riso, a formosura,\nPrincípios de inefável simpatia:\n\nAo pai da claridade, e da harmonia\nRoguei canções de singular brandura;\nMas sempre mais e mais a mente escura\nN'um tumulto de ideias se perdia:\n\nEis o deus, que da aurora aviva os lumes,\nMe diz: — «Porque tens nome entre os humanos,\nObjetos divinais cantar presumes?\n\n«Subjuga dentro d'alma os sons profanos;\nMuda em culto o louvor; celebrem numes,\nMortais adorem de Marília os anos.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 115, «A Marília, no seu dia natalício»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tu-es-meu-coracao-tu-es-meu-nume": {"t":["Tu és meu coração, tu és meu nume;\nNão vive para mim do mundo o resto;\nA morte, a vida, os céus, meu fado atesto,\nMeu fado, que em teus olhos se resume.\n\nMas com frequente, ríspido queixume\nOs mimosos ouvidos te molesto;\nDias d'ouro, e de amor (ah!) toldo, empesto\nCo'as trevas mais que horríveis do ciúme,\n\nOlho-te as graças, olho-te a beleza,\nE cuido que enfeitiças por meu dano\nQuantos entes abrange a natureza!\n\nSocorre, doce Márcia, o triste Elmano;\nOh! Que infernal tormento o da incerteza!\nAo menos é só morte o desengano."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 116, «A Marcia, pedindo-lhe a confirmação do seu amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quando-meu-coracao-de-amor-vivia": {"t":["Quando meu coração de Amor vivia,\n(Ufana a liberdade em ver-se escrava)\nE quando para mim se variava\nO céu n'um riso, o céu n'um ai d'Armia:\n\nDas escuras irmãs a mais sombria,\nE que mais com seu peso o mundo agrava,\nNa vista divinal, que me encantava,\nRoubou luz à minha alma, e luz ao dia:\n\nNão mais, Dor, fado meu, Dor, meu costume;\nCedo a paz gozarei, que o peito anela,\nNos olhos do meu bem, do céu já lume:\n\nJunto à ninfa imortal na estância bela\nOs dias perenais, que vive um nume,\nIrei (nume em ser seu) viver com ela."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 117, «À memória de Armia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-noute-amiga-de-amor-calada-escura": {"t":["Noute, amiga de Amor, calada, escura,\nEia engrossa os teus véus, os teus horrores;\nEnquanto vou gozar de mil favores\nSobre o doce teatro da ternura:\n\nMarília, mais gentil, e até mais pura\nQue as ledas Graças, que as mimosas flores,\nVelando às mudas horas dos Amores\nReceia o casto pejo, que murmura:\n\nEm deleitoso e tácito retiro,\nSuspensa entre o temor, entre o desejo,\nFlutua a bela, a cuja posse aspiro:\n\nAh! já nos braços meus a aperto e beijo!\nJá, desprendendo um lânguido suspiro,\nNo seio do prazer se absorve o pejo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 118, «Aguardando uma entrevista prometida»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-homens-e-numes-suspirado-encanto": {"t":["De homens e numes suspirado encanto,\nLília, inocente como virgem rosa,\nLília mais branda, Lília mais formosa\nQue a ninfa etérea, de puníceo manto:\n\nEu, e os Amores, que perderam tanto,\nDamos-te às cinzas oblação mimosa;\nCurva goteje minha dor saudosa\nNa mole of'renda, que requer meu pranto:\n\nEm teu sagrado, perenal retiro,\nDisponho ao som de lânguidas querelas,\nA rosa, o cravo, a tulipa, o suspiro:\n\nMedrai no chão de amor, florinhas belas...\nAh! Lília, eu gozo o céu!... Lília, eu respiro\nTua alma pura na fragrância d'elas!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 119, «A uma donzela de extrema beleza, e de rara virtude, morta na flor dos anos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Lilia > Lília.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-da-fria-habitacao-da-vitrea-gruta": {"t":["Da fria habitação, da vítrea gruta\nAlça o Calipo a fronte salitrosa;\nE risonho penteia a nunca enxuta\nAlva melena, ríspida, e limosa:\n\nEm torno d'ele a modular se escuta\nChusma de ninfas cândida, e formosa;\nDos ventos o tropel bramindo luta\nLá na eólia masmorra cavernosa:\n\nDando lascivos ósculos nas flores\nGratos eflúvios Zéfiro derrama,\nDesfaz do inverno os mádidos vapores:\n\nAlmo prazer os corações inflama,\nTudo respira amor, tudo louvores\nAo festivo natal do ilustre Gama."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 120, «Nos faustos anos do Senhor Antonio José Bernardo da Gama Faria e Barros, em Setúbal»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-da-triste-bela-ines-inda-os-clamores": {"t":["Da triste, bela Inês, inda os clamores\nAndas, Eco chorosa, repetindo;\nInda aos piedosos céus, andas pedindo\nJustiça contra os ímpios matadores;\n\nOuvem-se ainda na fonte dos Amores\nDe quando em quando as náiades carpindo;\nE o Mondego, no caso refletindo,\nRompe irado a barreira, alaga as flores:\n\nInda altos hinos o universo entoa\nA Pedro, que da morta formosura\nConvosco, Amores, ao sepulcro voa:\n\nMilagre da beleza, e da ternura!\nAbre, desce, olha, geme, abraça e c'roa\nA malfadada Inês na sepultura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 121, «À lamentável catástrofe de D. Inês de Castro»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-radiosas-virtudes-escoltada": {"t":["De radiosas virtudes escoltada\nDeste imaturo adeus ao mundo triste,\nCo'a mente no almo polo, aonde existe\nBem, que sempre se goza, e nunca enfada;\n\nA fouce, a segar vidas destinada,\nMansíssima cordeira o colo uniste;\nO que é do céu ao céu restituíste,\nRestituíste ao nada o que é do nada:\n\nE inda gemo, inda choro, alma querida,\nTeu fado amigo, tua dita imensa,\nQue em vez de pranto a júbilo convida!\n\nAh! Pio acordo minha mágoa vença;\nÉ cativeiro para o justo a vida,\nA morte para o justo é recompensa."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 122, «À morte de sua irmã D. Maria Eugênia Barbosa du Bocage, falecida na flor da idade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-olhos-suaves-que-em-suaves-dias": {"t":["Olhos suaves, que em suaves dias\nVi nos meus tantas vezes empregados;\nVista, que sobre esta alma despedias\nDeleitosos farpões, no céu forjados:\n\nSantuários de amor, luzes sombrias,\nOlhos, olhos da cor de meus cuidados,\nQue podeis inflamar as pedras frias,\nAnimar os cadáveres mirrados:\n\nTroquei-vos pelos ventos, pelos mares,\nCuja verde arrogância as nuvens toca,\nCuja horríssona voz perturba os ares:\n\nTroquei-vos pelo mal, que me sufoca;\nTroquei-vos pelos ais, pelos pesares:\nOh câmbio triste! oh deplorável troca!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 126, «O Poeta distante da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-da-perfida-gertruria-o-juramento": {"t":["Da pérfida Gertrúria o juramento\nParece-me que estou inda escutando,\nE que inda ao som da voz suave e brando\nEncolhe as asas, de encantado, o vento:\n\nNo vasto, infatigável pensamento\nOs mimos da perjura estou notando...\nEis Amor, eis as Graças festejando\nDos ternos votos o feliz momento.\n\nMas ah!... Da minha rápida alegria\nPara que acendes mais as vivas cores,\nLisonjeiro pincel da fantasia?\n\nBasta, cega paixão, loucos amores;\nEsqueçam-se os prazeres de algum dia,\nTão belos, tão duráveis como as flores."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 127, «Recordando-se da inconstância de Gertrúria»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-por-fofos-escarceus-arremessado": {"t":["Por fofos escarcéus arremessado\nOra aos abismos, ora ao firmamento,\nEscutando o furor, e o som violento\nDo ríspido Aquilão, de Noto irado:\n\nAberto o peito, o coração rasgado\nPelo agudo punhal do apartamento,\nQual pombinho, que foi de açor cruento\nPelas garras mortais atravessado;\n\nAssim n'um cego amor já cego e louco,\nEnvio, alma querida, envio aos ares\nDe quando em quando um ai trêmulo e rouco;\n\nMas tantas aflições, tantos pesares\nTudo é pouco, Gertrúria, tudo é pouco,\nSe inda eu vir os teus olhos singulares."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 128, «A Gertrúria ausente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-qual-o-avaro-infeliz-que-nao-descansa": {"t":["Qual o avaro infeliz, que não descansa,\nVolvendo os olhos d'um para o outro lado,\nPor cuidar que ao tesouro idolatrado\nCubiçosa vontade as mãos lhe lança:\n\nTal eu, meu doce amor, minha esperança,\nDe suspeitas cruéis atormentado,\nReceio que a distância, o tempo, o fado\nTe arranquem meus carinhos da lembrança:\n\nReceio que, por minha adversidade,\nNovo amante sagaz, e lisonjeiro\nMacule de teus votos a lealdade:\n\nAh! crê, bela Gertrúria, que o primeiro\nDia, em que eu chore a tua variedade,\nSerá da minha vida o derradeiro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 129, «À mesma, receoso da sua constância»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nCubiçosa: forma antiga de «cobiçosa», mantida.\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-enquanto-os-bravos-formidaveis-notos": {"t":["Enquanto os bravos, formidáveis Notos,\nPor entre os cabos trêmulos zunindo,\nO fendente baixel vão sacudindo\nA climas, do meu clima tão remotos:\n\nEnquanto de Nereu contínuos motos\nNa vacilante popa estou sentindo,\nAo meu ídolo amado, ausente, e lindo,\nFormo nas mãos d'Amor sagrados votos:\n\nMordaz tristeza o coração me corte,\nSofra tudo, oh Gertrúria, por amar-te,\nFarte-se embora a cólera da sorte:\n\nMas talvez (ai de mim!) que se não farte,\nQue ou tua variedade, ou minha morte\nMe roube as esperanças de lograr-te."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 130, «A Gertrúria, escrito durante uma viagem»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-usurpando-um-minuto-a-meu-lamento": {"t":["Usurpando um minuto a meu lamento\nAmigo sono os olhos me ocupava,\nE enquanto o débil corpo descansava,\nVelava amor, velava o pensamento:\n\nEis que em deserto e lúgubre aposento,\nQue semimorta luz mais afeiava,\nCri, Gertrúria (ai de mim!) que te avistava\nJá sem cor, já sem voz, já sem alento:\n\nSúbito acordo em lágrimas banhado,\nE, das trevas palpando o véu medonho,\nEm vão busco teu corpo delicado:\n\nMas inda em ânsias trêmulo suponho\nQue me vaticinou meu negro fado\nDos males o pior no horrível sonho."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 131, «Preságios de desventura propínqua»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nAfeiava: forma antiga de «afeava», mantida.\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-alva-gertruria-minha-a-quem-saudoso": {"t":["Alva Gertrúria minha, a quem saudoso\nMando trêmulos ais enternecidos;\nGertrúria, que encantaste os meus sentidos\nCo'um meigo riso, co'um olhar piedoso:\n\nAmor, o injusto Amor, nume doloso,\nInsensível penedo a meus gemidos,\nMe exala sobre os tímidos ouvidos\nEstas vozes cruéis em tom raivoso:\n\n«Tu, que já desfrutaste os meus favores,\nTu, que na face de Gertrúria bela\nNéctar bebeste, mitigaste ardores,\n\nNão tornarás, não tornarás a vê-la:\nLamenta, desgraçado, os teus amores,\nAcusa, desgraçado, a tua estrela.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 132, «Oráculo de Amor»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-meia-noute-seria-eu-passeando": {"t":["Meia noute seria; eu passeando\nNo meu palmar chorava o meu destino;\nEis que ao som de um gemido repentino\nOlho, e vejo uma sombra no ar girando:\n\nQuem és, Guirá? (pergunto-lhe arquejando)\nQuem és, quem és, oh Lêmure maligno?... —\n«Sou o espírito (diz) de Saladino,\nDe quem já leste o caso miserando:\n\n«De Grisalda as traições inda lamento\nDa solitária noute entre os horrores,\nE os olhos, mortal cego, abrir-te intento:\n\n«Não soltes por Natércia mais clamores;\nSepulta a desleal no esquecimento:\nOlha o trágico fim de meus amores!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 133, «Visão noturna (Feito na Índia)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nMaligno: rima com destino, Saladino (pronúncia antiga «malino»).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sonhei-que-nos-meus-bracos-inclinado": {"t":["Sonhei que nos meus braços inclinado\nTeu rosto encantador, Gertrúria, via;\nQue mil ávidos beijos me sofria\nTeu níveo colo, para os mais sagrado:\n\nSonhei que era feliz por ser ousado,\nQue o siso, a força, a voz, a cor perdia\nN'um extasis suave, em que bebia\nO néctar nem por Jove inda libado:\n\nMas no mais doce, no melhor momento\nExalando um suspiro de ternura\nAcordo, acho-te só no pensamento:\n\nOh destino cruel! Oh sorte escura!\nQue nem me dure um vão contentamento!\nQue nem me dure em sonhos a ventura!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 134, «Ventura sonhada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nExtasis: forma antiga de «êxtase», mantida.\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-eu-me-ausento-de-ti-meu-patrio-sado": {"t":["Eu me ausento de ti, meu pátrio Sado,\nMansa corrente deleitosa, amena,\nEm cuja praia o nome de Filena\nMil vezes tenho escrito, e mil beijado:\n\nNunca mais me verás entre o meu gado\nSoprando a namorada e branda avena,\nA cujo som descias mais serena,\nMais vagarosa para o mar salgado:\n\nDevo enfim manejar por lei da sorte\nCajados não, mortíferos alfanges\nNos campos do colérico Mavorte;\n\nE talvez entre impávidas falanges\nTestemunhas farei da minha morte\nRemotas margens, que umedece o Ganges."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 135, «Despedindo-se da pátria, ao partir para a Índia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-do-mandovi-na-margem-reclinado": {"t":["Do Mandovi na margem reclinado\nChorei debalde minha negra sina,\nQual o mísero vate de Corina\nNas tomitanas praias desterrado:\n\nMais duro fez ali meu duro fado\nDa vil calúnia a língua viperina;\nAté que aos mares da longínqua China\nFui por bravos tufões arremessado:\n\nAtassalhou-me a serpe, que devora\nTantos mil, perseguiu-me o gran' gigante\nQue no terrível promontório mora:\n\nPor bárbaros sertões gemi vagante;\nFalta-me inda o pior, falta-me agora\nVer Gertrúria nos braços d'outro amante!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 136, «Descreve as suas desventuras, longe da pátria e de Gertrúria»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-praias-de-sacavem-que-lemnoria": {"t":["Praias de Sacavém, que Lemnoria\nOrna c'os pés nevados e mimosos,\nGotejantes penedos cavernosos,\nQue do Tejo cobris a margem fria:\n\nDe vós me desarreiga a tirania\nDos ásperos Destinos poderosos;\nQue não querem que eu logre os amorosos\nOlhos, aonde jaz minha alegria:\n\nOh funesto, oh penoso apartamento!\nObjeto encantador de meus sentidos,\nA sorte o manda assim, de ti me ausento:\n\nMas inda lá de longe os meus gemidos\nGuiados por Amor, cortando o vento,\nVirão, ninfa querida, a teus ouvidos."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 137, «Achando-se prestes a ausentar-se da sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nDesarreiga: forma antiga de «desarraiga», mantida.\n\nVerso 1: a digitalização da ed. 1875 lê «Leranoria» (provável erro de OCR); adotado «Lemnoria», como nas digitalizações da ed. 1853, que a rima (fria, tirania, alegria) e o metro confirmam (lem-no-ri-a).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-camoes-grande-camoes-quao-semelhante": {"t":["Camões, grande Camões, quão semelhante\nAcho teu fado ao meu, quando os cotejo!\nIgual causa nos fez perdendo o Tejo\nArrostar c'o sacrílego gigante:\n\nComo tu, junto ao Ganges sussurrante\nDa penúria cruel no horror me vejo;\nComo tu, gostos vãos, que em vão desejo,\nTambém carpindo estou, saudoso amante:\n\nLudíbrio, como tu, da sorte dura\nMeu fim demando ao céu, pela certeza\nDe que só terei paz na sepultura:\n\nModelo meu tu és... Mas, oh tristeza!...\nSe te imito nos trances da ventura,\nNão te imito nos dons da natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 138, «A Camões, comparando com os d'ele os seus próprios infortúnios»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nQuam > quão; similhante > semelhante.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-adeja-coracao-vai-ter-aos-lares": {"t":["Adeja, coração, vai ter aos lares,\nDitosos lares, que Gertrúria pisa;\nOlha, se inda te guarda a fé mais lisa,\nVê, se inda tem pesar dos teus pesares:\n\nNo fulgor de seus olhos singulares\nCrestando as asas, tua dor suaviza,\nAmor de lá te chama, te divisa,\nInterpostos em vão tão longos mares:\n\nDize-lhe, que do tempo o leve giro\nNão faz abalo em ti, não faz mudança,\nQue ainda lhe és fiel n'este retiro:\n\nSim, pinta-lhe imortal minha lembrança;\nDá-lhe teus ais, e pede-lhe um suspiro,\nQue alente, coração, tua esperança."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 139, «Saudades de Gertrúria»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ah-que-fazes-elmano-ah-nao-te-ausentes": {"t":["Ah! que fazes, Elmano? Ah! Não te ausentes\nDos braços de Gertrúria carinhosa:\nTrocas do Tejo a margem deleitosa\nPor bárbaro país, bárbaras gentes?\n\nUm tigre te gerou, se dó não sentes\nVendo tão consternada, e tão saudosa\nA tágide mais linda, e mais mimosa;\nAh! Que fazes, Elmano? ah, não te ausentes.\n\nTeme os duros cachopos, treme, insano,\nDo enorme Adamastor, que sempre vela\nEntre as fúrias, e os monstros do Oceano:\n\nOlha nos lábios de Gertrúria bela\nComo suspira Amor!... Vê, vê, tirano,\nAs Graças a chorar nos olhos d'ela!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 140, «Ao partir para a Índia, deixando em Lisboa a sua amada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Gertruria > Gertrúria.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-deixar-amado-bem-teu-rosto-lindo": {"t":["Deixar, amado bem, teu rosto lindo,\nTeus afagos deixar, tua candura,\nTanto me oprime, que da morte escura\nSobre mim negras sombras vêm caindo:\n\nEu parto, e vou teu nome repetindo,\nPorque dê desafogo à mágoa dura;\nMeus tristes ais, suspiros de amargura\nAquém dos mares ficarás ouvindo:\n\nMas se me cercam no cruel transporte\nQuantas fúrias o báratro vomita,\nSe meu mal é pior que a mesma morte:\n\nO fado em me aterrar em vão cogita!\nCom todo o seu poder não pode a sorte\nTua imagem riscar d'esta alma aflita!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 141, «Ao partir da pátria para Lisboa, no intento de ausentar-se para terras longínquas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-mais-oh-tejo-meu-formoso-e-brando": {"t":["Não mais, oh Tejo meu, formoso e brando,\nA margem fértil de gentis verdores,\nTerás d'alta Ulisseia um dos cantores\nSuspiros no áureo metro modulando:\n\nRindo não mais verá, não mais brincando\nPor entre as ninfas, e por entre as flores,\nO coro divinal dos nus Amores,\nDos Zéfiros azuis o afável bando:\n\nCo'a fronte sem mirto, e já sem louro,\nO arrebata de rojo a mão da Sorte\nAo clima salutar, e à margem d'ouro:\n\nEi-lo em fragas de horror, sem luz, sem norte,\nSoa d'aqui, d'ali piado agouro;\nSois vós, desterro eterno, ermos da morte!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 142, «Despedidas ao Tejo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-por-barbaros-climas-entranhado": {"t":["Já por bárbaros climas entranhado,\nJá por mares inóspitos vagante,\nVítima triste da fortuna errante,\nTé dos mais desprezíveis desprezado:\n\nDa fagueira esperança abandonado,\nLassas as forças, pálido o semblante,\nSinto rasgar meu peito a cada instante\nA mágoa de morrer expatriado:\n\nMas ah! Que bem maior, se contra a sorte\nLá do sepulcro no sagrado hospício\nRefúgio me promete a amiga Morte!\n\nVem pois, oh nume aos míseros propício,\nVem livrar-me da mão pesada e forte,\nQue de rastos me leva ao precipício!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 143, «Vendo-se longe da pátria, e perseguido pela Fortuna»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aquele-a-quem-mil-bens-outorga-o-fado": {"t":["Aquele, a quem mil bens outorga o Fado,\nDeseje com razão da vida amigo\nNos anos igualar Nestor, o antigo,\nDe trezentos invernos carregado:\n\nPorém eu sempre triste, eu desgraçado,\nQue só n'esta caverna encontro abrigo,\nPor que não busco as sombras do jazigo,\nRefúgio perdurável, e sagrado?\n\nAh! bebe o sangue meu, tosca morada;\nAlma, quebra as prisões da humanidade,\nDespe o vil manto, que pertence ao nada!\n\nMas eu tremo!... Que escuto!... É a Verdade,\nÉ ela, é ela que do céu me brada:\nOh terrível pregão da eternidade!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 144, «Tentativa de suicídio, combatida pelas lembranças da eternidade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-qual-novo-orestes-entre-as-furias-brada": {"t":["Qual novo Orestes entre as Fúrias brada,\nInfeliz, que não crês no Omnipotente;\nCom sistema sacrílego desmente\nA razão luminosa, a fé sagrada:\n\nTua bárbara voz iguale ao nada\nO que em todas as cousas tens presente;\nBasta que o sábio, o justo, o pio, o crente\nLouve a mão, contra os maus do raio armada.\n\nMas vê, blasfemo ateu, vê, monstro horrendo,\nQue a bruta opinião, que cego expressas,\nA si mesma se está contradizendo:\n\nPois quando de negar um Deus não cessas,\nDe tudo o inerte Acaso autor fazendo,\nNo Acaso, a teu pesar, um Deus confessas!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 145, «Contradições do Ateísmo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-a-minha-lastimosa-desventura": {"t":["Se a minha lastimosa desventura\nIrreparável é, se trago escrito\nNo rosto cor da morte o meu delito,\nQue louca ideia os passos me segura?\n\nAh! Some-te, infeliz, foge, e procura\nMargens quais as do lívido Cocito,\nBrenhas, matos, sertões, errante, aflito,\nAté que vás parar na sepultura:\n\nOh nume enganador, nume falsário!\nOh lúbrica Fortuna de quem rego\nEm vão com triste pranto o santuário!\n\nJá sem violência em tuas mãos me entrego;\nSim, vária, aqui me tens inda mais vário,\nCega, a ti me abandono, inda mais cego!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 146, «Abandonando-se aos azares da Fortuna»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-deus-oh-rei-do-ceu-do-mar-da-terra": {"t":["Oh Deus, oh rei do céu, do mar, da terra,\n(Pois só me restam lágrimas, clamores)\nSuspende os teus horríssonos furores,\nO corisco, o trovão, que a tudo aterra:\n\nNos subterrâneos cárceres encerra\nOs procelosos monstros berradores,\nQue enchendo os ares de infernais vapores\nParece que entre si travaram guerra.\n\nPara nós compassivo os olhos lança,\nPerdoa ao fraco lenho, atende ao pranto\nDos tristes, que em ti põem sua esperança!\n\nAs densas trevas despedaça o manto!\nFaze, em sinal de próxima bonança,\nBrilhar no etéreo tope o lume santo!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 147, «Deprecação feita durante uma tempestade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-apenas-vi-do-dia-a-luz-brilhante": {"t":["Apenas vi do dia a luz brilhante\nLá de Tubal no empório celebrado,\nEm sanguíneo caráter foi marcado\nPelos Destinos meu primeiro instante:\n\nAos dous lustros a morte devorante\nMe roubou, terna mãe, teu doce agrado;\nSegui Marte depois, e enfim meu fado\nDos irmãos, e do pai me pôs distante:\n\nVagando a curva terra, o mar profundo,\nLonge da pátria, longe da ventura\nMinhas faces com lágrimas inundo:\n\nE enquanto insana multidão procura\nEssas quimeras, esses bens do mundo,\nSuspiro pela paz da sepultura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 148, «O Poeta lutando contra o infortúnio»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-no-etereo-prado-a-lua-apascentava": {"t":["No etéreo prado a lua apascentava\nDas estrelas o nítido rebanho,\nQuando o mísero Almeno em clima estranho\nDe negro bosque as sombras penetrava:\n\n«Silêncio, em cujo horror, que a vista agrava,\nQual fantasma notívago me entranho!\nSofre (dizia) os prantos, com que banho\nDe um crime a nódoa, que o chorar não lava.\n\n«Sofre os gritos... mas ai! que sem piedade\nPor entre folha e folha a luz procura\nFurtar-me o triste bem da escuridade!\n\nOnde te hei de escapar, oh sorte dura,\nOh cruel, insofrível claridade?\nJá sei onde, já sei — na sepultura!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 149, «Feito na Índia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-cessaroes-viriatos-apimanos": {"t":["Cessarões, Viriatos, Apimanos,\nVós, que brandindo vingadora espada,\nTentastes sacudir da pátria amada\nO vil, o férreo jugo dos romanos:\n\nSurgi, vede-a no sangue de tiranos\nInda piores outra vez banhada,\nE a nossa liberdade edificada\nNo estrago dos intrusos castelhanos:\n\nAos senhores do mundo armipotentes\nArrancastes em bélica porfia\nParte do louro, que lhe honrava as frentes:\n\nPorém com milagrosa valentia\nOs vossos memoráveis descendentes\nFizeram mais — livraram-se n'um dia!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 150, «À restauração de Portugal em 1640»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-musa-chorosa-que-por-terra-estranha": {"t":["Musa chorosa, que por terra estranha\nTão longe de teu pátrio ninho amado\nAndas errante, suspirando ao lado\nDa Saudade fiel, que te acompanha:\n\nDo chão, onde a lançaste, a lira apanha,\nE seja em brando som por ti cantado\nUm peito de virtudes adornado,\nA piedosa, a magnânima Saldanha:\n\nLouva os dons d'aquela alma excelsa e pura,\nQue as tuas gastará mágoas penosas,\nComo a aurora desfaz a noute escura:\n\nDepois às lindas filhas melindrosas,\nRivais da mãe d'Amor na formosura,\nTece capelas e festões de rosas."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 151, «Oferecido em Macau à Excelentíssima Senhora D. Maria Saldanha Noronha e Menezes, e suas filhas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sobre-os-contrarios-o-terror-e-a-morte": {"t":["Sobre os contrários o terror e a morte\nDardeje embora Aquiles denodado,\nOu no rápido carro ensanguentado\nLeve a rastos sem vida o Teucro forte:\n\nEmbora o bravo Macedônio corte\nCo'a fulminante espada o nó fadado,\nQue eu de mais nobre estímulo tocado,\nNem lhe amo a glória, nem lhe invejo a sorte:\n\nInvejo-te, Camões, o nome honroso;\nDa mente criadora o sacro lume,\nQue exprime as fúrias de Lieu raivoso:\n\nOs ais de Inês, de Vênus o queixume,\nAs pragas do gigante proceloso,\nO céu de Amor, o inferno do Ciúme."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 152, «Em louvor do grande Camões»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nArrastos (ed. 1875) > a rastos.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ser-prole-de-varoes-assinalados": {"t":["Ser prole de varões assinalados,\nQue nas asas da fama e da vitória\nAo templo foram da imortal Memória\nPendurar mil troféus ensanguentados:\n\nLer seus nomes nas páginas gravados\nD'alta epopeia, d'elegante história,\nNão, não vos serve d'esplendor, de glória,\nAlmas suberbas, corações inchados!\n\nOuvir com dor o miserável grito\nDe inocentes, que um bárbaro molesta,\nPrezar o sábio, consolar o aflito;\n\nPrender teus voos, Ambição funesta,\nTer amor à virtude, ódio ao delito,\n«Das almas grandes a nobreza é esta.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 153, «Glosando o mote: «Das almas grandes a nobreza é esta»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSuberbas: forma antiga de «soberbas», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-bando-espesso-em-numero-infinito": {"t":["Em bando espesso, em número infinito,\nDefende a ponte o bárbaro malaio;\nEis que entre horrores, êmulo do raio,\nAlbuquerque imortal voa ao conflito:\n\nAssim que assoma o claro chefe invicto,\nTerror da prole do feroz sabaio,\nGela os netos de Agar frio desmaio,\nOs lusos soltam da vitória o grito:\n\nVítima são do português Mavorte\nInda aqueles, que mal na fuga alcança,\nLeva no ferro transmigrada a morte:\n\nMas já sobre troféus o herói descansa,\nHavendo por seu braço ilustre, e forte,\nA pátria, a natureza, os céus vingança."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 154, «Ao grande Afonso d'Albuquerque, tomando Malaca em vingança da perfídia do rei do país para com os portugueses»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-blasfema-rumecao-jura-vinganca": {"t":["Blasfema Rumecão, jura vingança\nAos manes infernais, ao pai maldito,\nE contra Diu em pertinaz conflito\nAs indústrias esgota, as forças cansa:\n\nMunido de magnânima esperança\nO portentoso chefe, o luso invicto,\nDos veneráveis muros infinito\nE bárbaro tropel mil vezes lança:\n\nFeminina caterva as armas mede;\nEncurtando às do Rodope a memória\nSobre hostil multidão raios despede:\n\nE quando finalmente a lísia glória\nVê o extremo fatal, e inda não cede,\nEis Castro, eis a virtude, eis a vitória!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 155, «A D. João de Castro, socorrendo e salvando a fortaleza de Diu»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-louca-cega-iludida-humanidade": {"t":["Louca, cega, iludida Humanidade,\nMiserável de ti! Não consideras\nQue o barro te gerou, como que esperas\nEvadir-te à geral fatalidade!\n\nPó, que levanta o sopro da vaidade,\nHomem caduco e frágil, não ponderas\nQue teus bens, teus brasões, tuas quimeras\nNenhum valor terão na eternidade?\n\nAh! Volta, volta os olhos mais sisudos;\nAli na majestade aniquilada\nTe faz o desengano aviso mudo:\n\nAtenta de José na cinza amada:\nQue serás, se ele é já, se há de ser tudo\nPasto da Morte, vítima do nada?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 156, «Na morte do Senhor D. José, Príncipe do Brasil»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-jose-sangue-d-herois-principe-amado": {"t":["José, sangue d'heróis, príncipe amado,\nNosso bem, nosso pai, nossa alegria,\nTu pela negra mão da Morte fria,\nDa truculenta Morte em flor cortado!\n\nTu de nós para sempre desterrado!\nNós sem ti para sempre! Horrível dia!\nMísero povo! Infausta monarquia!\nRígida lei do inexorável Fado!\n\nÁureas, vãs esperanças concebemos...\nEi-las, ei-las em cinzas no jazigo\nCom teu rosto adorável, que perdemos.\n\nAh! Que é do nosso generoso abrigo?\nQue fazemos no mundo, ah! que fazemos,\nQue nos não vamos sepultar contigo?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 157, «Sobre o mesmo assunto»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-por-terra-jaz-o-emporio-do-oriente": {"t":["Por terra jaz o empório do Oriente,\nQue do rígido Afonso o ferro, o raio\nAo gran'filho ganhou do gran'sabaio,\nEnvergonhando o deus armipotente;\n\nCaiu Goa, terror antigamente\nDo naire vão, do pérfido malaio,\nDe bárbaras nações!... Ah! Que desmaio\nApaga o márcio ardor da lusa gente?\n\nOh séculos d'heróis! Dias de glória!\nVarões excelsos, que apesar da morte\nViveis na tradição, viveis na história!\n\nAlbuquerque terrível, Castro forte,\nMenezes, e outros mil, vossa memória\nVinga as injúrias, que nos faz a sorte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 158, «À decadência do império português na Ásia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-rompe-os-ares-pelouro-sibilante": {"t":["Rompe os ares pelouro sibilante\nDa Guerra iníqua pelas mãos forjado,\nE para te prostrar, Pireno amado,\nVoa com ele a Parca devorante:\n\nCerras teus olhos, despe o teu semblante\nAquela viva cor de que era ornado,\nE sobes, da matéria desatado,\nEspírito feliz, ao céu brilhante:\n\nNa dura, marcial, honrosa lida,\nEntre os braços da Glória heróico, e forte,\nRecebeste a cruel, mortal ferida:\n\nAh! que inveja me faz a tua sorte!...\nÉ viver como eu vivo infausta vida,\nE morrer como tu ditosa morte!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 159, «Ao Guarda-Marinha Prudêncio Rebelo Palhares, morto no combate de Argel»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-adamastor-cruel-de-teus-furores": {"t":["Adamastor cruel! De teus furores\nQuantas vezes me lembro horrorizado!\nOh monstro! Quantas vezes tens tragado\nDo suberbo oriente os domadores!\n\nParece-me que entregue a vis traidores\nEstou vendo Sepúlveda afamado,\nCo'a esposa, e c'os filhinhos abraçado,\nQual Mavorte com Vênus e os Amores:\n\nParece-me que vejo o triste esposo,\nPerdida a tenra prole, e a bela dama,\nAs garras dos leões correr furioso:\n\nBem te vingaste em nós do afouto Gama!\nPelos nossos desastres és famoso;\nMaldito Adamastor! Maldita fama!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 160, «As predições de Adamastor realizadas contra os portugueses»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSuberbo: forma antiga de «soberbo», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-cala-a-boca-satirico-poeta": {"t":["Cala a boca, satírico poeta,\nNão te metas no rol dos maldizentes;\nNão tragas os mestiços entre dentes,\nRestitui ao carcás a ervada seta;\n\nDizes que é má nação, que é casta abjeta,\nFruto de enxertos vis? Irra! Tu mentes;\nVai ver-lhe os seus papéis; são descendentes\nDo solar d'Hidalcão por linha reta:\n\nVêm d'heróis, quais não viu Cartago ou Roma;\nDe seus avós, andantes cavaleiros,\nA chusma de brasões não cabe em soma:\n\nE (se não mentem certos noveleiros)\nA muitos d'eles concedeu Mafoma\nO foro de fidalgos-escudeiros."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 161, «À infatuação que predominava em certos naturais de Goa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-das-terras-a-pior-tu-es-oh-goa": {"t":["Das terras a pior tu és, oh Goa,\nTu pareces mais ermo, que cidade;\nMas alojas em ti maior vaidade\nQue Londres, que Paris, ou que Lisboa:\n\nA chusma de teus íncolas pregoa\nQue excede o gran'Senhor na qualidade;\nTudo quer senhoria; o próprio frade\nAlega, para tê-la, o jus da c'roa!\n\nDe timbres prenhe estás; mas ouro e prata\nEm cruzes, com que d'antes te benzias,\nFoge a teus infanções de bolsa chata:\n\nOh que feliz, e esplêndida serias,\nSe algum fusco Merlim, que faz bagata,\nTe alborcasse a pardaus as senhorias!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 164, «Ao mesmo (À infatuação que predominava em certos naturais de Goa)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-preside-o-neto-da-rainha-ginga": {"t":["Preside o neto da rainha Ginga\nA corja vil, aduladora, insana:\nTraz sujo moço amostras de chanfana,\nEm copos desiguais se esgota a pinga:\n\nVem pão, manteiga, e chá, tudo à catinga;\nMasca farinha a turba americana;\nE o ourango-outang a corda à banza abana,\nCom gestos e visagens de mandinga:\n\nUm bando de comparsas logo acode\nDo fofo Conde ao novo Talaveiras;\nImprovisa berrando o rouco bode:\n\nAplaudem de contínuo as frioleiras\nBelmiro em ditirambo, o ex-frade em ode:\nEis aqui de Lereno as quartas feiras."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 190, «Descreve uma sessão da «Academia de Belas Letras de Lisboa», mais conhecida pela denominação de «Nova Arcádia»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-tendo-que-fazer-apolo-um-dia": {"t":["Não tendo que fazer Apolo um dia\nÀs Musas disse: «Irmãs, é benefício\nVadios empregar; demos ofício\nAos sócios vãos da magra Academia:\n\n«O Caldas satisfaça a padaria;\nO França d'enjoar tenha exercício,\nE o autor do entremez do rei egípcio\nO Pégaso veloz conduza à pia:\n\n«Vá na Ulisseia tasquinhar o ex-frade;\nDa sala o Quintanilha acenda as velas,\nEm se juntando alguma sociedade:\n\n«Bernardes nênia faça, e roa n'elas;\nE Belmiro, por ter habilidade,\nComo d'antes, trabalhe em bagatelas.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 192, «Aos mesmos (sócios da Nova Arcádia)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-triste-malfadada-academia": {"t":["Oh triste malfadada Academia!\nO vate Elmano em sátiras se espraia;\nFervem correios ao loquaz Talaia,\nQue a todos teu descrédito anuncia:\n\nApolo exulta, o povo te assobia;\nA glória tua em convulsões desmaia;\nAh! primeiro que a pobre em terra caia,\nCorte-se o voo da fatal porfia:\n\nAo satírico audaz põe duro freio,\nPune o declamador, que te flagela;\nDá-lhe assento outra vez no magro seio:\n\nBem como a quem profana uma donzela,\nQue em pena do afrontoso estupro feio\nFazem próvidas leis casar com ela."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 196, «À Nova Arcádia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sanhudo-inexoravel-despotismo": {"t":["Sanhudo, inexorável Despotismo,\nMonstro que em pranto, em sangue a fúria cevas,\nQue em mil quadros horríficos te enlevas,\nObra da Iniquidade, e do Ateísmo:\n\nAssanhas o danado Fanatismo\nPorque te escore o trono onde te enlevas;\nPorque o sol da Verdade envolva em trevas,\nE sepulte a Razão n'um denso abismo:\n\nDa sagrada Virtude o colo pisas,\nE aos satélites vis da prepotência\nDe crimes infernais o plano gizas:\n\nMas, apesar da bárbara insolência,\nReinas só no ext'rior, não tiranizas\nDo livre coração a independência."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 203, «Contra o despotismo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-liberdade-onde-estas-quem-te-demora": {"t":["Liberdade, onde estás? Quem te demora?\nQuem faz que o teu influxo em nós não caia?\nPor que (triste de mim!) por que não raia\nJá na esfera de Lísia a tua aurora?\n\nDa santa redenção é vinda a hora\nA esta parte do mundo, que desmaia:\nOh! Venha... Oh! Venha, e trêmulo descaia\nDespotismo feroz, que nos devora!\n\nEia! Acode ao mortal, que frio e mudo\nOculta o pátrio amor, torce a vontade,\nE em fingir, por temor, empenha estudo:\n\nMovam nossos grilhões tua piedade;\nNosso númen tu és, e glória, e tudo,\nMãe do gênio e prazer, oh Liberdade!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 204, «Aspirações do Liberalismo, excitadas pela Revolução Francesa, e consolidação da República em 1797»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-liberdade-querida-e-suspirada": {"t":["Liberdade querida, e suspirada,\nQue o Despotismo acérrimo condena;\nLiberdade, a meus olhos mais serena\nQue o sereno clarão da madrugada!\n\nAtende à minha voz, que geme e brada\nPor ver-te, por gozar-te a face amena;\nLiberdade gentil, desterra a pena\nEm que esta alma infeliz jaz sepultada:\n\nVem, oh deusa imortal, vem, maravilha,\nVem, oh consolação da humanidade,\nCujo semblante mais que os astros brilha:\n\nVem, solta-me o grilhão d'adversidade;\nDos céus descende, pois dos céus és filha,\nMãe dos prazeres, doce Liberdade!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 205, «Reprodução do antecedente, estando o autor preso»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-a-prole-de-antenor-degenerada": {"t":["A prole de Antenor degenerada,\nO débil resto dos heróis troianos,\nEm jugo vil de aspérrimos tiranos,\nTinha a curva cerviz já calejada:\n\nEra triste sinônimo do nada\nA morta liberdade envolta em danos;\nMas eis que irracionais vão sendo humanos,\nGraças, oh Corso excelso, à tua espada!\n\nTu, purpúreo reitor; vós, membros graves,\nTremei na cúria da sagaz Veneza;\nTrocam-se as agras leis em leis suaves:\n\nRestaura-se a razão, cai a grandeza,\nE o feroz despotismo entrega as chaves\nAo novo redentor da natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 206, «Por ocasião dos favoráveis sucessos obtidos na Itália, pelas tropas francesas, sob o comando de Bonaparte»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-sinto-me-arrojasse-o-duro-fado": {"t":["Não sinto me arrojasse o duro fado\nN'esta abóbada feia, horrenda, escura,\nN'esta dos vivos negra sepultura,\nOnde a luz nunca entrou do sol dourado:\n\nNão me consterna o ver-me traspassado\nCom mil golpes cruéis da desventura,\nPorque bem sei que a frágil criatura\nRaramente é feliz no mundo errado:\n\nNão choro a liberdade, que enleiada\nTenho em férreas prisões, e a paz ditosa,\nQue voou da minh'alma atribulada:\n\nSó sinto que Marília rigorosa\nEntre os braços de Aônio reclinada\nZombe da minha sorte lastimosa."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 207, «Feito na prisão»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nEnleiada: forma antiga de «enleada», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-n-esta-do-feio-oprobrio-estancia-feia": {"t":["N'esta, do feio opróbrio estância feia,\nQue abafas, mãe das trevas, com teu manto,\nMuda tristeza, carrancudo espanto\nO amotinado espírito me anseia:\n\nDas sombras abrigada a frágil teia\nUrde Aracne sagaz de canto em canto,\nMinha imaginação faz outro tanto,\nMil tristes pensamentos forma, enleia:\n\nMinha imaginação de algoz me serve,\nForçando-me a que os gostos d'algum dia\nSubmersos d'este horror no abismo observe:\n\nD'encontradas visões na fantasia\nBaralhado tropel me cai, me ferve,\nE n'esta confusão reluz Armia."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 208, «Recordações da amada, jazendo no cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quando-na-rosea-nuvem-sobe-o-dia": {"t":["Quando na rósea nuvem sobe o dia\nDe risos esmaltando a natureza,\nBem que me aclare as sombras da tristeza\nUm tempo sem-sabor me principia:\n\nQuando por entre os véus da noute fria\nA máquina celeste observo acesa,\nD'angústias, de terror a imagens presa\nComeça a devorar-me a fantasia.\n\nPor mais ardentes preces, que lhe faço,\nMeus ais não ouve o númen sonolento,\nNem prende a minha dor com tênue laço:\n\nNo inferno se me troca o pensamento;\nCéus! Por que hei de existir, por que, se passo\nDias d'enjoo, e noutes de tormento?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 209, «Na solidão do cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-folheando-os-anais-da-antiguidade": {"t":["Folheando os anais da antiguidade,\nLendo n'eles, oh Píramo, o teu fado,\nVendo o peito d'Elisa atravessado\nDo ferro, que empunhou cruel saudade:\n\nChamado pela voz da Liberdade,\nDo Desengano pela mão guiado,\nFui jurar da Razão no altar sagrado\nRancor eterno à cega divindade:\n\nMas o traidor, que aos mesmos céus se atreve\nNotando no meu voto o seu desdouro,\nDe fazer-me perjuro astúcias teve:\n\nMostrou-me de mil graças um tesouro,\nE obrigou-me a beber por mãos de neve\n«Refinado veneno em taça d'ouro.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 210, «Glosando o mote: «Refinado veneno em taça d'ouro»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-idosa-fada-que-nos-astros-lia": {"t":["Idosa fada, que nos astros lia,\nMil males me agourou com turvo aspecto;\nMil males me agourou, mas indiscreto\nTratei de falsa a negra profecia:\n\nDepois d'aquele brusco, infausto dia\nSempre velando as noutes inquieto,\nGransnar sinistro corvo sobre o teto.\nPiar aflito mocho à porta ouvia:\n\nVi d'um loureiro o tronco fulminado,\nVi d'um cometa o resplendor temível,\nVi feias sombras voltejar-me ao lado:\n\nE vejo-te nas mãos da morte horrível,\nOh minha Fílis! — Eis verificado\n«O desmentido oráculo terrível.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 211, «Glosando o mote: «O desmentido oráculo terrível»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nGransnar: assim nas edições de 1853 e 1875 (por «grasnar»), mantido.\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Filis > Fílis.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quem-se-ve-maltratado-e-combatido": {"t":["Quem se vê maltratado, e combatido\nPelas cruéis angústias da indigência\nQuem sofre de inimigos a violência,\nQuem geme de tiranos oprimido:\n\nQuem não pode ultrajado, e perseguido\nAchar nos céus, ou nos mortais clemência,\nQuem chora finalmente a dura ausência\nDe um bem, que para sempre está perdido:\n\nFolgará de viver, quando não passa\nNem um momento em paz, quando a amargura\nO coração lhe arranca e despedaça?\n\nAh! Só deve agradar-lhe a sepultura,\nQue a vida para os tristes é desgraça,\n«A morte para os tristes é ventura.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 212, «Glosando o mote: «A morte para os tristes é ventura»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-do-velho-ertilio-magico-afamado": {"t":["Do velho Ertílio, mágico afamado,\nMeus passos dirigi ao antro escuro,\nBradei-lhe: «— Oh semideus, que em teu conjuro\nTens dom, que força o báratro inflamado!\n\nSe hei de ser com Tirsália desgraçado,\nMe dize; pois que lendo no éter puro,\nAlças o véu do túrbido futuro,\nSopras a névoa, que rodeia o fado.»\n\nEis n'isto o mago vezes três meneia\nA venerável fronte, e em tom divino\nD'esta arte as esperanças me cerceia:\n\n«Pesquisar o vindouro é desatino;\nRogas-me em vão: só Júpiter folheia\n«O livro anoso do fatal destino.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 213, «Glosando o mote: «O livro anoso do fatal destino»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Ertilio > Ertílio, Tirsalia > Tirsália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-elmano-de-teus-mimos-anelante": {"t":["Elmano, de teus mimos anelante,\nElmano em te admirar, meu bem, não erra;\nIncomparáveis dons tua alma encerra,\nOrnam mil perfeições o teu semblante:\n\nGranjeias sem vontade a cada instante\nClaros triunfos na amorosa guerra:\nTesouro que do céu vieste à terra,\nNão precisas dos olhos de um amante.\n\nOh! Se eu podesse, Amor, oh! se eu podesse\nCumprir meu gosto! Se em altar sublime\nOs incensos de Jove a Lília desse!\n\nFolgara o coração quanto se oprime;\nE a Razão, que os excessos aborrece,\nNotando a causa, relevara o crime."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 214, «Desejo amante»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Lilia > Lília.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-noturno-horroroso-pesadelo": {"t":["De noturno, horroroso pesadelo\nFui na mente sombria atormentado;\nInda palpito, da visão lembrado,\nEsfria o sangue, eriça-se o cabelo:\n\nVi d'um lado a Desgraça impondo o selo\nÀs leis, que em dano meu criara o Fado;\nMeus Males em tropel vi d'outro lado\nAis dirigindo a corações de gelo.\n\nCo'a pátria, mundo, e céu me vi malquisto,\nAo longe a Glória laureada, e bela,\nOuvi dizer-me: — «De te honrar desisto!» —\n\nTive a Morte ante mim torva, amarela;\nFúrias, Manes: — O horror não parou n'isto,\nVi Nise, e o meu rival nos braços d'ela."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 215, «À infidelidade de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nIrriça-se > eriça-se.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nise-mimosa-como-as-gracas-pura": {"t":["Nise mimosa, como as Graças pura,\nAmável Nise como as Graças bela,\nSe inda em teus olhos me pertence aquela\nMaviosa afeição, que fere, e cura:\n\nUm ai, penhor de cândida ternura,\nEnvia ao triste, que esmorece, anela;\nQue em ti cuidando solitário vela\nNo seio antigo de masmorra escura:\n\nManda-lhe um ai, meu bem; com ele afaga\nDo ansioso amante o coração ferido,\nA quem mordaz saudade assanha a chaga:\n\nDas minhas aflições compadecido\nNas asas cor de neve Amor o traga;\nPago será com mil um só gemido."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 216, «A Nise, escrito do cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nas-horas-de-morfeu-vi-a-meu-lado": {"t":["Nas horas de Morfeu vi a meu lado\nPavoroso gigante, enorme vulto:\nTinha na mão sinistra, e quase oculto,\nVolume em férrea pasta enquadernado:\n\n— Ah! Quem és (lhe pergunto arrepiado)\nMereces o meu ódio, ou o meu culto?\n«Sou (me diz) o que em sombras te sepulto,\nSou teu perseguidor, teu mal, teu Fado.\n\n«Corres, triste mortal, por minha conta;\nMas há de a meu despeito haver quem corte\nA série de tormentos, que te afronta:\n\n«Poder vem perto, que te mude a sorte:\nLá tens o teu regresso...» — E n'isto aponta,\nOlho rapidamente, e vejo a Morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 217, «A Morte único refúgio contra as perseguições da Sorte»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nEnquadernado: forma antiga de «encadernado», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aceso-no-almo-ardor-que-a-mente-inflama": {"t":["Aceso no almo ardor, que a mente inflama,\nVivo de Amor, de Amor suspiro e canto;\nNa face agora o riso, agora o pranto,\nD'árvore tua, oh Febo, eu cinjo a rama:\n\nPrezo a doce moral, na voz da fama\nMeu nome pouco a pouco aos céus levanto;\nMas turba vil, que abato, anseio e espanto,\nUrde em meu dano abominável trama;\n\nRéu me delata de hórrida maldade,\nProjeta aniquilar-me o bando rude,\nEnvolto na leteia escuridade:\n\nQue falsa ideia, oh zoilos, vos ilude?\nFurtais-me a paz? Furtais-me a liberdade?\nFica-me a glória, fica-me a virtude."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 218, «Escrito no cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-bem-hajas-oh-morfeu-a-fantasia": {"t":["Bem hajas, oh Morfeu! A fantasia\nQue cena divinal me deste agora!\nNise, qual sai da noute a grata aurora,\nSurgiu-me d'entre as sombras da agonia.\n\nMais belo inda a saudade me fingia\nO gesto encantador, que os céus namora;\nCuido que inda me afaga, que inda chora\nPranto, que morta flor viver faria.\n\nGraças, oh nume, de meus ais magoado!\nAlta mercê meu coração te deve,\nPor este acinte, que fizeste ao fado:\n\nSó tua divindade a tal se atreve;\nMas ah! Que eras prazer de um desgraçado\nSempre mostraste, oh sonho, em ser tão breve."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 219, «Agradecendo a Morfeu um sonho feliz»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-na-acesa-fantasia-estou-medindo": {"t":["Na acesa fantasia estou medindo\nOs passos, e as ações da minha amada;\nNoto-lhe o puro colo, a mão nevada,\nOs olhos divinais, o gesto lindo:\n\nVejo-a com doces lágrimas sentindo\nMinha acerba opressão de horror cercada,\nE em torno da beleza amargurada\nAs Graças soluçando, Amor carpindo:\n\nA tudo quanto a vê, quanto a rodeia\nTé mesmo irracional e inanimado,\nObriga a suspirar, comove, anseia:\n\nE de a ter com meus males consternado\nTalvez lá na profunda estância feia\nDê também algum ai meu duro fado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 220, «Recordações da sua amada no cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-excedo-lustros-seis-por-mais-tres-anos": {"t":["Excedo lustros seis por mais três anos,\nMas bem que juvenis meus anos sejam,\nJá murcham de agonia, e já me alvejam\nNão raros na cabeça os desenganos.\n\nOs fados, meus verdugos, meus tiranos,\nQue de Pandora o cofre em mim despejam,\nFolgam de que os mortais nas cans me vejam\nTristes amostras de frequentes danos.\n\nParece que devia a formosura\nVingar-me dos cruéis comigo irados,\nE da ternura o prêmio ser ternura:\n\nMas Nise (oh vãos extremos desgraçados!)\nNa trança infausta branquear procura\nO resto escuro, que escapou aos fados."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 221, «Deplorando a crueldade de Nise»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-sordida-masmorra-aferrolhado": {"t":["Em sórdida masmorra aferrolhado,\nDe cadeias aspérrimas cingido,\nPor ferozes contrários perseguido,\nPor línguas impostoras criminado:\n\nOs membros quase nus, o aspecto honrado\nPor vil boca, e vil mão roto, e cuspido,\nSem ver um só mortal compadecido\nDe seu funesto, rigoroso estado:\n\nO penetrante, o bárbaro instrumento\nDe atroz, violenta, inevitável morte\nOlhando já na mão do algoz cruento:\n\nInda assim não maldiz a iníqua sorte,\nInda assim tem prazer, sossego, alento,\nO sábio verdadeiro, o justo, o forte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 222, «A constância do sábio superior aos infortúnios»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tu-que-em-torpes-desejos-atolado": {"t":["Tu, que em torpes desejos atolado\nVergonhosos prostíbulos frequentas:\nTu, que os olhos famintos alimentas\nNo cofre, de tesouros atulhado:\n\nTu, que do ouro e da púrpura adornado\nQuase d'igual a Júpiter ostentas,\nBebendo as frases vis, e peçonhentas\nDe bando adulador, que tens ao lado:\n\nMonstros, que desonrais a humanidade,\nDesprezando a pobreza atribulada,\nE transgredindo a lei da caridade:\n\nO Desengano ouvi, que assim vos brada:\n«Tremei da pavorosa eternidade,\nTremei, filhos do pó, filhos do nada!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 223, «Desengano aos viciosos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-os-milhoes-de-aureos-lustres-coruscantes": {"t":["Os milhões de áureos lustres coruscantes\nQue estão d'azul abóbada pendendo:\nO sol, e a que ilumina o trono horrendo\nD'essa, que amima os ávidos amantes:\n\nAs vastíssimas ondas arrogantes,\nSerras d'espuma contra os céus erguendo,\nA leda fonte humilde o chão lambendo,\nLourejando as searas flutuantes:\n\nO vil mosquito, a próvida formiga,\nA rama chocalheira, o tronco mudo,\nTudo que há Deus a confessar me obriga:\n\nE para crer n'um braço, autor de tudo,\nQue recompensa os bons, que os maus castiga,\nNão só da fé, mas da razão me ajudo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 224, «A existência de Deus, provada pelas obras da criação»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-filho-espirito-e-pai-tres-e-um-somente": {"t":["Filho, Espírito, e Pai, três e um somente,\nQue extraíste do caos, do pó, do nada\nO sol dourado, a lua prateada,\nO racional, e irracional vivente:\n\nEterno, justo, imenso, omnipotente,\nQue ocupas essa abóbada estrelada,\nGran'Ser, de cuja força ilimitada\nA máquina do mundo está pendente:\n\nTu, que, se queres, furacão violento,\nSumatra feia, tempestade escura\nDesatas, e subjugas n'um momento:\n\nCriador, que remiste a criatura,\nQuebra o furor do túmido elemento,\nQue nos abre no inferno a sepultura!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 225, «Deprecatório, em ocasião de tempestade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-rei-dos-reis-oh-arbitro-do-mundo": {"t":["Oh rei dos reis, oh árbitro do mundo,\nCuja mão sacrossanta os maus fulmina,\nE a cuja voz terrífica, e divina\nLúcifer treme no seu caos profundo!\n\nLava-me as nódoas do pecado imundo,\nQue as almas cega, as almas contamina:\nO rosto para mim piedoso inclina,\nDo eterno império teu, do céu rotundo:\n\nEstende o braço, a lágrimas propício,\nSolta-me os ferros, em que choro e gemo\nNa extremidade já do precipício:\n\nDe mim próprio me livra, oh Deus supremo!\nPorque o meu coração propenso ao vício\nÉ, senhor, o contrário que mais temo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 226, «Afetos de um coração contrito»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-te-adornas-de-sa-filosofia": {"t":["Se te adornas de sã filosofia\nE pio coração, por que o desmentes,\nMantendo contra as lindas inocentes\nPerante a séria mãe tenaz porfia?\n\nSe um caráter ingênuo desafia\nTua voz a dizer tudo o que sentes,\nConsidera também que tens presentes\nA virtude, a beleza, a fidalguia.\n\nDespindo a magistral severidade\nConfessa que de uns olhos a brandura\nÉ carta de favor, que persuade:\n\nSê digno preceptor, mas com doçura:\nMil desculpas merece a tenra idade,\nE mil adorações a formosura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 227, «Conselhos a um Preceptor austero»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-o-filho-do-gran-rei-que-a-monarquia": {"t":["O filho do gran'rei, que a monarquia\nTem lá nos céus, e que de si procede,\nHoje mudo e submisso à fúria cede\nDe um povo, que foi seu, que à morte o guia:\n\nDe trevas, de pavor se veste o dia,\nInchado o mar o seu limite excede,\nConvulsa a terra por mil bocas pede\nVingança de tão nova tirania:\n\nSacrílego mortal, que espanto ordenas,\nQue ignoto horror, que lúgubre aparato!...\nTu julgas teu juiz!... Teu Deus condenas!\n\nAh! Castigai, senhor, o mundo ingrato:\nCaiam-lhe as maldições, chovam-lhe as penas,\nTambém eu morra, que também vos mato."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 228, «À Paixão de Jesus-Cristo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-considero-o-triste-abatimento": {"t":["Se considero o triste abatimento\nEm que me faz jazer minha desgraça,\nA desesperação me despedaça\nNo mesmo instante o frágil sofrimento:\n\nMas súbito me diz o pensamento\nPara aplacar-me a dor, que me traspassa,\nQue este, que trouxe ao mundo a lei da graça,\nTeve n'um vil presepe o nascimento:\n\nVejo na palha o redentor chorando,\nAo lado a mãe, prostrados os pastores,\nA milagrosa estrela os reis guiando:\n\nVejo-o morrer depois, oh pecadores,\nPor nós, e fecho os olhos adorando\nOs castigos do céu como favores."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 229, «Sentimentos de conformidade, colhidos na religião»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nos-campos-o-vilao-sem-sustos-passa": {"t":["Nos campos o vilão sem sustos passa,\nInquieto na corte o nobre mora;\nO que é ser infeliz aquele ignora,\nEste encontra nas pompas a desgraça:\n\nAquele canta e ri; não se embaraça\nCom essas cousas vãs que o mundo adora:\nEste (oh cega ambição!) mil vezes chora,\nPorque não acha bem que o satisfaça:\n\nAquele dorme em paz no chão deitado,\nEste no ebúrneo leito precioso\nNutre, exaspera velador cuidado:\n\nTriste, sai do palácio majestoso;\nSe hás de ser cortesão, mas desgraçado,\nAntes ser camponês, e venturoso!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 230, «Contraste entre a vida campestre e a das cidades»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tu-de-quantos-dragoes-o-inferno-encerra": {"t":["Tu de quantos dragões o inferno encerra\nÉs o pior, Inveja pestilente!\nMorde a virtude, ao mérito faz guerra\nTeu detestável, teu maligno dente:\n\nAtenas por teu mando iniquamente\nO defensor Temístocles desterra;\nO gran' Pacheco, o raio do Oriente,\nPor ti cruel, sem funerais se enterra:\n\nLívidas gotas de infernal peçonha\nCuspiste sobre o néctar, que a ventura\nPor mãos de neve me ofreceu risonha:\n\nE depois de tragar-me a Parca dura,\nHá de ir ainda a tua voz medonha\nMinha cinza afrontar na sepultura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 231, «Contra a Inveja»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABAB BABA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tu-por-deus-entre-todas-escolhida": {"t":["Tu, por Deus entre todas escolhida,\nVirgem das virgens, tu, que do assanhado\nTartáreo monstro com teu pé sagrado\nEsmagaste a cabeça entumecida:\n\nDoce abrigo, santíssima guarida\nDe quem te busca em lágrimas banhado,\nCorrente com que as nódoas do pecado\nLava uma alma, que geme arrependida:\n\nVirgem, d'estrelas nítidas c'roada,\nDo Espírito, do Pai, do Filho eterno\nMãe, filha, esposa, e mais que tudo amada:\n\nValha-me o teu poder, e amor materno;\nGuia este cego, arranca-me da estrada,\nQue vai parar ao tenebroso inferno!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 232, «Invocando o amparo da Virgem Santíssima»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-senhor-que-estas-no-ceu-que-ves-na-terra": {"t":["Senhor, que estás no céu, que vês na terra\nMeu frágil coração desfeito em pranto,\nPelas ânsias mortais, o ardor, o encanto\nCom que lhe move Amor terrível guerra:\n\nJá que poder imenso em ti se encerra,\nJá que aos ingênuos ais atendes tanto,\nSocorre-me entre os santos sacrossanto,\nCriminosas paixões de mim desterra:\n\nFugir aos laços de um gentil semblante\nNão posso eu só: da tua mão preciso,\nCom que prostrou David o atroz gigante:\n\nFira-me a contrição, torne-me o siso,\nAcode-me, senhor, põe-me diante\n«Morte, Juízo, Inferno e Paraíso.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 233, «Glosando o mote: «Morte, Juízo, Inferno e Paraíso»»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-miseranda-inocencia-es-nome-abstrato": {"t":["Miseranda Inocência és nome abstrato,\nÉs um título vão da humanidade;\nQuando se envolve em sombras a verdade,\nQuando sofres do crime o duro trato:\n\nQue importa que eu conserve o peito intacto\nDas peçonhentas fezes da maldade;\nQue em cumprir tuas leis, oh probidade,\nFosse meu coração fiel e exato?\n\nQue importa, se a calúnia m'o desmente,\nSe o ser do parecer é tão diverso,\nE em vão se opõe o interno ao aparente?\n\nOpinião, rainha do universo,\nAnte o teu tribunal omnipotente\nSócrates ímpio foi, e eu sou perverso!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 234, «Contando-se por vítima de acusações caluniosas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-n-este-horrivel-sepulcro-da-existencia": {"t":["N'este horrível sepulcro da existência\nO triste coração de dor se parte;\nA mesquinha razão se vê sem arte,\nCom que dome a frenética impaciência:\n\nAqui pela opressão, pela violência\nQue em todos os sentidos se reparte,\nTransitório poder quer imitar-te,\nEterna, vingadora omnipotência!\n\nAqui onde o que o peito abrange, e sente,\nNa mais ampla expressão acha estreiteza,\nNegra ideia do abismo me assombra a mente.\n\nDifere acaso da infernal tristeza\nNão ver terra, nem céu, nem mar, nem gente,\nSer vivo, e não gozar da natureza?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 235, «Deplorando a solidão do cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sonho-cruel-o-espirito-inquieto": {"t":["Sonho cruel o espírito inquieto\nMe arrebatou a incógnita morada;\nEra de bronze a temerosa entrada,\nDe bronze o pavimento, o muro, o teto:\n\nEnte disforme, de rugoso aspecto,\nD'alto assento me diz com voz pesada:\n«Té que do meu furor te abrigue o nada,\nFulminei contra ti este decreto:\n\n«Os foros perderás da humanidade,\nTeus flagelos serão teus semelhantes,\nHão de extorquir-te a glória e a liberdade:»\n\nN'isto acordo c'os membros titubantes:\nAssim temeste, ouvindo, oh férrea Idade,\nA queda horrenda, que esmagou gigantes."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 236, «Ao despertar d'um sonho terrível»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-minh-alma-quer-lutar-com-meu-tormento": {"t":["Minh'alma quer lutar com meu tormento;\nContenda inútil! É por ele o Fado:\nApenas de oprimir-me está cansado\nEterna força lhe refaz o alento:\n\nMais vale que delire o pensamento\nTé agora co'a Razão debalde armado;\nE menos triste, menos duro estado\nA Desesperação, que o Sofrimento:\n\nA Desesperação soluça e chora,\nA Desesperação mil ais desata,\nParte do mal nas queixas se evapora:\n\nO Sofrimento azeda o que recata;\nPrende suspiros, lágrimas devora,\nTiraniza, consome, e às vezes mata."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 237, «Contenda entre a Desesperação e o Sofrimento»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vos-credulos-mortais-alucinados": {"t":["Vós, crédulos mortais, alucinados\nDe sonhos, de quimeras, de aparências,\nColheis por uso erradas consequências\nDos acontecimentos desastrados:\n\nSe à perdição correis precipitados\nPor cegas, por fogosas impaciências,\nIndo a cair, gritais que são violências\nD'inexoráveis céus, de negros fados:\n\nSe um celeste poder tirano, e duro,\nÀs vezes extorquisse as liberdades,\nQue prestava, oh Razão, teu lume puro?\n\nNão forçam corações as divindades;\nFado amigo não há, nem fado escuro:\nFados são as paixões, são as vontades."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 238, «Contra os que negam o livre arbítrio nas ações humanas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tenho-assaz-conservado-o-rosto-enxuto": {"t":["Tenho assaz conservado o rosto enxuto\nContra as iras do Fado omnipotente;\nAssaz contigo, oh Sócrates, na mente\nÀ dor neguei das queixas o tributo:\n\nSinto engelhar-se da constância o fruto,\nCai no meu coração nova semente;\nJá me não vale um ânimo inocente;\nGritos da Natureza! Eu vos escuto.\n\nJazer mudo entre as garras da Amargura,\nD'alma estoica aspirar à vã grandeza,\nQuando orgulho não for, será loucura.\n\nNo 'spírito maior sempre há fraqueza,\nE, abafada no horror da desventura,\nCede a Filosofia à Natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 239, «A filosofia prestes a ceder aos golpes da adversidade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nao-sou-vil-delator-vil-assassino": {"t":["Não sou vil delator, vil assassino,\nÍmpio, cruel, sacrílego, blasfemo;\nUm Deus adoro, a eternidade temo,\nConheço que há vontade, e não destino:\n\nAo saber, e à virtude a fronte inclino;\nSe chora e geme o triste, eu choro, eu gemo;\nChamo à beneficência um dom supremo;\nJulgo a doce amizade um bem divino:\n\nAmo a pátria, amo as leis, precisos laços\nQue mantêm dos mortais a convivência,\nE de infames grilhões ouço ameaços!\n\nVejo-me exposto à rígida violência,\nMas folgo, e canto, e durmo nos teus braços,\nAmiga da Razão, pura Inocência."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 240, «Vendo-se exposto a tribulações imerecidas»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-queimando-o-veu-dos-seculos-futuros": {"t":["Queimando o véu dos séculos futuros\nO vate, aceso em divinais luzeiros,\nAssim cantou (e aos ecos pregoeiros\nExultaram, Sion, teus sacros muros):\n\n«O justo descerá dos astros puros\nEm deleitosos, cândidos chuveiros,\nAs feras dormirão com os cordeiros,\nSoarão doce mel carvalhos duros;\n\nA virgem será mãe; vós dareis flores,\nBrenhas intonsas, em remotos dias;\nPorás fim, torva guerra, a teus horrores.»\n\nNão, não sonhou o altíssono Isaías;\nOh reis, ajoelhai, correi, pastores!\nEis a prole do Eterno, eis o Messias!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 241, «Aludindo à profecia de Isaías nos cap. VII e XI, etc.»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aquele-que-domina-os-ceus-brilhantes": {"t":["Aquele, que domina os céus brilhantes,\nArtífice da máquina estrelada,\nAnte cuja grandeza os reis são nada,\nÁtomo a terra, os séculos instantes:\n\nO Deus, que contra os vícios negrejantes\nPela voz dos trovões ao homem brada,\nDa mísera virtude atropelada\nVinga os tristes suspiros penetrantes:\n\nSem que o mortal com lágrimas o peça,\nJuiz imparcial, juiz superno\nNa causa do inocente se interessa:\n\nManda-te ressurgir do horror eterno:\nDevorante remorso! Em ti começa\nO suplício dos maus, dos maus o inferno."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 242, «O Remorso (Escrito na prisão)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-a-frente-que-de-louro-ergui-cingida": {"t":["A frente, que de louro ergui cingida,\nUfana do louvor, e da inocência,\nJaz por efeito d'hórrida aparência,\nCurvada pelo opróbrio, e denegrida:\n\nDe mil gratos objetos guarnecida\nRutilava a meus olhos a existência;\nHoje, amável Prazer, na tua ausência\nParece aos olhos meus um ermo a vida.\n\nDe quantas cores se matiza o Fado!\nNem sempre o homem ri, nem sempre chora,\nMal com bem, bem com mal é temperado;\n\nOs estados variam de hora em hora;\nSábio o mortal, que em um, que em outro estado\n(Disposto a tudo) a Providência adora!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 243, «Conformidade com os decretos da Providência»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-aqui-onde-arquejando-estou-curvado": {"t":["Aqui, onde arquejando estou curvado\nÀ lei, pesada lei, que me agrilhoa,\nDe lúgubres ideias se povoa\nMeu triste pensamento horrorizado:\n\nAqui não brama o Noto anuviado,\nO Zéfiro macio aqui não voa,\nNem zune inseto alígero, nem soa\nAve de canto alegre, ou agourado;\n\nExpeliu-me de si a humanidade,\nTu, astro benfeitor da redondeza,\nNão despendes comigo a claridade:\n\nSó me cercam fantasmas da tristeza:\nQue silêncio! Que horror! Que escuridade!\nParece muda, ou morta a natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 244, «Vendo-se encarcerado e solitário»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nAnnuveado > anuviado.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tao-negro-como-a-turba-que-vagueia": {"t":["Tão negro como a turba que vagueia\nNa margem do Cocito à luz odioso,\nO bando de meus males espantoso\nNo sepulcro dos vivos me rodeia,\n\nQual me abala os fuzis da vil cadeia,\nQual me afigura um rótulo afrontoso,\nQual me diz (ai de mim!) que fui ditoso;\nEis d'eles todos o que mais me anseia.\n\nTomara reforçar pela amargura\nMeu ser, que anda c'os fados tão malquisto,\nTomara costumar-me à desventura:\n\nEsquecer-me do bem gozado, e visto,\nPensar que a natureza é sempre escura,\nQue é geral este horror, que o mundo é isto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 245, «Ao mesmo assunto»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-vos-que-lamentais-d-elmano-a-sorte": {"t":["Oh vós que lamentais d'Elmano a sorte,\nCrendo na escura terra o corpo frio,\nE os manes já sulcando o mudo rio,\nNa barca imensa de geral transporte:\n\nSabei que o doce, inevitável corte\nLhe foge da existência ao tênue fio;\nE que seria em vós dever mais pio\nChorar-lhe a vida, que chorar-lhe a morte:\n\nExistindo agoniza um desgraçado;\nQuem lágrimas nas cinzas lhe derrama\nParece que o queria atormentado;\n\nVive, mas pela morte Elmano chama,\nCom suspiros Elmano implora ao fado\nQue seja voz de agouro a voz da fama."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 246, «Aos amigos, dando-lhes a saber que ainda vive»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-meus-dias-que-ja-foram-tao-luzentes": {"t":["Meus dias, que já foram tão luzentes,\nHoje da noute opaca irmãos parecem;\nMeus dias miseráveis emurchecem\nLonge do gosto, e longe dos viventes:\n\nHorror das trevas, peso das correntes\nOlhos, forças me abatem, me entorpecem:\nE apenas por momentos me aparecem\nRostos sombrios de intratáveis entes:\n\nPagam-se da rugosa austeridade:\nAntolha-se-lhe um crime, um atentado\nSofrer nos corações a humanidade:\n\nVoai, voai do céu para meu lado,\nAh! Vinde, doce Amor, doce amizade,\nSou tão digno de vós, quão desgraçado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 247, «Descreve os seus tormentos no cárcere»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vitima-do-rigor-e-da-tristeza": {"t":["Vítima do rigor, e da tristeza,\nEm negra estância, em cárcere profundo,\nO mundo habito sem saber do mundo,\nComo que não pertenço à natureza:\n\nEnquanto pela vasta redondeza\nVai solto o crime infesto, o vício imundo,\nEu (não perverso) em pranto a face inundo,\nDo grilhão suportando a vil dureza:\n\nMas no bojo voraz da desventura,\nMonstro por cujas faces fui tragado,\nEm parte um pensamento a dor me cura:\n\nO infeliz (não por culpa, só por fado)\nN'aqueles corações em que há ternura,\nÉ mais interessante, é mais amado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 248, «Lenitivos do sofrimento contra as perseguições da desventura»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-para-as-sombras-da-morte-aqui-me-ensaio": {"t":["Para as sombras da morte aqui me ensaio\nNa habitação da culpa e do desdouro;\nLendo no mal presente o mal vindouro,\nAqui choro, aqui tremo, aqui desmaio:\n\nPor imagens fatais a ideia espraio,\nNegreja n'uma, e n'outra infausto agouro;\nFebo! Oh Febo! Ai de mim! Teu sacro louro\nA fronte não me escuda contra o raio.\n\nSou vítima de aspérrima violência,\nSem ter quem dos meus males se lastime\nN'este horrível sepulcro da existência:\n\nMas peso dos remorsos não me oprime;\nA sussurrante, a vil Maledicência\nD'erros dispersos me organiza o crime."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 249, «Sobre o mesmo assunto»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-do-tempo-sobre-as-asas-volve-o-dia": {"t":["Do Tempo sobre as asas volve o dia,\nO ponto de meu triste nascimento;\nVedado à luz do sol este momento,\nFúrias, com vossos fachos se alumia!\n\nNascido apenas, pavorosa harpia\nAo berço me voou de imundo alento:\nEmpestando o misérrimo aposento,\nEis me roga esta praga horrenda, impia:\n\n«Esteja sempre o bem de ti remoto,\nVivas sempre choroso, amargurado,\nDane teus dias o destino imoto.»\n\nCaiu-me a imprecação do monstro alado,\nCurto mil males, e entre sombras noto\nOutros com que me espera ao longe o fado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 250, «No seu dia natalício»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nImpia: a rima (dia, harpia, alumia) pede a pronúncia grave, im-pí-a; mantida sem acento.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nescia-vil-ignorancia-injuriada": {"t":["Néscia, vil ignorância, injuriada\nDos vivas, que meu estro me granjeia,\nDesce aos infernos, e a calúnia feia\nBramindo extrai da lôbrega morada:\n\nDo monstro de cem bocas escoltada\nPor aqui, por ali corre, vagueia,\nEm meu nome de lar em lar semeia\nAgro ditério, sátira danada:\n\nEm cínico furor me finge aceso,\nVenenoso, mordaz, ímpio me chama,\nDiz que o jugo de um rei, de um Deus desprezo.\n\nMas sempre, sobranceiro à baixa trama,\nDas pátrias justas leis me é doce o peso,\nAmo a religião, e aspiro à fama."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 251, «Protesta pela sua inocência, agredida por detratores invejosos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-pela-voz-do-trovao-corisco-intenso": {"t":["Pela voz do trovão corisco intenso\nClama, que à natureza impera um ente,\nQue cinge do áureo dia o véu ridente,\nQue veste d'atra noute manto denso:\n\nPasmar na imensidade, é crer o imenso;\nTudo em nós o requer, o adora, o sente;\nProvam-te olhos, ouvidos, peito e mente?\nNúmen, eu ouço, eu olho, eu sinto, eu penso!\n\nTua ideia, oh gran'Ser, oh Ser divino,\nMe é vida, se me dão mortal desmaio\nMales que sofro, e males que imagino:\n\nNunca impiedade em mim fez bruto ensaio;\nSempre (até das paixões no desatino)\nTua clemência amei, temi teu raio."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 252, «Hino a Deus»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-la-quando-a-tua-voz-deu-ser-ao-nada": {"t":["Lá quando a tua voz deu ser ao nada,\nFrágil criaste, oh Deus, a natureza;\nQuiseste que aos encantos da beleza\nAmorosa paixão fosse ligada:\n\nÀs vezes em seus gostos desmandada,\nNos excessos desliza-se a fraqueza;\nFingem-te então com ímpeto, e braveza\nErguendo contra nós a destra armada:\n\nOh almas sem acordo, e sem brandura,\nFalsos órgãos do Eterno! Ah!... Profanai-o,\nDando-lhe condição tirana e dura\n\nTrovejai, que eu não tremo, e não desmaio;\nSe um Deus fulmina os erros da ternura,\nUma lágrima só lhe apaga o raio."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 253, «Confiança na misericórdia divina»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-um-ente-dos-mais-entes-soberano": {"t":["Um Ente, dos mais entes soberano,\nQue abrange a terra, os céus, a eternidade;\nQue difunde anual fertilidade,\nE aplana as altas serras do oceano:\n\nUm númen só terrível ao tirano,\nNão à triste mortal fragilidade;\nEis o Deus, que consola a humanidade,\nEis o Deus da razão, o Deus d'Elmano:\n\nUm déspota de enorme fortaleza,\nPronto sempre o rigor para a ternura,\nRaio sempre na mão para a fraqueza:\n\nUm criador funesto à criatura;\nEis o Deus, que horroriza a natureza,\nO Deus do fanatismo, ou da impostura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 254, «O retrato de Deus, desfigurado por ministros embusteiros»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-encantador-garcao-tu-me-arrebatas": {"t":["Encantador Garção, tu me arrebatas\nAudaz vibrando o plectro venusino;\nSuave Albano, delicado Alcino,\nMusas do terno Amor, vós me sois gratas;\n\nAdoro altos prodígios, que relatas\nCantor da Glória, majestoso Elpino,\nTu, que agitado de ímpeto divino\nAcesos turbilhões na voz desatas:\n\nOh cisnes imortais do Tejo ameno!\nA carrancuda Inveja em mim não cria\nVíboras prenhes de infernal veneno:\n\nO clarão, que esparzis, me acende e guia:\nCulto, incenso vos dou, quando condeno\nDelírios que Belmiro ao prelo envia."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 261, «Louvando alguns poetas líricos seus contemporâneos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ao-crebro-som-do-lugubre-instrumento": {"t":["Ao crebro som do lúgubre instrumento\nCom tardo pé caminha o delinquente;\nUm Deus consolador, um Deus clemente\nLhe inspira, lhe vigora o sofrimento:\n\nDuro nó pelas mãos do algoz cruento\nEstreitar-se no colo o réu já sente;\nMultiplicada a morte anseia a mente,\nBate horror sobre horror no pensamento:\n\nOlhos e ais dirigindo à Divindade,\nSobe, envolto nas sombras da tristeza,\nAo termo expiador da iniquidade:\n\nDas leis se cumpre a salutar dureza;\nSai a alma d'entre o véu da humanidade;\nFolga a Justiça, e geme a Natureza."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 262, «Ao réu, que foi conduzido ao patíbulo no dia 11 de julho de 1797»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-sobre-o-degrau-terrivel-assomava": {"t":["Sobre o degrau terrível assomava\nO réu cingido de funéreo manto;\nAvezada ao terror, aos ais, ao pranto\nDa intrepidez a Morte se assombrava:\n\nNo firme coração não palpitava\nO percursor da Parca, o mudo espanto;\nE, ufana de subir no esforço a tanto,\nUm ai a Humanidade apenas dava:\n\nMortal, que foste herói no extremo dia,\nDe ideias carrancudas e opressoras\nNão sofreste o pavor na fantasia:\n\nCo'as vozes divinais, consoladoras,\nSó a religião te embrandecia:\nForas de ferro, se cristão não foras!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 263, «Ao mesmo assunto (o réu conduzido ao patíbulo)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-tu-que-tens-no-seio-a-eternidade": {"t":["Oh tu, que tens no seio a eternidade,\nE em cujo resplendor o sol se acende,\nGrande, imutável ser, de quem depende\nA harmonia da etérea imensidade!\n\nAmigo, e benfeitor da humanidade,\nDa mesma que te nega, e que te ofende,\nManda ao meu coração, que à dor se rende,\nManda o reforço d'eficaz piedade.\n\nOpressa, consternada a natureza\nEm mim com vozes lânguidas te implora,\nÓrgãos do sentimento, e da tristeza:\n\nA tua inteligência nada ignora;\nSabes que, de alta fé minha alma acesa,\nTé nas angústias o teu braço adora."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 285 (sem título)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-com-tenue-clarao-ja-quase-escura": {"t":["Já com tênue clarão, já quase escura\nA noturna Diana o céu volteia,\nE sobre o Tejo azul, que mal prateia,\nVai duplicando a trêmula figura:\n\nAura sutil nas árvores murmura,\nNo lago adormecido a rã vozeia,\nMocho importuno agouros mil semeia,\nD'entre as umbrosas moutas da espessura:\n\nLetárgico vapor Morfeu derrama,\nCom que insinua um doce desalento\nNo livre coração de quem não ama:\n\nTriste de mim! Se repousar intento\nOs olhos me abre Amor, Amor me inflama,\nE Anália me persegue o pensamento."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 286, «Insônia amorosa»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-vos-que-de-meus-extremos-sois-a-historia": {"t":["Vós, que de meus extremos sois a história,\nVersos, por negro zoilo em vão roubados,\nNascidos da Ternura, e restaurados\nC'o pronto auxílio de fiel memória:\n\nDa Inveja conseguindo alta vitória\nIde, meus versos, em Amor fiados,\nQue d'ele só dependem vossos fados,\nQue n'ele só demando a minha glória:\n\nNão vos importe o público juízo;\nDa voz, que pelo mundo se derrama,\nOs vivas caprichosos não preciso.\n\nVoai aos olhos, cuja luz me inflama;\nTereis de Anarda aprovador sorriso,\nUm sorriso de Anarda é mais que a Fama."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 287, «O Autor aos seus versos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-distrai-meu-coracao-tua-amargura": {"t":["Distrai, meu coração, tua amargura,\nOs males que te assanha a fantasia:\nProvém da formosura essa agonia?\nSeja o seu lenitivo a formosura;\n\nPor mil objetos adoçar procura\nO ardor, que lavra em ti de dia em dia;\nMas oh fatal poder da simpatia!\nOh moléstia d'amor, que não tem cura!\n\nAstúcia exercitar que te resista\nMinha Anália, meu bem, debalde intento,\nEstá segura em mim tua conquista.\n\nComo hei de minorar-te o vencimento,\nCoartar o império teu, se as mais à vista\nValem menos que tu no pensamento?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 288, «Assegurando Anália da sua firmeza»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 3: «Provém» (na outra digitalização da ed. 1875 e numa da ed. 1853); a digitalização-base traz «Provêm».\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-tenta-em-vao-temeraria-conjectura": {"t":["Tenta em vão temerária conjectura\nSondar o abismo do invisível Fado,\nQue, de umbrosos mistérios enlutado,\nSome aos olhos mortais a luz futura:\n\nPresumia (ai de mim!) vendo a ternura\nD'aquela, que me trouxe enfeitiçado,\nPresumia que Amor tinha guardado\nNos braços do meu bem minha ventura:\n\nOh terra! Oh céu! Mentiram-me os brilhantes\nOlhos seus, onde achei suave abrigo;\nQuão fáceis de enganar são os amantes!\n\nHumanos, que seguis as leis que sigo,\nVós, corações, que ao meu sois semelhantes,\nAh! Comigo aprendei, chorai comigo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 289, «Lamenta um desengano inesperado»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-amor-que-o-pensamento-me-salteias": {"t":["Amor, que o pensamento me salteias\nCo'as memórias d'Anália a cada instante;\nTirano, que vaidoso e triunfante\nMe apertas mais e mais servis cadeias:\n\nDoces as aflições com que me anseias,\nSe ao ver-se de meus olhos tão distante\nSoltasse Anália um ai do peito amante,\nE o fogo antigo lhe inflamasse as veias!\n\nMas é talvez o exemplo das perjuras,\nOutro amima talvez, enquanto eu choro,\nMorrendo de saudosas amarguras;\n\nE pelo ardente excesso com que adoro,\nAo clarão de medonhas conjecturas\nVejo o fantasma da traição que ignoro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 290, «Incertezas sobre a fidelidade de Anália ausente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-quando-analia-o-meu-bem-que-o-ceu-namora": {"t":["Quando Anália, o meu bem, que o céu namora,\nMeigo sorriso de outro céu desprende,\nGeme, e o que é vida n'um gemido aprende\nPeito, que amor, e que a existência ignora:\n\nQuando Anália, o meu bem, suspira, ou chora,\nA doce mágoa doce fogo acende;\nNa estância divinal com Jove entende,\nQuase tenta implorá-la o ser que implora;\n\nSente um Deus como sente a natureza\nAquela, em cujos dons adorno o canto,\nAquela, que a meus versos dá grandeza:\n\nMas (se posso antepor encanto a encanto)\nAmo-lhe o riso, adoro-lhe a tristeza;\nDe Vênus a chorar tal era o pranto!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 291, «O sorriso de Anália»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-e-doce-no-recente-ameno-estio": {"t":["Se é doce no recente, ameno estio\nVer toucar-se a manhã d'etéreas flores,\nE, lambendo as areias, e os verdores,\nMole e queixoso, deslizar-se o rio:\n\nSe é doce no inocente desafio\nOuvirem-se os voláteis amadores,\nSeus versos modulando, e seus ardores\nD'entre os aromas de pomar sombrio:\n\nSe é doce mares, céus ver anilados\nPela quadra gentil, de Amor querida,\nQue esperta os corações, flórea, os prados:\n\nMais doce é ver-te de meus ais vencida,\nDar-me em teus brandos olhos desmaiados\nMorte, morte de amor, melhor que a vida."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 292, «À mesma (Anália)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-desejo-iluso-e-vao-para-que-tracas": {"t":["Desejo iluso, e vão! Para que traças\nQuadro, que imagens divinais of'rece?\nA terna ausente amada me aparece,\nEm céu d'amores eclipsando as Graças:\n\nAnte a doce visão com que me enlaças,\nJá murcho, estéril já, meu ser florece:\nMas súbito fantasma eis desvanece\nChusma d'encantos, que em teu sonho abraças:\n\nCroado de cipreste o Desengano\nO meu nada me agoura... Oh dor mais forte\nDo que em seu grau supremo o esforço humano!\n\nChorai, Piedade, e Amor, tão triste sorte,\nChorai: longe de Anália expira Elmano;\nOs que a ternura uniu, desune a morte."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 293, «As ilusões do desejo desfeitas pela realidade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nCroado: forma sincopada de «coroado» (como c'roa), mantida.\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-planta-mimosa-de-loucaos-verdores": {"t":["Planta mimosa de louçãos verdores,\nDe amorosos perfumes! Planta bela,\nFade-te o nome do meu bem, d'aquela\nQue é céu nos olhos, néctar nos favores!\n\nGravado apenas, te dará mil flores,\nDepois mil frutos, que o desejo anela:\nSúbito irás medrando, e vós com ela,\nE vós com ela crescereis, amores!\n\nEncantava-me assim Morfeu risonho:\nElísia, recendente amenidade,\nJardim celeste respirar suponho:\n\nEis desperto na dor, na escuridade:\nUm relâmpago foi tão lindo sonho:\nTu só tens duração, cruel verdade!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 294, «Sobre o mesmo assunto do precedente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-um-nume-aos-ais-d-elmano-oh-dom-mimoso": {"t":["De um nume aos ais d'Elmano oh dom mimoso!\nTesouros meus! Aljôfares de Amores!\nAo ver-vos deslizar, cair nas flores\nDe um gesto, como os deuses, milagroso;\n\nOrvalho pareceis do céu piedoso,\nQue meigo alívio influi em agras dores,\nQue umedece estes áridos vapores,\nEste hálito da morte infesto, ansioso:\n\nSentindo o coração por ti regado,\nContigo, oh néctar, a existência encanto,\nE brando para mim se ri meu fado:\n\nAmada! Jove, e tu, só podem tanto!\nMeu mal dorme, repousa embriagado\nDas mil delícias, que me dá teu pranto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 295, «As lágrimas de Anália (Escrito no último período da sua final moléstia)»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-oh-ninfa-que-das-gracas-melindrosas": {"t":["Oh ninfa, que das graças melindrosas\nTens na face a lindeza, o riso, as cores,\nNa face mimos toda, e toda flores,\nQue é metade jasmins, metade é rosas!\n\nNinfa suave, para quem saudosas\nDou mágoas mil aos Zéfiros, e Amores!\nTu gozas de meus ais, e dos louvores\nD'estremado cantor, meu bem, tu gozas.\n\nEm sons (pincéis febeus) em sons copia\nTeu rosto, um céu; do original o encanto\nEis, eis n'alma em tumulto a imagem cria:\n\nEu vate, eu amador não logro tanto;\nAmor fogo me dá, Febo harmonia,\nE és mais no coração do que és no canto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 296, «À mesma Anália»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome(s) próprio(s) em grafia atual (acento pelo metro e pela rima): Analia > Anália.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-contigo-alma-suave-alma-formosa": {"t":["Contigo, alma suave, alma formosa,\nCeleste imagem, de que o céu me priva,\nQue eu vivesse não quis, não quer que eu viva\nLei (sendo etérea) ao coração penosa:\n\nVendo sumir-me por morada umbrosa,\nAh! Não desmaies, a constância aviva,\nE por artes de amor, de amor oh diva,\nDo não-gozado amante os manes goza:\n\nMais doce orvalho de teus olhos desça,\nÀ linda (como tu) melhor das flores,\nQue em torno à campa se abotoe, e cresça;\n\nPasseia entre os meninos voadores,\nUne a mãe aos filhinhos, e pareça\nDa morte a solidão jardim de amores."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 297, «À mesma»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-cantor-que-a-fronte-erguia-engrinaldada": {"t":["Cantor, que a fronte erguia engrinaldada\nConvosco, idálias c'roas, mirto, e rosas,\nQue viu por mão das tágides formosas\nD'aljôfares a lira, e d'ouro ornada:\n\nMente, d'etéreos dons abrilhantada,\nQue solta em produções, louçãs, pomposas,\nSurgiu, voou com asas luminosas\nAnte o bando, que vai de rojo ao nada:\n\nEstro, opulento do febeu tesouro\n(Já dos épicos sons talvez no ensaio)\nOuviu sair das trevas triste agouro:\n\nSeu fado o fulminou, bateu-lhe o raio\nÀ sombra tua (ai dor!) lá mesmo, oh louro!\nChorai-o, Amores! Tágides, chorai-o!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 298, «Últimos cantos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«A sombra» na fonte (maiúscula sem acento); atualizado para «À sombra» (a sombra do louro).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-o-destino-cruel-me-nao-consente": {"t":["Se o Destino cruel me não consente\nQue o ferro nu brandindo irado, e forte,\nLá nos horrendos campos de Mavorte\nDe louros imortais guarneça a frente:\n\nSe proíbe que em sólio refulgente\nFaça os povos felices, de tal sorte\nQue o meu nome apesar da negra morte\nFique em padrões e estátuas permanente:\n\nSe as suas ímpias leis inexoráveis\nNão querem que os mortais em alto verso\nContem de mim façanhas memoráveis:\n\nSubmisso à má ventura, ao fado adverso,\nAo menos por desgraças lamentáveis\nTerei perpétua fama no universo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 299, «Conformando-se com os reveses da Sorte»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nFelices: forma antiga de «felizes», mantida.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-pouco-a-pouco-a-letifera-doenca": {"t":["Pouco a pouco a letífera Doença\nDirige para mim trêmulos passos;\nEis seus caídos, macilentos braços,\nEis a sua terrífica presença:\n\nVirá pronunciar final sentença,\nEm meu rosto cravando os olhos baços,\nVirá romper-me à vida os tênues laços\nA fouce, contra a qual não há defensa:\n\nOh! Vem, deidade horrenda, irmã da Morte,\nVem, que esta alma avezada a mil conflitos,\nNão se assombra do teu, bem que mais forte:\n\nMas ah! Mandando ao céu meus ais contritos,\nEspero que primeiro que o teu corte\nMe acabe viva dor dos meus delitos."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 300, «Vendo-se acometido de grave enfermidade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-na-que-morna-e-lugubre-murmura": {"t":["Se na que, morna e lúgubre, murmura,\nCorrente averna, como as sombras densa,\nDer queda enorme a sôfrega Doença\nQue à vida quer sorver-me a fonte impura:\n\nDe eleitos vegetais sagaz mistura\nNão foi rígido estorvo à morte intensa;\nSó pode aos olhos meus virtude imensa\nA do horror ferrolhar morada escura:\n\nArde, oh estro! fulmina o monstro humano,\nQue origem vil ao mundo, a si presume,\nE à causa divinal repugna, insano:\n\nSalve, princípio d'alma, etéreo lume!...\nSe um Deus não fora, que seria Elmano!\nExiste o vate, porque existe o nume."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 301, «Alentos d'esperança durante o período da moléstia final»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-dura-filosofia-audaz-forceja": {"t":["Dura filosofia audaz forceja\nPor dar-me essência nova ao pensamento;\nDe bronze diz, que forre o sofrimento,\nE em brasas, como em flores, manso esteja:\n\nDiz que, oh leis de Zenon, por vós me reja;\nQue sai do alto sistema alto portento;\n«Os órgãos vivem, morre o sentimento,\nE mudo, e frio, o coração caleja.»\n\nMas ai! Mais sábio que Zenon o Eterno\nFonte às lágrimas deu, deu fonte ao riso;\nCo'a lei das sensações meu ser governo:\n\nSe eu folgasse entre o mal que em mim diviso,\nNa mente ousara unir o horror do inferno\nAos sóis, de que se esmalta o paraíso."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 302, «Insuficiência das doutrinas do Estoicismo»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-as-rigidas-licoes-do-ferreo-zeno": {"t":["Às rígidas lições do férreo Zeno\nSe torce o coração, se enruga o rosto;\nFalaz sistema, e de aridez composto,\nQue às fecundas paixões seca o terreno!\n\nPor timbre em metro d'ouro o doura Oleno,\nE, à doce natureza o nunca oposto\n(Rindo entre flores, vicejando em gosto)\nGênio desliza d'Epicuro ameno:\n\nEle (bem que o difame o vulgo rude)\nDe almos Prazeres pela mão nevada\nD'espinhos despe o trilho à sã virtude;\n\nVeste de rosas a macia estrada,\nA moral formoseia, e não me ilude\nQuerendo que de um Deus ostente um Nada."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 303, «Por ocasião de uma poesia, em que seu autor (N. A. P. Pato-Moniz) propugnava os mesmos ditames»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«As rígidas» na fonte (letra capitular, sem acento); atualizado para «Às» (o coração se torce às lições).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-em-vao-para-tecer-me-um-ledo-engano": {"t":["::epigrafe Il n'est de malheureux que les coeurs détrompés. (Voltaire, Mérope)\n\nEm vão, para tecer-me um ledo engano,\nFilósofo ostentoso indústrias cansa:\nDiz-me em vão, que exalando-se a esperança,\nRepousa na apatia o peito humano:\n\nO nauta a soçobrar no pego insano\nVê rir-se ao longe a cérula bonança;\nA mente esperançosa enfreia, amansa\nOs roncos, e as bravezas do oceano:\n\nSe nos míseros cai da mão dos fados\nO negro desengano, ei-los ansiosos,\nE à desesperação, e à fúria dados!...\n\nDourai-nos o porvir, oh céus piedosos!\nJustos céus! Deem sequer jardins sonhados\nAs flores da ventura aos desditosos!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 304 (sem título)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 11: a ed. de 1875 traz «desperação» (verso hipométrico); adotada a lição «desesperação» da ed. de 1853.\n\n«Dêm» (ed. 1875; «Dêem» na ed. 1853), monossílabo no verso; grafia atual «deem».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-no-abismo-tragador-da-humanidade": {"t":["No abismo tragador da Humanidade\n(D'ela, d'ela não só, de quanto existe)\nCo'a mesma rapidez, Elmano, ah! viste\nSumir-se a florescente, e a murcha idade!\n\nOlha em muros, que veste a escuridade,\nOlha a cor de teu fado, a cor mais triste:\nTalvez (agora!... agora!...) ele te aliste\nNo volume, em que lê a eternidade!\n\nOh tochas funerais! Clarão medonho!\nDa morte oh mudas, solitárias cenas!\nEm vós arrepiado os olhos ponho!...\n\nAh! Por que tremes, louco? Ah! Por que penas?\nSonhas n'um ermo, e surgirás do sonho\nEm climas d'ouro, em regiões amenas."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 305, «Abalado por funestos pressentimentos, colhidos em alheios sucessos»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-o-grande-o-que-nos-orbes-diamantinos": {"t":["Se o grande, o que nos orbes diamantinos\nTem curvos a seus pés dos reis os fados,\nNovamente me der ver animados\nDe modesta ventura os meus destinos:\n\nSe acordarem na lira os sons divinos,\nQue dormem (já da glória não lembrados)\nAo coro eterno cândidos, e alados\nHonrar com ele um Deus ireis, meus hinos:\n\nMas, da humana carreira inda no meio,\nSe a débil flor vital sentir murchada\nPor lei que envolta na existência veio;\n\nCo'a mente pelos céus toda espraiada,\nDirei, d'eternidade ufano e cheio:\n«Adeus, oh mundo! Oh natureza! Oh nada!»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 306, «Vendo-se indeciso acerca do termo da sua enfermidade»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-meu-ser-evaporei-na-lida-insana": {"t":["Meu ser evaporei na lida insana\nDo tropel de paixões, que me arrastava;\nAh! Cego eu cria, ah! mísero eu sonhava\nEm mim quase imortal a essência humana:\n\nDe que inúmeros sóis a mente ufana\nExistência falaz me não dourava!\nMas eis sucumbe Natureza escrava\nAo mal, que a vida em sua orgia dana.\n\nPrazeres, sócios meus, e meus tiranos!\nEsta alma, que sedenta «em si não coube,\nNo abismo vos sumiu dos desenganos:\n\nDeus, oh Deus!... Quando a morte à luz me roube\nGanhe um momento o que perderam anos,\nSaiba morrer o que viver não soube."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 307, «Sentimentos de contrição, e arrependimento da vida passada»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVerso 8: «orgia» na ed. de 1875; a ed. de 1853 (e a lição corrente) traz «origem».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ja-bocage-nao-sou-a-cova-escura": {"t":["Já Bocage não sou!... À cova escura\nMeu estro vai parar desfeito em vento...\nEu aos céus ultrajei! O meu tormento\nLeve me torne sempre a terra dura:\n\nConheço agora já quão vã figura\nEm prosa e verso fez meu louco intento;\nMusa!... Tivera algum merecimento\nSe um raio da razão seguisse pura!\n\nEu me arrependo; a língua quase fria\nBrade em alto pregão à mocidade,\nQue atrás do som fantástico corria:\n\nOutro Aretino fui... A santidade\nManchei!... Oh! Se me creste, gente impia,\nRasga meus versos, crê na eternidade!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 308, «Ditado entre as agonias do seu trânsito final»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«impia» sem acento: a rima (fria, corria) e o metro pedem «impía».","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-d-elmano-a-musa-que-entre-imagens-vela": {"t":["D'Elmano a Musa, que entre imagens vela,\nEnquanto, oh natureza, estás calada,\nCarpia do áureo Pluto abandonada,\nE Pluto era de bronze aos prantos d'ela:\n\nD'Elmano a Musa, que a memória anela,\nConforma o plectro em dor co'a voz magoada;\nE dos piedosos sons tu apiedada,\nGemes, oh Lísia, oh mãe suave, e bela:\n\nQual arde avara sede ante um tesouro,\nPátrio amor ante o metro me flameja,\nE o que em verso me extrai, me volve em ouro:\n\nD'alma em torno a sorrir-se a Glória adeja;\nE (mercê d'alta Lísia) imune o louro\nEntre as sombras letais inda verdeja."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 319, «À Pátria»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-d-elmano-antes-da-morte-e-morto-o-canto": {"t":["D'Elmano antes da morte é morto o canto,\nDo Pindo inspirações já lhe não descem;\nMas inda aos que em seus males se enternecem\nO que somente é dor, parece encanto.\n\nAh! Ditoso o que deve à pátria tanto,\nDitoso, o que altas Musas enobrecem:\nBem que afinadas opressões não cessem\nDe abrir-lhe mais e mais a fonte ao pranto!\n\nDa mente, em que fervia o gás sagrado,\nUm Deus, que respirei, já não respiro,\nUm Deus, por quem do nada estou salvado:\n\nNos versos, que te dou, talvez deliro;\nDa sorte aos meus pousar foi já mandado,\nE aos teus impõe seguir da fama o giro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 331, «Ao padre fr. José Botelho Torrezão, Em resposta»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNome do destinatário de leitura incerta no OCR («Ton^ezão»).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-ave-da-morte-que-piando-agouros": {"t":["Ave da morte, que piando agouros\nTinges meus ares de funéreo luto!\nAve da morte (que em teus ais a escuto)\nMeus dias murcharás, mas não meus louros:\n\nDoou-me Febo aos séculos vindouros,\nDeponho a flor da vida, e guardo o fruto,\nPagando em vil matéria um vão tributo,\nRetenho a posse de imortais tesouros.\n\nNome no tempo, e ser na eternidade!\nQue fado! Oh ponto escuro, assoma embora,\nDê-me o piedoso adeus comum saudade:\n\nE rindo-me na campa os dons de Flora,\nMais do que eles a adorne esta verdade:\n«Lísia cantava Elmano, e Lísia o chora.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 348, «Próximo aos seus últimos dias»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-nestoreos-dias-que-sonhava-elmano": {"t":["Nestóreos dias, que sonhava Elmano,\nBrilhantes de almos gostos, d'áurea sorte,\nPomposa fantasia, audaz transporte.\nAs asas cerceai do orgulho insano:\n\nPlano de um númen contradiz meu plano,\nE quer que se esvaeça, e quer que aborte;\nEis, eis palpita, percursor da morte,\nNo túmido aneurisma o desengano:\n\nAdeus, oh gênios que Olisseia admira!\nCantor, que honrastes, honrareis cantores,\nVersos, pranto lhe dai, que Elmano expira!\n\nDeixai-lhe a cinza em paz, fatais Amores;\nE vós do extinto vate a campa, e lira,\nVirtudes, que exaltou, cubri de flores!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 349, «Sobre o mesmo assunto»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-magro-de-olhos-azuis-carao-moreno": {"t":["Magro, de olhos azuis, carão moreno,\nBem servido de pés, meão na altura,\nTriste de facha, o mesmo de figura,\nNariz alto no meio, e não pequeno:\n\nIncapaz de assistir n'um só terreno,\nMais propenso ao furor do que à ternura;\nBebendo em níveas mãos por taça escura\nDe zelos infernais letal veneno:\n\nDevoto incensador de mil deidades\n(Digo, de moças mil) n'um só momento,\nE somente no altar amando os frades:\n\nEis Bocage, em quem luz algum talento;\nSaíram d'ele mesmo estas verdades\nN'um dia em que se achou mais pachorrento."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 366, «Retrato próprio»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-de-ceruleo-gabao-nao-bem-cuberto": {"t":["De cerúleo gabão, não bem cuberto,\nPasseia em Santarém chuchado moço,\nMantido às vezes de sucinto almoço,\nDe ceia casual, jantar incerto:\n\nDos esburgados peitos quase aberto,\nVersos impinge por miúdo e grosso;\nE do que em frase vil chamam caroço,\nSe o quer, é vox clamantis in deserto:\n\nPede às moças ternura, e dão-lhe motes!\nQue tendo um coração como estalage,\nVão n'ele acomodando a mil peixotes:\n\nSabes, leitor, quem sofre tanto ultraje,\nCercado de um tropel de franchinotes?\nÉ o autor do soneto; — é o Bocage!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 367, «Segundo retrato»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nEstalage: forma antiga de «estalagem» (rima com ultraje, Bocage), mantida.\n\n«E o auctor» na ed. 1875 (maiúscula sem acento; «É» na ed. 1853).","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-se-eu-podera-ir-de-tralha-ir-a-surdina": {"t":["Se eu poderá ir de tralha, ir à surdina\nPor aí! Forte sede, e forte gana\nDe zurrapa, de atum, de ti, chanfana,\nDe ti, que dos pingões és golosina!\n\nQue tempo em que eu com súcia, ou grossa, ou fina,\nPara a tia Anastácia (a tal cigana)\nIa, e vinha depois co'a trabuzana\nA remos, no mar roxo, ou à bolina!\n\nQuando hás de consentir, cruel Fortuna,\nAo magro, de olho azul, de tez morena\nO bem d'andar a flaino, e d'ir à tuna?...\n\nMas ai! Maldito som, que me condena!\nDize, oh Fado, ao besouro, que não zuna...\nAí me chama algum — Alma pequena!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 371, «Feito em um intervalo da sua final moléstia»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«poderá» (v. 1) nas eds. de 1853 e 1875, pelo sentido «podéra» (= pudera); mantido.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-soneto-chalaca-minha-que-chibavas-tanto": {"t":["Chalaça minha, que chibavas tanto\nNa súcia dos tafuis! És uma feia;\nDeixas-me andar talvez por língua alheia,\nOu lá não sei por onde, e eu cá n'um canto!\n\nVem para casa, vem, que me ataranto\nSem te ver ao jantar, sem ver-te à ceia;\nDa enferma história minha urdindo a teia,\nDê-se a folguedo o que se deve ao pranto:\n\nContem-se o «Vai melhor» e o «Não é nada»;\nSecos «Bons dias» da hiperbórea mana,\nE a roda viva da vivaz criada:\n\nAmoleça-se o fel da vida humana,\nAté que a Morte, de broquel e espada,\nNos leve à cortesia até Pantana."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage, vol. I — Sonetos (1875), soneto 372, «Análogo ao antecedente»\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, Imprensa Portuguesa, 1875, vol. I, cotejada com a ed. de 1853)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/stream/obraspoticasde01bocauoft/obraspoticasde01bocauoft_djvu.txt"}]}},
"bocage-idilio-filena-ou-a-saudade": {"t":["Que terna, que saudosa cantilena\nAo som da lira Melibeu soltava,\nO pastor Melibeu, que por Filena,\nPela branca Filena em vão chorava!\nInda me fere o peito aguda pena,\nQuando recordo os ais, que o triste dava,\nO pranto que vertia, amargo, e justo\nÀ sombra, que ali faz aquele arbusto.\n\nTu, maviosa a choros, e a clamores,\nTu, Vênus (Vênus só na formosura)\nLuz de meus olhos, únicos amores\nD'esta alma, e seu prazer, sua ventura;\nQue, reclinada, amarrotando as flores,\nDescansas em meu peito a face pura,\nOuve-me os ais, e as queixas de outro amante.\nQue ao teu no ardente extremo é semelhante,\n\n«Céus! (assim começou, e eu escondido\nEntre as copadas árvores o ouvia)\nPor vós em duras mágoas convertido\nVejo enfim todo o bem, que possuía:\nÀ cândida Filena estar unido\nJulgastes que um pastor não merecia:\nA mais doce prisão de Amor partistes.\nAjuda, triste lira, os versos tristes.\n\n«Mal haja a lei dos fados inclemente!\nO seu poder, o seu rigor praguejo:\nMorte! Geral verdugo! Estás contente?\nJá saciaste o sôfrego desejo?...\nMas Filena inda é viva, inda me sente\nSuspirar nos seus braços: inda a beijo!...\nAh meus olhos, morreu: sem alma a vistes.\nAjuda, triste lira, os versos tristes.\n\n«Em ti, cara Filena, a sepultura\nTem de Amor, tem das Graças o tesouro;\nAli te arranca a morte acerba, e dura\nDa mimosa cabeça as tranças de ouro:\nEis terra, eis cinza, eis nada a formosura...\nAh! Que não pude perceber o agouro\nCom que esta perda, oh fados, me advertistes!\nAjuda, triste lira, os versos tristes.\n\n«Um dia, há tempos, Lênia, a feiticeira,\nMe disse: «Grande mal te está guardado!»\nNão m'o quis declarar, e ave agoureira\nDe noute me piou sobre o telhado:\nCuidei que perderia a sementeira,\nO rebanho, o rafeiro... ah desgraçado!\nPerdeste mais, e a tanto inda resistes!\nAjuda, triste lira, os versos tristes.\n\n«A tua meiga voz, o teu carinho\nMaior falta me faz, minha Filena,\nQue lá no bosque ao rouxinol sozinho\nDa presa amiga a doce cantilena:\nO teu branco, amoroso cordeirinho,\nMal que se viu sem ti, morreu de pena:\nBalar saudoso, oh montes, vós o ouvistes.\nAjuda, triste lira, os versos tristes.\n\n«O meu rebanho definhou de sorte,\nDepois que te perdi, que anda caindo;\nSeca estes campos o hálito da Morte\nDesde que ela sumiu teu gesto lindo:\nRogo-lhe vezes mil, que me transporte\nLá onde, como estrela, estás luzindo,\nLá onde alegre para sempre existes.\nAjuda, triste lira, os versos tristes.\n\n«A roseira também, que tu plantaste,\nTeu prazer, e prazer da Natureza,\nMurchou-se logo assim que te murchaste,\nOh flor na duração, flor na beleza!\nA pequenina rola, que apanhaste,\nNão comeu mais, finou-se de fraqueza:\nPor que blasfêmia, oh deuses, me punistes?\nAjuda, triste lira, os versos tristes.\n\n«Já pelas selvas, ao raiar da aurora,\nCaçando, as tenras aves não persigo;\nTudo me anceia, me enfastia agora,\nNem sofro os que por dó vêm ter comigo:\nFigura-me a saudade a toda a hora\nTernas delícias, que logrei contigo.\nAh! Quão depressa, gostos meus, fugistes!\nAjuda, triste lira, os versos tristes.\n\n«Como as formigas pelo chão, no estio,\nOu como as folhas pelo chão, de inverno,\nNo aflito coração, que em ais te envio,\nJazem penas cruéis, quais as do inferno:\nOra me sinto arder, outr'hora esfrio,\nDesfaz-me em ânsias um veneno interno:\nTalvez meus pés, oh víboras, feristes!\nAjuda, triste lira, os versos tristes.\n\n«Nos troncos, e nos mármores gravemos\nMemórias de Filena idolatrada,\nTão digna de suspiros, e de extremos,\nDe tantos corações tão cobiçada:\nAmor! Amor! Seu nome eternizemos...\nAi, que me falta a voz! Socorro, amada;\nConforta-me dos céus, aonde assistes!\nNão mais, oh triste lira, oh versos tristes.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 1 (pastoril)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio (oitavas rimadas ABABABCC de decassílabos, com refrão)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-cantata-medeia": {"t":["Já de Colcos a fera, ardente Maga\nHórridos versos murmurado havia;\nAo som de atroz conjuro, e negra praga\nJá tinha amortecido a luz do dia:\nJá co'a força do encanto\nOs implacáveis monstros subjugara\nNa feia habitação do eterno pranto,\nE à voz terrível, ao potente aceno\nA triforme carranca enfim curvara\nDo rei das sombras a feroz consorte.\nEmbebidas n'um férvido veneno\nAs roupas nupciais, brilhante ornato,\nEm que ia disfarçada, alegre a Morte,\nInstrumentos da raiva, e do ciúme,\nPunindo a vil traição do esposo ingrato,\nO invisível por arte, aéreo lume\nPouco a pouco ateavam\nNas lisas carnes da real donzela,\nE a preferida, a bela\nMiseranda rival desesperavam.\nDescendente do Sol, do deus fogoso,\nTu, zelosa, frenética Medeia,\nFoste colher ao carro luminoso\nTênue, fatal porção da luz febeia;\nTalhaste fulvo anel da ígnea trança,\nE d'ele urdiste aspérrima vingança.\nEstás desafrontada? Estás contente?\nNas garras da aflição Creúsa expira;\nJason sem alma a sente,\nJason, que te ofendeu, Jason delira,\nBrama de horror, de angústia desfalece,\nE mais que teu furor teu dó merece:\nEis o envolve, o consterna amargo luto,\nFoi falso, foi traidor, foi réu sem fruto.\nQue novo crime insólito, execrando,\nQue atrocidade insana\nVás contra a natureza aparelhando?\nPoupa os filhinhos, bárbara, inumana,\nPoupa os meigos filhinhos:\nEles são inocentes,\nEles inda têm jus aos teus carinhos.\nNão vês que, descontentes,\nNão vês que, enternecidos,\nA teu fado, a teu mal dão mil gemidos,\nSoluçam, tremem, choram,\nSe lamentam do pai, e a mãe deploram?\nOh céus! No coração da maga horrenda\nNatureza e vingança\nArmam fervente, pertinaz contenda:\nOra a ternura suspirando amansa\nDos zelos a raivosa tempestade,\nOra de agro despeito\nAo vigoroso impulso\nCede a benigna, maternal piedade:\nEnfim do irado peito\nFoge, voa carpindo Amor expulso.\nEis a mãe (já não mãe) qual ímpia Fúria,\nMedonha, e desgrenhada,\nTe faz, oh Natureza, atroz injúria!\nA tua doce voz em vão lhe brada,\nEm vão lhe representa, em vão lhe pinta\nCom mimoso pincel, com vária tinta\nÁureos instantes, cenas deleitosas;\nNos meninos gentis em vão lhe aponta\nDe amor suave as prendas carinhosas:\nCo'as imagens brilhantes\nSe assanha do divórcio a crua afronta,\nDobra-se a pena, a raiva se requinta.\nJá lança mão dos cândidos infantes,\nE empunhando mortífero instrumento\nCom que a Ternura espanca\nNo cerrado aposento\nEstas vozes cruéis do peito arranca:\n«Longe, afetos piedosos,\nLonge, materno amor! — Estes, que eu mato,\nSão prole de Jason, são criminosos,\nDetestável porção de um peito ingrato.\nMorra, morra com eles a memória\nDo pérfido consorte.\nJustiça, Indignação, dai-me a vitória!\nCessa de murmurar, oh Natureza,\nRecebe as tenras vítimas, oh Morte!...»\nN'isto em chamas do inferno a maga acesa,\nVibra o férreo punhal contra os mesquinhos,\nLacrimosos filhinhos:\nAo ato de os ferir lhe cai por terra,\nMas a destra fatal de novo o aferra.\nInfância, formosura, a dor, e o pranto\nNada o terrível ímpeto embaraça,\nUm após outro os míseros traspassa:\nTu, Ciúme cruel, tu podes tanto!\nNo horror da morte as vítimas arquejam,\nE, inda sentindo a filial ternura,\nA mãe, o algoz acarinhar desejam.\nEla, mais que rochedos seca, e dura,\nDenso véu lutuoso\nSobre os rotos cadáveres estende,\nE aos olhos tristes do culpado esposo\nA triste cena renovar pretende...\nEi-lo, ah! Ei-lo, convulso, arrebatado,\nDerriba a porta da lutuosa estância\nNo liso pavimento ensanguentado:\nFerro mortal brandindo\nCorre a Medeia com terrível ânsia.\nAo vê-lo, em novas fúrias se afogueia,\nRelâmpagos dos olhos sacudindo\nA torva maga, e súbito meneia\nCom rápido sussurro a tênue vara,\nQue às longas vestes do perjuro aplica:\nEle treme, ele para,\nCalado, imóvel qual estátua fica;\nPorém se perde a voz, e o movimento,\nConserva ilesos vista, e sentimento.\nLogo o fúnebre véu Medeia alçando,\nDo falsário Jason a angústia dobra,\nAponta ao espetáculo nefando,\nMostra-lhe os filhos, e a traição lhe exprobra.\nDepois, abominando os ímpios lares,\nTeatro de seus hórridos furores,\nAs soberbas abóbadas atroa\nCom mil imprecações, com mil clamores;\nE em leve salto se arremessa aos ares,\nE pelos ares voa\nDe alígeros dragões n'um carro enorme,\nDádiva de Prosérpina triforme.\nDas Górgonas, das Fúrias negro bando\nRetorce os olhos, que arremedam brasas,\nA segue, e vai correndo, e vai crestando\nCom rubro facho ardente ao vento as asas.\nUníssono alarido\nA sanhuda caterva aos céus levanta,\nE da brutal fereza\nO triunfo atrocíssimo decanta.\nO sol na escuridão fica sumido,\nNegreja horrorizada a natureza,\nMontanhas ergue o mar, vulcões a terra,\nAos sons, que o coro estígio desencerra:\nE entretanto o misérrimo consorte\nJaz entre os filhos, a lutar co'a morte.\n\n«Triunfe (os monstros clamam,\nE a Compaixão suspira)\nTriunfe, reine a Ira,\nCaia, pereça Amor.\n\n«Teus raios, oh Vingança,\nJamais, jamais se apaguem:\nSempre o altar te alaguem\nOndas de rubra cor.\n\n«Pasmai, tartáreas hidras,\nPasma, infernal tirano;\nInda o furor humano\nTranscende o teu furor.\n\n«Da atroz Medeia o nome\nEm perenal memória\nSerá do averno a glória,\nE dos mortais o horror.\n\n«Tropel de acerbos males\nO mundo assalte, e fira;\nReine, triunfe a Ira,\nCaia, pereça Amor."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, I (publicada nas Rimas, tomo II, 1799)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cantata (recitativo em decassílabos e hexassílabos rimados livremente; ária final em quadras de hexassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-cantata-a-morte-de-ines-de-castro": {"t":["::epigrafe As filhas do Mondego a morte escura / Longo tempo, chorando, memoraram. (Camões, Lusiad.)\n\nLonge do caro esposo Inês formosa\nNa margem do Mondego\nAs amorosas faces aljofrava\nDe mavioso pranto.\nOs melindrosos, cândidos penhores\nDo tálamo furtivo,\nOs filhinhos gentis, imagens d'ela,\nNo regaço da mãe serenos gozam\nO sono da inocência.\nCoro sutil de alígeros Favônios\nQue os ares embrandece,\nOra enlevado afaga\nCom as plumas azuis o par mimoso,\nOra solto, inquieto\nEm leda travessura, em doce brinco,\nPela amante saudosa,\nPelos tenros meninos se reparte,\nE com tênue murmúrio vai prender-se\nDas áureas tranças nos anéis brilhantes.\nPrimavera louçã, quadra macia\nDa ternura, e das flores,\nQue à bela Natureza o seio esmaltas,\nQue no prazer de Amor ao mundo apuras\nPrazer da existência,\nTu de Inês lacrimosa\nAs mágoas não distrais com teus encantos.\nDebalde o rouxinol, cantor de amores,\nNos versos naturais os sons varia;\nO límpido Mondego em vão serpeia\nCo'um benigno sussurro, entre boninas\nDe lustroso matiz, alvo perfume;\nEm vão se doura o sol de luz mais viva,\nOs céus de mais pureza em vão se adornam\nPor divertir-te, oh Castro!\nObjetos de alegria Amor enjoam\nSe Amor é desgraçado.\nA meiga voz dos Zéfiros, do rio,\nNão te convida o sono:\nSó de já fatigada\nNa luta de amargosos pensamentos\nCerras, mísera, os olhos;\nMas não há para ti, para os amantes\nSono plácido, e mudo:\nNão dorme a fantasia, Amor não dorme:\nOu gratas ilusões, ou negros sonhos\nAssomando na ideia espertam, rompem\nO silêncio da morte.\nAh! Que fausta visão de Inês se apossa!\nQue cena, que espetáculo assombroso\nA paixão lhe afigura aos olhos d'alma!\nEm marmóreo salão de altas colunas,\nA sólio majestoso, e rutilante\nJunto ao régio amador se crê subida:\nGraças de neve a púrpura lhe envolve,\nPende augusto dossel do teto d'ouro;\nRico diadema de radioso esmalte\nLhe cobre as tranças, mais formosas que ele;\nNos luzentes degraus do trono excelso\nPomposos cortesãos o orgulho acurvam;\nA lisonja sagaz lhe adoça os lábios,\nO monstro da política se aterra,\nE se Inês perseguia, Inês adora.\nEla escuta os extremos,\nOs vivas populares; vê o amante\nNos olhos estudar-lhe as leis que dita;\nO prazer a transporta, amor a encanta:\nPrêmios, dádivas mil ao justo, ao sábio\nMagnânima confere,\nRainha esquece o que sofreu vassala:\nDe sublimes ações orna a grandeza,\nFelicita os mortais, do cetro é digna,\nImpera em corações... Mas, céus!... Que estrondo\nO sonho encantador lhe desvanece!\nInês sobressaltada\nDesperta, e de repente aos olhos turvos\nDa vistosa ilusão lhe foge o quadro.\nMinistros do Furor, três vis algozes,\nDe buídos punhais a destra armada,\nContra a bela infeliz bramindo avançam,\nEla grita, ela treme, ela descora,\nOs frutos da ternura ao seio aperta,\nInvocando a piedade, os céus, o amante;\nMas de mármore aos ais, de bronze ao pranto,\nÀ suave atração da formosura,\nVós, brutos assassinos,\nNo peito lhe enterrais os ímpios ferros.\nCai nas sombras da morte\nA vítima d'Amor lavada em sangue:\nAs rosas, os jasmins da face amena\nPara sempre desbotam;\nDos olhos se lhe some o doce lume,\nE no fatal momento\nBalbucia, arquejando: — «Esposo! Esposo!...»\nOs tristes inocentes\nÀ triste mãe se abraçam,\nE soltam de agonia inútil choro.\nAo suspiro exalado,\nFinal suspiro da formosa extinta,\nOs Amores acodem.\nMostra a prole de Inês, e tua, oh Vênus,\nIgual consternação, e igual beleza:\nUns dos outros os cândidos meninos\nSó nas asas diferem,\n(Que jazem pelo campo em mil pedaços\nCarcases de marfim, virotes d'ouro)\nSúbito voam dous do coro alado;\nEste, raivoso, a demandar vingança\nNo tribunal de Jove,\nAquele a conduzir o infausto anúncio\nAo descuidado amante.\nNas cem tubas da Fama o gran desastre\nIrá pelo universo:\nHão de chorar-te, Inês, na Hircânia os tigres,\nNo torrado sertão da Líbia fera\nAs serpes, os leões hão de chorar-te.\nDo Mondego, que atônito recua,\nDo sentido Mondego as alvas filhas\nEm tropel doloroso\nDas urnas de cristal eis vêm surgindo;\nEis, atentas no horror do caso infando,\nTerríveis maldições dos lábios vibram\nAos monstros infernais, que vão fugindo.\nJá c'roam de cipreste a malfadada,\nE, arrepelando as nítidas madeixas,\nLhe urdem saudosas, lúgubres endeixas.\nTu, Eco, as decoraste;\nE cortadas dos ais, assim ressoam\nNos côncavos penedos, que magoam:\n\n«Toldam-se os ares,\nMurcham-se as flores;\nMorrei, Amores,\nQue Inês morreu.\n\n«Mísero esposo,\nDesata o pranto,\nQue o teu encanto\nJá não é teu.\n\n«Sua alma pura\nNos céus se encerra;\nTriste da terra,\nPorque a perdeu.\n\n«Contra a cruenta\nRaiva ferina\nFace divina\nNão lhe valeu.\n\n«Tem roto o seio,\nTesouro oculto,\nBárbaro insulto\nSe lhe atreveu.\n\n«De dor e espanto\nNo carro de ouro\nO númen louro\nDesfaleceu.\n\n«Aves sinistras\nAqui piaram,\nLobos uivaram,\nO chão tremeu.\n\n«Toldam-se os ares,\nMurcham-se as flores;\nMorrei, Amores,\nQue Inês morreu.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, II (publicada nas Rimas, tomo II, 1799)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cantata (recitativo em decassílabos e hexassílabos soltos; ária final em quadras de tetrassílabos rimados)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-outros-soneto-a-ulina": {"t":["Da miseranda Inês o caso triste,\nNos tristes sons, que a mágoa desafina,\nEnvia o terno Elmano à terna Ulina,\nEm cujos olhos seu prazer consiste:\n\nPaixão, que, se a sentir, não lhe resiste\nNem nos brutos sertões alma ferina,\nBeleza funestou quase divina,\nDe que a memória em lágrimas existe:\n\nLê, suspira, meu bem, vendo um composto\nDe raras perfeições aniquilado\nPor mãos do crime, à natureza oposto:\n\nTu és cópia de Inês, encanto amado;\nTu tens seu coração, tu tens seu rosto...\nAh! Defendam-te os céus de ter seu fado!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, II (dedicatória da cantata À morte de Inês de Castro)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-crinaura-ou-o-amor-magico": {"t":["Já, da noute ametade anunciando,\nO galo velador tinha cantado;\nRegougavam nas serras as raposas,\nCarpiam pelas árvores os mochos,\nE no sórdido lago as rãs coaxavam.\nPor entre densas, pluviosas nuvens,\nPrenhes de raios, transluzia apenas\nSemimorto clarão da frouxa lua.\nEntregue ao sono o racional jazia\nOu nos braços de amor, ou solitário,\nSobre cama de feno, ou leito de ouro,\nSegundo teus caprichos, oh Fortuna,\nCom que dás tudo a uns, a outros nada.\nSó n'um bosque de víboras coalhado,\nFértil de sombras, sombras dos infernos,\nN'um ermo, onde não há pegada humana,\nQue dos magos notívagos não seja,\nVelava um d'eles, o amoroso Elmano,\nPerto de turvo, e rápido ribeiro,\nQue do atro seio de horrorosa gruta\nCom ríspido sussurro ia correndo.\nFantasmas infernais, que a negra noute\nArroja à terra, sacudindo o manto,\nVagavam por ali: Górgonas, Fúrias,\nQue o pavoroso báratro vomita,\nQue exalam peste das cruéis entranhas,\nAs serpes, as melenas assanhavam\nEm torno do infeliz, queixoso amante,\nInfluindo-lhe a raiva, a dor, e a morte.\nNo centro da terrível assembleia\nCom carrancudo aspecto o malfadado\nSó tinha em ti, Crinaura, os pensamentos!\nTu lhe negavas o fulgor suave\nCom que teu rosto os céus abrilhantaram;\nLonge estavas, cruel; porém supriam\nAos olhos corporais os olhos d'alma;\nLonge estavas, cruel; porém pasmado\nNa fantástica imagem de teu gesto,\nQue vivamente Amor lhe debuxava,\nD'esta maneira os ares atroava:\n\n«Potentes versos meus, arte divina,\nAs tartáreas cavernas invadistes,\nComovestes Sumano, e Prosérpina,\nHidras, Cerastes, Fúrias atraístes:\nDa fresca lua a face cristalina\nCom tenebrosas nuvens denegristes,\nDomais as feras n'esta horrível mata:\nSó não podeis vencer Crinaura ingrata.\n\n«Versos! Versos! Oh dádiva celeste!\nApinhando os delfins ao som da lira,\nO músico Arion remir pudeste\nDas cobiçosas mãos, em que caíra:\nDesarraigaste as árvores, soubeste\nAs penhas derreter! Amor te inspira,\nAmor a força tua em mim dilata,\nE não hás de vencer Crinaura ingrata!\n\n«Versos! Versos! Nas ermas sepulturas\nCom graça, pelas graças influída,\nFurtando as almas das prisões escuras,\nTornais às cinzas o calor, e a vida:\nA Dite, revogando-lhe as leis duras,\nTirais a ninfa, do áspide mordida:\nTanto podes, oh arte aos deuses grata!\nSó não triunfarás d'aquela ingrata!\n\n«Ah! Sim, tentemos outra vez a sorte;\nA ternura porfie, a paixão teime;\nDeixai-me, oh desenganos, longe, oh Morte:\nDeus Febo, teu fervor minha alma queime!\nEia, Vênus, e Amor, dai-me um transporte\nDigno de vós: oh filho! Oh mãe! Valei-me,\nNão só, não só por mim, de vós se trata:\nVós venceis, se eu vencer Crinaura ingrata.\n\n«Solte-se a veia, principie o encanto;\nVersos! Versos! Crinaura! Eu t'os envio.\nEis nas plumas do Zéfiro o meu canto,\nEis Íris sobre o ar úmido, e frio:\nCessa o berro da rã, do mocho o pranto,\nFicam mudas as Fúrias, mudo o rio:\nLá mostra a lua a face prateada,\nTrazei-me, versos meus, a minha amada.\n\n«Esta semente, de fragrância bela,\nAos raios venerável como o louro,\nPlanto aqui: flores mil brotarão d'ela\nSúbito... ah! Ei-las, é feliz o agouro:\nAcendamos três vezes esta vela,\nCrestemos à terceira este besouro:\nMinha mestra m'a deu, Canídia, a fada.\nTrazei-me, versos meus, a minha amada.\n\n«As amoras silvestres espremamos\nN'este vaso de Alceu, mágico experto;\nSobre o licor sanguíneo desfaçamos\nFolha a folha este cravo meio-aberto:\nMisturemos-lhe agora o mel, e os ramos,\nQue torrei, que mói, remédio certo\nContra o negro lacrão: não falte nada;\nTrazei-me, versos meus, a minha amada.\n\n«Pondo este roto véu, que era de Circe,\nDepois batendo o pé, Lâmia podia\nConverter-se em morcego, e restituir-se\nÀ forma natural, quando queria;\nEis o buço de lobo: a sabia Tirse\nCom ele assombros mil também fazia:\nJá com isto em serpente a vi mudada.\nTrazei-me, versos meus, a minha amada.\n\n«Pus a secar debaixo de um penedo\nCrescida, e gorda rã, que apanhei viva;\nDous ossos lhe guardei: pondo-lhe o dedo\nQualquer amante, seu amor se aviva;\nTem a virtude, enfim, tem o segredo\nDe amansar lobos: a caduca Oliva\nCom eles das mãos d'um foi já tirada.\nTrazei-me versos meus, a minha amada.\n\n«A torta vara, com que Ileu fazia\nMilhões de espectros negrejar nos ares,\nCom que ao mínimo aceno embravecia\nPlácidas auras, bonançosos mares:\nParte do incenso, que Medeia ímpia\nDava da horrível Hécate aos altares,\nGuardo n'aquela gruta, ao sol vedada.\nTrazei-me, versos meus, a minha amada.\n\n«Falta a cinza (ei-la aqui) do corvo branco,\nQue Lícidas caçou, que tanto estimo:\nDos feridos com ela o sangue estanco,\nE os quase mortos, em querendo, ânimo:\nEis a admirável planta, com que arranco\nAs mais cravadas setas, eis o limo,\nE esta concha, no Eufrates apanhada.\nTrazei-me, versos meus, a minha amada.\n\n«Produzi, meus encantos, vosso efeito\nPara glória de Amor, e glória minha;\nVenha curar o mal, que me tem feito,\nAquela, em cujos olhos me mantinha:\nTrazei-a... ah! Que prazer me inunda o peito,\nQue luz, que objeto para mim caminha!\nQue força oculta as forças me restaura!\nBasta, meus versos: ali vem Crinaura.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 2 (farmaceutria)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio (introdução em decassílabos soltos; canto em oitavas rimadas ABABABCC com refrão)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-cantata-leandro-e-hero": {"t":["De horrenda cerração c'roada a Noute\nSurgira há muito da ciméria gruta;\nTapando o longo céu co'as asas longas\nReina em meio universo:\nOcupam-lhe os degraus do negro trono\nA Tristeza, o Silêncio,\nO Medo, a Solidão, o Amor, e o Crime;\nVoam-lhe em roda lúgubres fantasmas,\nAves sinistras pousam-lhe no grêmio.\nEis manso e manso as nuvens se entumecem,\nEis o líquido peso\nRompe os enormes, carregados bojos,\nEm torrentes sussurra, e cai na terra.\nRebentam furacões, flamejam raios,\nO estrondoso trovão no céu rebrama,\nO Helesponto nas rochas ferve, e ronca.\nTu, Abideno amante,\nTu velas n'este horror com a saudade,\nJá corres insofrido às ermas praias,\nD'onde é teu uso arremessar-te ao pego,\nE, destro nadador, talhando as vagas,\nTeus gostos demandar na oposta margem.\nAo longe em celsa torre, estância cara\nD'Hero, sol dos teus dias,\nO brilhante sinal, o amigo lume\n(Que é no facho d'Amor por ela aceso)\nVês entre as sombras cintilar a espaços,\nE como que te acena, e te suspira.\nDebalde o mar bramindo, o céu troando\nTeu ímpeto ameaçam:\nArdem-te n'alma os sôfregos desejos;\nFulgurante ilusão, dourando as trevas,\nN'um quadro tentador te of'rece aos olhos\nGlórias a furto, vívidos prazeres,\nDoces mistérios, que da luz se temem.\nA sagaz Esperança\nTe reforça, te incita,\nJura aplacar-te o ar, pôr freio às ondas,\nDar-te aos suspiros da suave amada.\nAtento à meiga voz, que atrai, que mente,\nNo montuoso pélago te arrojas:\nÀ queda repentina alteia um grito\nO corvo grasnador na destra parte,\nE os Ecos despertando ao som medonho,\nGemem nas brutas, cavernosas fragas.\nO triste agouro te arrepia as carnes,\nTeus cabelos eriça;\nMas prevalece Amor, e, expulso o medo,\nForças a equórea, túmida braveza.\nMetade já do trânsito afanoso\nIndústria e robustez vencido haviam:\nN'isto a procela horríssona recresce,\nTingem sombras do inferno os véus da noute,\nQue o súbito relâmpago retalha:\nBraveja o mar, aos astros se remontam\nSerras, e serras de fervente espuma;\nCarrancudos tufões arrebatados\nDobrando a força, a raiva, lutam, berram,\nE revolvem do pélago as entranhas:\nRochedo imóvel, aferrado à terra,\nRebate apenas o horroroso assalto...\nAh Leandro infeliz! Tu já fraqueias,\nA destreza, o vigor, nas mãos, nas plantas\nJá, mísero amador, já te falecem.\nProcuras o distante, o caro lume,\nAstro benigno, que te influi, e guia,\nOlhas, vês que te falta,\nQue desapareceu, que jaz extinto:\nSuspiras, esmoreces,\nDa tua doce luz desamparado.\nInvocas o gran deus, que rege os mares;\nDe teus rogos não cura imoto, e surdo.\nInvocas de Nereu potente as filhas;\nElas ardem por ti; mas, invejosas\nDo objeto encantador, que lhes preferes,\nÀs marítimas fúrias te abandonam.\nHero invocas, e Amor, e os Céus, e a Sorte:\nA Sorte é implacável,\nDos males, que dispõe, não se arrepende,\nTeus dias sinalou de um termo infausto.\nDebalde te auxilia o deus mimoso,\nO alado criador de teus suspiros,\nDos amorosos bens, que desfrutastes;\nO facho luminoso em vão meneia\nPara encurtar-te as sombras,\nE mais fácil tornar a undosa estrada;\nEm vão co'as asas brandas\nTenta arrasar os orgulhosos mares.\nSobre altos escarcéus o Fado escuro\nFolga, triunfa, e reina.\nPunge, ameaça, desespera os ventos,\nEnrola a morte nas horrendas vagas.\nEla, pronta a seu mando, ela acomete\nO deplorável moço:\nEis dos olhos gentis lhe turva o lume,\nO tardo movimento eis lhe sopeia,\nPelas águas o embebe, e d'Hero o nome\nDo ansioso coração n'um ai lhe arranca.\nAbaixo, acima, co'as cavadas ondas\nVai, vem mil vezes o infeliz mancebo...\nAi! Já sem vida aqui, e ali vagueia\nÀ discrição do mar, e o mar com ele\nDe Sesto às praias súbito arremete:\nDá contra a torre d'Hero, ali rebenta,\nE deixa o triste corpo à margem nua.\nTu entretanto, carinhosa amante,\nQue fazias (Oh céus!) que imaginavas?\nSolitária, anelando,\nNas trevas espantosas,\nNos soltos ventos, alterosos mares,\nLias de feio azar presságios feios.\nEm torno à viva luz, que vigiavas,\n(Que em raro véu com arte envolto havias,\nResguardando-a dos ares indignados)\nEm torno à viva luz eis de improviso\nNegro inseto voou, zuniu três vezes,\nE à terceira apagou a experta chama:\n(Foi no ponto funesto em que o mancebo\nCom teu nome adoçou o extremo arranco!)\nDo repentino assombro espavorida,\nAtônita, convulsa\nO agourado clarão não renovaste.\nEm ânsias implorando os deuses todos,\nE mais que todos o que em ti reinava,\nA bem do afouto, desvelado amante,\nAo númen indulgente, à mãe piedosa\nMil incensos, mil vítimas votaste.\nDepois, cevando a revoltosa ideia\nEm terríveis imagens,\nOra do moço audaz o usado arrojo\nReprovavas contigo,\nOra a cega imprudência maldizias\nCom que em tão desabrida, horrível noute\nA perigosa senha aventuraras...\nAh triste! Contra ti não te conjures;\nFoi lei dos fados a imprudência tua.\nHero desanimada\nMetida em profundíssimo letargo,\nJaz sem tino, e sem voz, até que aponta\nA purpúrea manhã no céu já ledo.\nFarto o cruel Destino,\nAdelgaçara os ares,\nAo pego a mansidão restituíra\nDepois que a terna vítima saudosa\nFoi sufocada nas voragens feras.\nEle, o duro opressor dos desditosos,\nEle do almo prazer, que os dous gozaram,\nEstá vingado em parte, e da vingança\nÀ Desesperação comete o resto.\nHero, ah Hero infeliz! Tu pelas águas\nÚmida vista suspirando alongas.\nNão vês o nadador por quem desmaias,\nO teu bem não flutua\nPelas ondas desertas:\nEis a consternação te inclina os olhos\nÀ pedregosa areia\nOnde o desventurado está sem alma.\nQue vista!... Que terror!... As alvas carnes\nRotas nas rochas pelo embate undoso,\nInda gotejam sangue; aberta a boca\nParece que inda quer, que inda procura\nChamar-te, oh Hero, murmurar teu nome!\nNo espetáculo horrendo\nMísera, tu reparas;\nTu... (Céus, não lhe acudis?...) tu reconheces\nO querido semblante, o corpo amado,\nEntre as sombras da morte inda formoso:\nCom palidez, que a pinta,\nGritas, arquejas, desesperas, fremes,\nDeitas as mãos de neve às tranças d'ouro,\nE as tranças d'ouro, delirando, arrancas.\nLevada enfim de um ímpeto raivoso\nTe arremessas da torre, e dás, e entregas\nO teu ai derradeiro ao mudo amante.\nLá jazem sobre a areia lutuosa\nAs vítimas do Fado:\nNas angústias mortais a linda moça\nInda, estendendo os amorosos braços,\nTenta apertar o suspirado objeto.\nApiedados delfins nas ondas surgem,\nE altos sons (oh prodígio!) derramando,\nLamentam junto à praia o duro caso:\nAs mesmas ninfas invejosas d'Hero\nSoluçam de pesar nos vítreos lares.\nUm marmóreo padrão se erige em breve;\nCompadecidas mãos a história triste\nGravam na lisa pedra; a pedra existe:\nMas o monstro voraz, que rói penedos,\nComendo em parte a fúnebre escritura,\nSó deixa soletrar-lhe\nO remate piedoso,\nEm meus piedosos versos trasladado,\nCarpido ao som da lira:\nInda agora de ouvi-lo Amor suspira.\n\nAos dous amantes\nD'abido e Sesto\nArdor funesto\nDeu negro fim.\n\nForam-lhe algozes\nOs seus extremos;\nMortais, amemos,\nMas não assim."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, III (publicada nas Rimas, tomo II, 1799)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cantata (recitativo em decassílabos e hexassílabos soltos; ária final em quadras de tetrassílabos rimados)\n\n**Notas sobre o texto.**\n\n\"Mas prevalece Amor, e, expulso o medo\": a ed. de 1875 imprime \"é\"; segue-se a de 1853.\n\n\"Reprovavas comtigo\" segue a ed. de 1853 (Poesias, ed. Inocêncio, tomo II); a de 1875 imprime \"Reprovas\", que deixa o verso com cinco sílabas.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-armia": {"t":["::fala JOSINO\nSalve, meu caro Elmano, enfim voltaste\nD'Scalabis aos campos, onde outr'ora\nCantando os versos teus nos encantaste.\n\nPorém que avesso te diviso agora\nDo que estavas então! Fere-te o peito\nInterna mágoa, que se vê por fora.\n\nPastor, às musas, e à ternura afeito,\nQue mal te aconteceu? Talvez padeces\nO de amor, a que tudo está sujeito?\n\nElmano, o antigo Elmano (ah!) não pareces;\nConta-me, por quem és, o teu desgosto;\nQuanto o devo sentir já tu conheces.\n\n::fala ELMANO\nBanhai-me sempre, lágrimas, o rosto,\nTé que este corpo mísero, e cansado\nTenha na fria sepultura encosto.\n\nChoremos, coração desenganado,\nChorai, ninfas gentis, gentis Amores,\nCom lágrimas de sangue o nosso estado.\n\nOh céus! Oh rio! Oh árvores! Oh flores!\nEis o mais consumido, o mais saudoso\nEntre a turba infeliz dos amadores.\n\n::fala JOSINO\nRefreia o terno pranto copioso,\nE co'um peito fiel reparte, amigo,\nDanos, que te granjeia o fado iroso.\n\nSe és qual foste, qual fui, qual sou contigo,\nDize-me a tua mágoa, o teu segredo,\nQue no meu coração terá jazigo.\n\nComo que nos acena este arvoredo,\nMovendo-se tão manso que parece\nEstão soprando os Zéfiros a medo.\n\nSentemo-nos: contado o mal decresce;\nA queixa é natural; e a filomela\nNo raminho cantando a pena esquece.\n\nImita, meu pastor, o exemplo d'ela;\nDo peito amargurado a voz desata:\nQue pastora te aflige, ingrata, e bela?\n\n::fala ELMANO\nPastora bela sim, mas não ingrata,\nDá motivo a meu pranto, a meu tormento;\nNão mata de rigores, de amores mata.\n\nNo momento em que a vi (fatal momento!)\nPara seus olhos meigos me voaram\nA vontade, o prazer, e o pensamento.\n\nEles a noute carrancuda aclaram,\nN'eles as Graças vivem, n'eles moram\nOs que ardentes farpões em mim disparam.\n\nD'eles o céu, e a terra se namoram,\nSerenos como as águas em remanso,\nLindos no gosto, e lindos quando choram.\n\nDei por eles meu siso, e meu descanso,\nCustam-me esta saudade, esta agonia,\nE os ais, que sem proveito aos ares lanço.\n\n::fala JOSINO\nTorno a dizer: — se extremos de algum dia\nInda te não passaram da memória,\nClaramente de mim teus males fia.\n\nD'este queixoso amor a inteira história,\nDando-te a dor lugar, saber quisera:\nCrê que a ninguém por mim será notória.\n\n::fala ELMANO\nSe da amizade a força me não dera\nCausa, oh Josino, a declarar qual ando,\nTambém meu mal por mim ninguém soubera.\n\nLá onde o Tejo teu, que vai manando\nTão claro para o mar, se dana, e torna\nEm salgado e feroz, de doce e brando;\n\nVasta planície de árvores se adorna,\nJunto de um fresco vale, onde sereno\nMurmurante cristal no chão se entorna:\n\nDos Arroios se chama o vale ameno;\nAlém d'ele o casal tem n'um recosto\nArmia, por quem ardo, e por quem peno.\n\nEla, e Felisa, em voz, em modo, em rosto,\nEm tudo, sendo irmãs, diferem tanto\nComo em calor difere Abril de Agosto.\n\nA fama, que por lá ganhei no canto,\nOs meus laços teceu, guiou-me um dia\nÀ minha desventura, ao meu encanto.\n\nDe ouvir-me curiosa a mãe de Armia\nRoga a dous sócios meus, Montano, e Fido,\nMe levem ao casal onde vivia.\n\nSegui-os, fui, olhei, fiquei perdido\nD'amores e desejos por aquela,\nQue nunca fugirá do meu sentido.\n\nDescansei mansamente os olhos n'ela;\nMudo lhe expus meu mal, e a vi, e achei-a\nFagueira, maviosa, além de bela.\n\nJá leda nos meus versos se recreia,\nMinha lira lhe apraz, e em meus louvores\nNão sofre se antecipe a língua alheia.\n\nCalados, mas dulcíssimos favores\nDesfruto do meu bem, e ambos sentimos\nOs brandos corações arder de amores.\n\nLigados desde a hora em que nos vimos,\nFomos passando o tempo em doce estado,\nEm furtiva ternura, e cautos mimos.\n\nDa mãe, e irmãos d'Armia era prezado,\n(Irmãos, porque esquecia o moço Anselo,\nQue sempre então me desejava ao lado!)\n\nPorém tu, da inocência atroz flagelo,\nTu, oh calúnia vil, n'um fero instante\nNos foste malograr tanto desvelo.\n\nDitosos n'este amor igual, constante,\n(Turbado às vezes só pelo ciúme,\nNecessária pensão do peito amante)\n\nDávamos ternos ais, e algum queixume,\nSem recear mudanças da ventura,\nVária por gênio, vária por costume.\n\nEis se arma em nosso dano, eis se conjura\nContra a nossa alegria um maldizente,\nTão mordaz como as feras da espessura.\n\nPéssima produção de má semente,\nÍnfimo pegureiro, o vil Domício,\nQue d'ali longo tempo andara ausente,\n\nEra por compaixão, por benefício\nAceito, recebido, agasalhado\nNos lares onde Amor me foi propício.\n\nEm baixas cantilenas mal versado\nÀs vezes, mas debalde, usar queria\nDas Musas imortais o dom sagrado.\n\nEste, pois, com sagaz aleivosia\n(Sem que jamais de mim provasse ofensa)\nUm sedutor me finge à mãe d'Armia.\n\nEla acredita o monstro; em raiva intensa\nArde contra a paixão, que em nós conhece,\nOlha-nos já com ríspida presença.\n\nClaro de dia em dia o tédio cresce,\nConverte-se em rigor o afago d'antes,\nTudo nos desampara, e nos empece.\n\nNós desvalidos, míseros amantes,\nCom disfarces em vão cegar queremos\nA cuidadosa mãe, e os circunstantes.\n\nTodos a nosso amor contrários vemos:\nComigo desleais Montano, e Fido\nCondenam quais delitos meus extremos.\n\nPara tormentos mil eu fui nascido;\nQuis sofrer o pior, sacrificar-me\nÀquela, que me tinha ali rendido.\n\nA furto não deixava de animar-me,\nDizendo-me: «Tolera a mãe raivosa,\nAté que o tempo as fúrias lhe desarme.»\n\nMas vendo, a seu pesar, minha alma ansiosa\nQue de alguns dons, que devo à Natureza,\nO desconto me faz Fortuna irosa;\n\nOusado me arrojei a estranha empresa;\nFugi subitamente ao caro objeto,\nPara evitar-lhe a maternal dureza.\n\nNo peito a dor, e a palidez no aspecto,\nMorrer longe de Armia amante, e bela,\nEra ao princípio meu feroz projeto:\n\nMas o fervente amor, que me desvela,\nMe disse ao coração que não perdesse\nA glória, o bem de padecer por ela.\n\nÀ morte eu antepus este interesse:\n(Se alguém a si prefere a sua amada,\nO fiel, o estremado amante é esse!)\n\nEm fugir ao meu bem vi requintada\nEsta acesa paixão, que me transporta,\nPaixão, que é tão leal quão desgraçada!\n\nE dado todo à mágoa, que me corta\nO triste coração, sem tino a mente,\nCom alma esmorecida, ou quase morta;\n\nDeixo aqueles contornos de repente,\nDesertos, solidões achar desejo,\nOnde as aves da noute andem somente.\n\nMil vezes canso, vezes mil forcejo\nPor caminhar no mato, onde me entranho,\nE enfim (sem saber como) aqui me vejo.\n\n::fala JOSINO\nCom lágrimas as tuas acompanho;\nMas a quem, meu pastor, conhece o mundo\nNenhum mal como o teu se faz estranho.\n\nA sólida exp'riência em que me fundo\nBravezas das paixões em mim quebranta,\nSalvando-me de um pego tão profundo.\n\nAmor nos multiplica, e nos encanta,\nDocemente ligado à natureza,\nOs homens, os mortais ao céu levanta:\n\nMas se influi o prazer n'uma alma acesa,\nÀs vezes todavia em nós se aferra,\nQual monstro de ímpia garra, aguda presa.\n\nO velho Auliso não treslê, não erra\nEm dizer, e afirmar que amor é fogo,\nFogo devorador de toda a terra.\n\nMas cumpre haver, Elmano, um desafogo,\nUm corte nas paixões. Valor, constância,\nNão chores, cai em ti, cede a meu rogo.\n\nOs males diminui a tolerância;\nDe amor o ativo incêndio se modera\nC'os auxílios do tempo, e da distância.\n\nAtento n'este prado a dor tempera;\nVê como brilha na planície amena\nA vistosa estação da primavera.\n\nOlha a corrente como vai serena,\nOuve quão branda pelos ares soa\nDas aves a amorosa cantilena.\n\n::fala ELMANO\nPrimeiro que este mal, que me magoa,\nCesse de me afligir, serão gostosos\nOs ecos do trovão, que o mundo atroa:\n\nSerão sem graça os pássaros mimosos,\nAs estrelas sem luz, sem pranto a aurora,\nBravos os cabritinhos buliçosos.\n\n::fala JOSINO\nNão te quero oprimir, pranteia embora;\nMas em penhor de afeto, ao puro amigo\nAo menos um prazer concede agora.\n\nAcompanha meus passos, vem comigo,\nQue já são horas de acolher-se o gado.\n\n::fala ELMANO\nSim, Josino fiel, eu vou contigo;\nMas sofre lamentar-se um desgraçado."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 7 (pastoril)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio dialogado (tercetos encadeados de decassílabos)\n\n**Notas sobre o texto.**\n\nInterlocutores Elmano e Josino.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-ulina": {"t":["De Pedrouços na praia extensa e fria,\nQuando, extinguindo os astros, apontava\nNo corado horizonte a luz do dia:\n\nSozinho um pescador se lamentava,\nEnquanto na tenaz fateixa preso\nSeu batel sobre as ondas flutuava:\n\nD'amores o infeliz perdido, aceso,\nDerretia-se em lágrimas queixosas,\nProvando amarga dor, cruel desprezo.\n\nUlina, irmã das tágides formosas,\nE inveja das irmãs, a bela Ulina,\nLhe motivava as ânsias lastimosas.\n\nEm seus olhos gentis, com que domina\nRendidos corações Amor tirano,\nEm sua linda face, e voz divina,\n\nPerdera a liberdade o terno Elmano\n(Assim se nomeava o triste amante,\nQue ainda não cedia ao desengano).\n\n«Oh tu (clamava o cego, o delirante)\nFilha das ondas, como as ondas pura,\nE também como as ondas inconstante!\n\nQue mal te fiz, que mal? Porque tão dura\nNegas doce atenção, doce piedade\nAos ais de amor, aos prantos da ternura?\n\nSe és prole de Nereu, se és divindade,\nDe feia ingratidão como te infamas,\nVício, que enche de horror a humanidade?\n\nQue prêmio dás ao coração, que inflamas?\nTeu prazer, teus amores me chamaste,\nTeu ódio, teu desgosto hoje me chamas.\n\nRisos e afagos em desdéns trocaste,\nRisos e afagos mil, com que os sentidos,\nCom que os livres sentidos me enlaçaste.\n\nMeu canto foi suave a teus ouvidos,\nHoje aos ouvidos teus somente é grato\nO rouco, inútil som dos meus gemidos.\n\nAs lágrimas de amor, que em vão desato,\nAmarguras, que em míseros clamores\nÀ terra, ao vento, ao mar, e ao céu relato,\n\nDobram-te as iras, cevam-te os rigores;\nE debalde a teu lado estão carpindo,\nChamando-te à piedade os meus amores:\n\nDe meus ais, de meu mal tu, ímpia, rindo,\nTens por timbre, por glória a tirania,\nManchas co'um gênio fero um rosto lindo.\n\nNoute, mais clara para mim que o dia,\nMinha prisão forjou, quando eu folgava\nNo regaço da paz, e da alegria.\n\nFerindo a lira, ao ar meus versos dava\nN'esta lustrosa praia; a branda lua\nLá no cume dos céus então brilhava.\n\nEis sobre as águas límpidas flutua\nDas ninfas o tropel, e Amor me of'rece\nO sereno esplendor da face tua;\n\nConfusamente aos olhos me aparece\nEntre as mais; e um sagaz presentimento\nDe todas por melhor te reconhece.\n\nLevaste-me na voz o pensamento;\nSendo, oh ninfa, o momento de escutar-te\nDa minha perdição fatal momento.\n\nVieste sobre a margem reclinar-te,\nJurando que meus sons encantadores\nPuderam d'entre as ondas arrancar-te.\n\nAbsorto me deixaram teus louvores,\nE o ver das belas ninfas a mais bela\nMover-se à rude voz dos pescadores.\n\nQue noute para mim, que noute aquela!\nTempo, que tudo estragas, e devoras,\nAh! Não me roubes as memórias d'ela.\n\nHoras do meu prazer, benignas horas,\nAo menos consolai na ideia um triste,\nTende sequer fantásticas demoras.\n\nOh céus! Com quanto júbilo me ouviste,\nMinha adorada Ulina, e quão mimosa\nQue volvesse a teus olhos me pediste!\n\nQue vezes n'esta praia deleitosa\n(Que ufana de gozar teu meigo rosto\nMais fresca se tornava, e mais formosa)\n\nPintaste em brando olhar o amor, e o gosto!\nVieste, encanto meu, lograr comigo\nAs amenas manhãs do claro Agosto!\n\nVenturas, que idolatro, e que não digo,\nAltas venturas, em que trago a mente,\nO carinhoso Amor me deu contigo.\n\nAh! Que nunca o prazer foi permanente;\nArremeda o relâmpago a alegria,\nÉ tão fugaz como ele, e tão luzente.\n\nQuando serenas glórias possuía,\nE erguido ao céu d'Amor meu pensamento\nDo térreo mundo vil já nada via,\n\nAgros zelos traçaram n'um momento\nA minha desventura, e quis a Sorte\nFartar-se nos meus ais, no meu tormento.\n\nQual súbita rajada aguda, e forte,\nQue ao ledo, ao descuidado navegante\nEsperança e baixel destrói co'a morte;\n\nTal para meu amor foi outro amante,\nQue por ti, ninfa ingrata, olhado apenas,\nViu terno acolhimento em teu semblante.\n\nDesde então me aborreces, me condenas,\nDo desdém, do ciúme, e da saudade\nÀs negras aflições, às duras penas.\n\nHorrenda, carrancuda tempestade,\nQue rebenta nas rochas, e enegrece\nDos mares, e dos céus a claridade,\n\nÀ que tolero em mim não se parece:\nEm breve aquela afrouxa, e se abonança,\nN'esta, de dia em dia, a fúria cresce.\n\nMas oh cruel, tristíssima lembrança!\nSe ao menos de outro o mérito murchasse\nA meus vivos desejos a esperança!\n\nSe outro, digno de ti, me despenhasse\nN'este abismo de horror, n'esta agonia,\nE os prazeres em flor me desfolhasse,\n\nDesculpara a traição, a aleivosia,\nA soberba, o desdém com que me tratas,\nQuando fagueiro amor te merecia:\n\nPorém de puros laços te desatas,\nE n'um sórdido nó tua alma prendes,\nExemplo das cruéis, e das ingratas.\n\nEsse rival objeto, a quem te rendes,\nNão sabe em mole verso harmonioso\nCantar-te as perfeições, com que me acendes:\n\nNão é constante, férvido, extremoso;\nPranto de amor aos olhos não lhe acode,\nNão conhece o que vale um ai piedoso.\n\nAs redes, e os anzóis apenas pode\nIntroduzir no mar co'a mão bisonha,\nE a isca preparar, que o peixe engode.\n\nOh quanto me envilece, e me envergonha\nEsta amargosa ideia! Oh céus!... E é crível\nQue Ulina um torpe amante me anteponha!\n\nCiúme abrasador, paixão terrível,\nDeixa-me; — oh tu, Razão, Razão sagrada,\nPresta-me auxílio, torna-me insensível!\n\nNa mente por amor incendiada\nApaga, desvanece-me os encantos,\nAs graças, e o poder da minha amada.\n\nRompa-se um jugo, tão penoso a tantos,\nCorre... mas ai de mim, que em vão te imploro\nÉs surda a minhas preces, a meus prantos.\n\nNão, não me atendes; e a infiel, que adoro,\nSe paga, e se gloria, e se recreia\nCom as perdidas lágrimas, que choro.\n\nOh tu, que lambes a ditosa areia,\nOnde gozei mil gostos, mil favores,\nMar, que a muda bonança agora enfreia!\n\nPropício à minha dor, e a meus clamores\nSacode a mansidão: tu, rei dos ventos,\nTeus monstros solta, excita-lhe os furores.\n\nTravem raivosa guerra os elementos,\nEnquanto no alto pego a sepultura\nEscolho, por fugir aos meus tormentos.\n\nNoturnas aves da morada escura\nVenham, voando, aqui carpir de dia\nOs rigores de Ulina ingrata, e dura.\n\nAmor, que tantos bens me prometia,\nQuebre os cruéis farpões, que me abrasaram,\nLance um ai de piedade, e de agonia.\n\nOs delfins, os tritões, que me espreitaram\nMil vezes de sentidos, de invejosos,\nQuando amorosas ditas me encantaram,\n\nAgora enternecidos, maviosos,\nVejam como perece um triste amante,\nPor culpa só de uns olhos tão formosos.\n\nBrilhe alegre sorriso em teu semblante,\nOrigem de meu mal, doce inimiga,\nSurge a ver-me, entre as águas flutuante.\n\nGraças ao mar piedoso, à morte amiga;\nIngrata, o seu poder (pois não te abrando)\nAo menos dos teus laços me desliga.»\n\nDisse; e com turvos olhos foi trepando\nAo agro pico de rochedo ingente,\nQue as ondas porfiosas vão cavando.\n\nPara os céus ergue a vista, e de repente\nSe arroja, se despenha o desgraçado,\nVítima da paixão, do mal que sente.\n\nEis que do seio do licor salgado\nSalta a ninfa gentil, mimosa, e nua,\nDos ternos olhos seus objeto amado.\n\n«Espera, caro amante! Inda sou tua!\n(Exclama, e transportada as mãos lhe lança,\nO infeliz arrancando à morte crua):\n\n«Espera, torna em ti, não há mudança\nNo meu cândido amor; de vãos ciúmes\nCom fingida traição tomei vingança.\n\nNão cometo a perfídia, que presumes,\nSou qual fui, sou fiel...» (E orvalha em tanto\nDe chorosa piedade os puros lumes).\n\nÀ voz, e à vista do seu doce encanto\nNo ansioso pescador, no amante aflito,\nQual foi a confusão?... Qual foi o espanto?...\n\nDe prazer desmaiou soltando um grito,\nE a ninfa padeceu no susto a pena\nDo suposto, fantástico delito:\n\nSuspirando o conduz à praia amena,\nOnde lhe dá dulcíssimos instantes...\nDe puros gostos inefável cena,\n\nSempre te gozem corações amantes!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 8 (piscatório)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio (tercetos encadeados de decassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-a-nereida": {"t":["À Foz do Mandovi sereno, e brando\nAlicuto infeliz estava um dia\nAmorosos queixumes espalhando:\n\nAlicuto, o marítimo, que ardia\nPor Glaura, das Nereidas a mais bela,\nQue em vítrea lapa sem pesar o ouvia.\n\nDoudo pela não ver, doudo por vê-la,\nE nas algozas pedras debruçado,\nBradava d'esta sorte ali por ela:\n\n«Tanto, oh Glaura cruel, te desagrado,\nQue não deixas por mim, nem um momento,\nAs crespas ondas, o licor salgado!\n\nOlha que em ais, e em lágrimas o alento\nMe vai fugindo, que a mordaz saudade\nMe rói continuamente o sofrimento:\n\nOlha que lá me tens a liberdade,\nE que mais te não peço em recompensa,\nQue um ar benigno, uns longes de piedade.\n\nÉ digno tanto amor de tanta ofensa?\nAh! Que me faz odioso? A má figura?\nO pé gretado, a pálida presença?\n\nQueres só quem te iguale em formosura:\nPois sabe, que jamais verás objeto,\nQue possa merecer tua ternura.\n\nNão devo à Natureza um grato aspecto,\nÉ verdade: o meu mérito consiste\nN'um claro entendimento, e puro afeto.\n\nSe a compasso da lira o verso triste\nEntoo alguma vez, ao som canoro,\nNinguém, não sendo tu, ninguém resiste:\n\nQue provas mais fiéis de que te adoro,\nQue este incansável pranto? E finalmente,\nDo meu mister que requisito ignoro?\n\nNa manobra quem é mais diligente\nQue eu? Quem sabe deitar melhor o prumo?\nQuem no leme, e n'agulha é mais ciente?\n\nA carga no porão com regra arrumo,\nSei pôr à capa, sei mandar à via,\nComo qualquer piloto, e dar o rumo:\n\nSei como hei de correr com travessia,\nE pela balestilha, ou pelo outante\nAchar a latitude ao meio-dia:\n\nSei qual estrela é fixa, e qual errante;\nA Lebre, o Cisne, a Lira, a Nau conheço,\nE Órion, tão fatal ao navegante.\n\nTalvez muito vaidoso te pareço;\nMas devo assim falar, para que vejas\nQue teus desdéns, oh ninfa, não mereço;\n\nE se o que digo é pouco, e mais desejas,\nIrei, pois, outros méritos ganhando,\nAté que tu de mim contente estejas:\n\nTentarei, por fazer teu gênio brando,\nNunca tentados, nunca vistos mares,\nOs meus antepassados imitando;\n\nE agora, se teus olhos singulares\nPuseres à flor d'água um só minuto,\nDando-me alívio, serenando os ares:\n\nQuero fazer-te um mimo... ai! Já te escuto,\nOuço-te já dizer, que não cobiças\nDonativos do mísero Alicuto;\n\nMas apesar de tantas injustiças,\nHei de cada vez mais mostrar-te o fogo,\nQue tu com teu rigor n'esta alma atiças.\n\nAh! Vem, Nereida, amanse-te o meu rogo:\nSe te enoja o falar, e estar comigo,\nNão fales, aparece, e vai-te logo.\n\nTopamos há três dias o inimigo\nN'altura de Chaul; travamos guerra.\nSentiu do português o esforço antigo;\n\nFez-se uma presa, repartiu-se em terra\nInda agora: o quinhão, que lá me deram,\nEste pintado cofrezinho encerra.\n\nNas mãos um colar de ouro me puseram\nSobre aljôfares mil: vi que, por belos,\nDo teu colo, e teus pulsos dignos eram.\n\nO mesmo foi pegar-lhes, que trazê-los\nPara of'erecer-tos: vem (não é desdouro)\nVem aceitá-los, ou, sequer, vem vê-los;\n\nMas que precisas tu, se és um tesouro,\nSe tens mais lindas pérolas na boca,\nSe tens ouro melhor nas tranças de ouro!\n\nLoucas ideias! Esperança louca!\nLouco Amor! E of'reci com voz ousada\nÀ filha de Nereu cousa tão pouca!\n\nMas se nem alma tão fiel te agrada,\nUm pobre, oh Glaura, um triste marinheiro\nQue mais te há de of'erecer? Não tem mais nada.\n\nJá te entendo (ai de mim!). Bem sei, primeiro\nQual Glauco irei vagar no pego vasto\nSobre as espaldas de delfim ligeiro;\n\nPelo embate das ondas será gasto\nDo soberbo Netuno o gran tridente,\nE os palmares às focas darão pasto;\n\nLá no oposto horizonte do ocidente\nO dia apontará, primeiro (ah dura!)\nQue tu me atendas uma vez somente.\n\nEu que fiz, miserável! Por ventura\nAmor é crime? Para ser querida\nNão criou Jove eterno a formosura?\n\nA que foi como eu, no mar nascida,\nPor vencer Juno, e Palas na beleza\nMais que Palas, e Juno é aplaudida.\n\nPorém se ainda assim supões vileza\nSofreres que um mortal se afoute a amar-te,\nSendo tu de mais alta natureza;\n\nE se levas a mal o importunar-te\nCom ais um coração desesperado,\nTirana, porque tardas em vingar-te?\n\nPune, pune este amor desatinado;\nEu não fujo, aqui estou; das ondas saia\nTragador jacaré, por ti mandado.\n\nSobre mim de repente o monstro caia:\nFolgarás, vendo o sangue de meu peito\nÀs golfadas saltar, tingindo a praia;\n\nE eu morrerei contente, e satisfeito\nPor escapar de estado tão penoso,\nE inda mais por morrer por teu respeito.\n\nSó temo que o meu caso lastimoso,\nO deplorável fim de meus amores\nFaça teu nome a todos horroroso.»\n\nProsseguiria o triste em vãos clamores,\nMas viu, que para ali vinham remando\nNos lúbricos sadós os pescadores,\n\nE ficou mudo, para o mar olhando."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 9 (marítimo)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio (tercetos encadeados de decassílabos)\n\n**Notas sobre o texto.**\n\nVv. 77 e 87, \"off'erecer\": assim na fonte (apóstrofo antes do e); a medida pede a síncope of'recer (3 sílabas)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-as-tagides": {"t":["De Sadino, e Tagano os vãos clamores\nEm tosco verso renovar desejo,\nAmbos amantes, e ambos pescadores.\n\nParece-me que ainda os ouço, os vejo,\nComo quando escondido os espreitava\nOnde, salgado já, sussurra o Tejo.\n\nNo regaço de Tétis descansava\nO louro Febo, à porta do ocidente\nA Noute sobre o carro negrejava;\n\nIa para os casais a rude gente;\nSó do curto batel os dous soltavam\nQueixas, lágrimas, ais inutilmente:\n\nMorriam de saudades, suspiravam\nDe amor por Dinopeia, e por Armia,\nQue entre o coro das tágides brilhavam.\n\nO choroso Tagano a voz erguia,\nE Sadino após ele: eu sempre atento\nDecorava entretanto o que lhe ouvia,\n\nE tal era o recíproco lamento:\n\n::fala TAGANO\nArmia, no semblante mais serena,\nQue o manso Tejo azul, quando nem bole\nA tênue viração na tarde amena,\nEmbalando o raminho curvo, e mole;\nMais ímpia a quem por ti nem olhos cerra,\nQue o tubarão no mar, que o lobo em terra:\n\n::fala SADINO\nDinopeia, mais loura, e mais corada,\nQue a nuvem da manhã, do sol ferida;\nMais branca, mais gentil, mais engraçada\nQue a deusa, que é dos deuses tão querida;\nMais cruel, mais fatal a um triste amante,\nQue o canto da sereia ao navegante:\n\n::fala TAGANO\nMil vezes corro a praia, ora apanhando\nConchinhas para ti, bela inimiga,\nOutr'ora dos penedos arrancando\nRaiados mexilhões, de que és amiga:\nAs mãos, por te agradar, mil vezes firo,\nE nem sequer me sofres um suspiro.\n\n::fala SADINO\nRuivas lagostas, maculosas trutas,\nO salmonete, o pâmpano te of'reço\nPara atrair-te, para ver se escutas\nParte das penas, que por ti padeço;\nMas se vou dar-t'os, foges de improviso,\nE nem sequer me enganas co'um sorriso.\n\n::fala TAGANO\nViste bater no baixo pedregoso\nMísera nau, dos ventos impelida,\nQue, aberto o frágil centro cavernoso,\nEm breve pelas vagas é sorvida?\nPois, qual a triste nau sobre os escolhos,\nMinha alma vim perder n'esses teus olhos.\n\n::fala SADINO\nNão tens visto das ondas agitada\nA boia, sem parar um só momento,\nOu quem sobre os escarcéus com ânsia nada,\nQuase rendido à fúria do elemento?\nPois tal meu coração, por culpa tua,\nEm amorosas lágrimas flutua.\n\n::fala TAGANO\nInda, ninfa cruel, não te enternece\nUm triste, em pranto, em ais quase desfeito?\nAh! Que não sabes quanto mal parece\nUm feroz coração n'um lindo peito,\nN'um corpo delicado alma tão dura,\nTanta maldade em tanta formosura!\n\n::fala SADINO\nNão basta ainda, oh Tágide, não basta\nDe ofensas, de rigor, de iniquidade?\nEm que peito arderá paixão mais casta,\nDo que a minha paixão? Quem na lealdade,\nQuem me vence no amor? De um teu benigno,\nDe um teu suave olhar quem é mais digno?\n\n::fala TAGANO\nQuerem-se os brutos: amam-se os golfinhos,\nE os outros peixes no interior das águas;\nDão-se mil beijos os fiéis pombinhos,\nA todos causa amor prazer, ou mágoas:\nSó tu, que o seu poder não reconheces,\nNem por Amor te alegras, nem padeces.\n\n::fala SADINO\nGemer o deus da gruta os céus ouviram\nPela filha do mar, mãe dos Amores;\nNamorado Netuno as ondas viram,\nE ao selvático Pã os seus pastores;\nArdeu também por Ácis Galateia:\nQuem te resiste, Amor? Só Dinopeia.\n\n::fala TAGANO\nSe por ser pescador te desagrado,\nSe o meu sórdido ofício te injuria,\nTambém com redes Glauco foi criado,\nGlauco viveu também da pescaria:\nQue importa ser humilde? É deus agora,\nHoje como deidade o mar o adora.\n\n::fala SADINO\nSe acaso de meu rosto a cor tostada,\nMeus pés grosseiros, meu cabelo escuro,\nE esta mão, das escotas calejada,\nMe ganham teu desprezo amargo, e duro,\nVê, que nem só na graça, e na beleza\nFaz consistir seus dons a natureza.\n\n::fala TAGANO\nEis por entre as estrelas vem raiando\nA alva lua... eia, assome, oh ninfa bela,\nTeu brando corpo sobre o Tejo brando,\nE sobre o Tejo brilhará mais que ela;\nDá, dá glória a meus olhos... mas ai louco,\nQue esfalfo em gritos vãos o peito rouco!\n\n::fala SADINO\nDeixa, causa gentil de meus martírios,\nDeixa o fundo arenoso, é tempo, amansa\nCom tua vista as ânsias, os delírios\nD'esta alma, que sem ver-te não descansa;\nVem, pois, e o meigo Amor contigo venha...\nMas triste, com quem falo! Ah! co'uma penha.\n\n::fala TAGANO\nSuaves esperanças até'gora\nNutri de amaciar teu gênio duro,\nQue por costume ao coração, que adora,\nSempre se representa um bem futuro;\nMas menos cego já, menos insano,\nOuvidos quero dar ao desengano.\n\n::fala SADINO\nAté'gora pensei que os teus rigores\nÀ força das finezas cederiam;\nQue minhas queixas, lágrimas, e amores\nAo menos compaixão te inspirariam;\nCrédulo fui, mas já desenganado\nConheço que o meu mal provém do fado.\n\n::fala TAGANO\nJá não te aflijo mais, cruel, sossega,\nRepousa, vive alegre, e descansada;\nNunca mais, apesar da paixão cega,\nCom meus gritos serás importunada;\nMas teme que dos deuses a vingança\nVenha punir tão bárbara esquivança!\n\n::fala SADINO\nJá me calo, cruel, já não prossigo\nN'estes vãos desafogos da amargura;\nAssaz desperdicei meus ais contigo,\nDesperdiçá-los mais será loucura;\nMas treme, treme; ainda que te escondas,\nO raio vingador penetra as ondas!\n\nFaltos de alento os dous aqui pararam,\nUm para o outro olhando,\nEm silêncio a chorar continuando:\nE depois que esgotaram\nDe infrutuosas lágrimas o peito,\nSe foram recolher no tosco leito."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 11 (piscatório)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio dialogado (introdução em tercetos encadeados; canto amebeu em sextilhas ABABCC de decassílabos; fecho em silva de decassílabos e hexassílabos)\n\n**Notas sobre o texto.**\n\nInterlocutores Sadino e Tagano.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-outros-soneto-dedicatorio-das-tagides": {"t":["Nem só comove o tom de altos cantores;\nEnternece também, também recreia\nAo som de cristalina, e tarda veia,\nA rude, e baixa voz dos pescadores.\n\nTu, pois, cujo pincel produz mil flores\nDos campos, que Hipocrene aformoseia,\nQueixumes contra Armia, e Dinopeia\nOuve a seus desgraçados amadores.\n\nAis, que deram no Tejo, aqui voaram,\nDepois de serem lá desatendidos\nDas Tágides cruéis, que os motivaram;\n\nAgora vão parar nos teus ouvidos,\nE n'eles com razão, Sebástio, param,\nQue não te enojas de escutar gemidos."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 11 (dedicatória do idílio As Tágides)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Soneto.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-tritao": {"t":["::epigrafe Onia vincit Amor. (Virgil., Eclog. X)\n\nÀ Foz do Tejo, em bronca penedia\nMinada pelas ondas salitrosas,\nPrisioneiro de Amor, Tritão gemia.\n\nLuziam-lhe as espadoas escamosas,\nSustentava o marítimo instrumento,\nO búzio atroador nas mãos calosas:\n\nConchas da cor do líquido elemento\nParte do corpo enorme lhe vestiam,\nIgual na ligeireza ao próprio vento:\n\nDa barba salsas gotas lhe caíam,\nE nos olhos, que amor afogueava,\nEm borbotões as lágrimas ferviam.\n\nLília, que um bosque próximo habitava,\nLília a Napeia, desdenhosa e bela,\nAmorosos clamores lhe arrancava:\n\nUm dia a viu na praia, e só de vê-la\nSeu coração feroz enfeitiçado,\nVoou, gemendo, para os olhos d'ela,\n\nDas entranhas do pélago salgado,\nLouco de amores, louco de saudades,\nO queixoso amador tinha saltado:\n\nDo pai, que abafa as negras tempestades,\nJá seu voraz tormento era sabido,\nE das outras equóreas divindades.\n\nDe aéreas esperanças iludido,\nGran tempo seu espírito saudoso,\nRastejando a cruel, vagou perdido;\n\nGran tempo glórias vãs sonhou, teimoso,\nAntes que desse frutuosa entrada\nAo acre desengano o peito ansioso.\n\nJá pela transparente, imensa estrada\nNo coche rutilante o Sol corria\nApós a Aurora cândida, e rosada,\n\nQuando envolto nas sombras da agonia\nAo vento derramava o deus amante\nTais queixas, que eu não longe oculto ouvia:\n\n«Lília! Lília! Ah cruel! Ver um instante\nTeus olhos garços, tuas louras tranças\nPara meu lenitivo era bastante.\n\nArdo, choro, e não vens, e não te amansas!\nOh céus! Talvez nos braços cabeludos\nDe vil, bicórneo Sátiro descansas?\n\nFera, pior que os jacarés sanhudos,\nRirás talvez com ele, enquanto abalo\nCom meus suspiros os penhascos mudos!\n\nAh! De zelos frenéticos estalo,\nE doces ilusões desvanecendo,\nNa desesperação o inferno igualo.\n\nQuantas serpes contêm seu bojo horrendo\nVem cravar-me o letal, maligno dente\nPelas entranhas, que me estão fervendo.\n\nComo te sofre o céu, como consente\nQue ultrajem teus desdéns a prole augusta\nDo númen, que maneja azul tridente!\n\nNão ponderas quem sou, bárbara injusta!\nSe o meu rendido amor te não comove,\nNem meu grande poder sequer te assusta!\n\nNo mar à minha voz tudo se move:\nEu aos deuses undívagos intimo\nAltos decretos do cerúleo Jove:\n\nDe Éolo as fúrias em tão pouco estimo,\nQue até na horrível, sinuosa gruta\nCom cem cadeias os tufões lhe oprimo:\n\nMuge o mar, treme a terra, o céu se enluta\nApenas, tempestade apregoando,\nEste meu búzio côncavo se escuta:\n\nTambém, se quero, os duros sons lhe abrando;\nE os magos versos do cantor de Trácia\nVou no rijo instrumento arremedando;\n\nE desprezas-me ainda, e tens a audácia\nDe rejeitares com soberbo enfado\nO filho de Netuno, e de Salácia!\n\nEm que, ninfa cruel, te desagrado?\nQue te afugenta? As lúcidas escamas,\nAs verdes conchas, de que estou forrado?\n\nPois isto, que, por feio, em mim desamas,\nE que te obriga a nunca me escutares,\nGera em mais dócil peito ardentes chamas.\n\nOh quantas vezes sai dos vítreos lares\nSó para ver-me Arginia, que, em se rindo,\nEnfreia os ventos, agrilhoa os mares!\n\nA Dóris, à benigna mãe fugindo,\nBrando afago me traz no lácteo rosto:\nO teu vaidosa, o teu não é mais lindo;\n\nMas a seus doces mimos sempre oposto\nAcha meu coração, que foge d'ela,\nE vem sacrificar o amor ao gosto.\n\nDebalde a triste ninfa se desvela\nEm finezas, e em lágrimas, que tudo\nEnjeito por amar-te, oh dura, oh bela:\n\nCom semblante enrugado, e carrancudo,\nLhe atalho os ternos ais, e, se porfia,\nOu as costas lhe volto, ou fico mudo.\n\nOh pasmo! Nem Proteu pensar devia\nQue eu por uma campestre semideia\nA prole de Nereu desprezaria.\n\nMas ah! Já sinto Amor, que me refreia\nA petulante voz. — Não mais, perdoa\nÀ desesperação, gentil Napeia:\n\nPara meus braços amorosos voa,\nVoa, e verás então, que alegres hinos\nMeu rude búzio, respirando entoa.\n\nDepois de ouvires os meus sons divinos,\nMergulhando comigo, irás sem medo\nAos majestosos paços netuninos;\n\nLá no seio de um côncavo rochedo\nJaz de meu pai a esplêndida morada,\nD'onde para te ver saí tão cedo:\n\nDe ouro, e safiras altamente obrada,\nE de lustrosas conchas de mil cores\nCom mimoso artifício variada,\n\nAtrairá teus olhos, e os Amores,\nQue te acompanham, lograrão, pasmados,\nMais prazer entre as águas, que entre as flores:\n\nAli sobre diáfanos estrados\nOh Lília, a par de Tétis, e Anfitrite\nRepousarão teus membros delicados:\n\nEm honra tua festival convite\nFarei aos pátrios deuses: o meu gosto\nNos mesmos imortais inveja excite:\n\nMeu venerando pai, no sólio posto,\nCom grave riso, e plácida alegria\nA senil ruga alisará no rosto:\n\nRubros corais, fulgente pedraria\nTe of'recerá nos cândidos regaços\nA chusma das Nereidas à porfia:\n\nAquela mesma, que em gostosos laços\nPretende unir-me a si, teus olhos vendo\nConfio que te aperte entre seus braços:\n\nTanto poder terás! Ah! Vem correndo,\nQue já seus raios de ouro o Sol dardeja\nDo etéreo carro, o mundo esclarecendo:\n\nPunge os Etontes, como que deseja\nA queda antecipar nas águas, onde\nDe perto, oh ninfa, tuas graças veja.\n\nVem, pois, encanto meu, vem, corresponde\nAo fervoroso amor, em que me inflamo,\nSai d'entre a basta selva, que te esconde.\n\nMas ai, que em vão te rogo, em vão te chamo:\nNem fazes caso de meu ser divino,\nNem das lágrimas tristes, que derramo.\n\nPeito insensível, peito diamantino,\nÀs maviosas preces da ternura\nNão amaciam teu rigor ferino.\n\nAh! Basta de cegueira, e de loucura,\nBasta de suspirar, paixão funesta:\nQuem há de n'uma penha achar brandura?\n\nVíboras, que jazeis n'essa floresta,\nVingai-me, envenenai c'o tênue dente\nA ingrata, que me foge, e me detesta:\n\nSinta rábidas ânsias, como sente\nMeu triste coração, de amor ferido,\nAtassalhado de pior serpente...\n\nMas não. Fúrias do inferno, eu vos convido!\nSois mais dignas de mim: de vós se vale\nUm deus irado, um deus escarnecido:\n\nRebentai do vulcão, que o mundo abale,\nE a peste, que exalais do peito horrendo,\nO férreo coração de Lília rale!»\n\nCalou-se, e do alto escolho à pressa erguendo\nO formidável corpo, inda mais alto,\nE as negras mãos, frenético, mordendo,\n\nPor entre as ondas se abismou de um salto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Idílios e cantatas, 13 (marítimo)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Idílio (tercetos encadeados de decassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-idilio-queixumes-do-pastor-elmano": {"t":["::epigrafe Metido tenho a mão na Consciência, / E não falo senão verdades puras, / Que me ensinou a viva experiência. (Camões)\n\nSeu manto desdobrava a Noite escura,\nE a Rã no charco, o Lobo na espessura\nVociferando, os ares atroavam;\nDo trabalho diurno já cessavam\nOs rudes, vigorosos Camponeses:\nO Vaqueiro, cantando atrás das Reses,\nApós as Cabras o Pastor cantando,\nIam para as Malhadas caminhando;\nTudo jazia em paz, menos o triste,\nO desgraçado Elmano, a quem feriste,\nOh pernicioso Amor, cruel Deidade,\nFlagelo da infeliz Humanidade:\nTudo, enfim, descansava, exceto Elmano,\nQue a mão do Fado, universal Tirano,\nSentia sobre si descarregada;\nQue, longe da Paterna Choça amada,\nDependente vivia em Lar estranho,\nSendo os desgostos seus o seu rebanho.\nHonrados Maiorais o Ser lhe deram\nLá junto ao Sado ameno, e lhe fizeram\nDas Artes cortesãs prezar o estudo:\nAs Musas o encantaram mais que tudo,\nAteando-lhe n'alma o Fogo santo,\nQue estúpidos Mortais desdenham tanto.\nInflamado com ele, ao som da Lira\nQuebrava dos Tufões a força, a ira,\nE o venerando Tejo sossegado,\nA cuja fresca praia o trouxe o Fado,\nMil vezes, para ouvir-lhe as ternas mágoas,\nA limosa cabeça ergueu das Águas.\nCego, convulso, pálido, e sem tino\nEntrava na Cabana de Francino\nO desditoso Elmano. Entre os Pastores\nGeral estimação, gerais louvores\nFrancino com justiça desfrutava:\nAlto saber, o Espírito lhe ornava,\nNa vasta Capital fora criado,\nE por expertos Mestres cultivado.\nDoce nó de Amizade os dois unia,\nConcorrendo a Razão, e a Simpatia\nPara tão bela, e plácida Aliança.\nNotando, pois, a fúnebre mudança,\nQue no aspecto do Amigo aparecia,\nAssim Francino a causa lhe inquiria:\n\n::fala FRANCINO\nQue tens, Elmano? Que fatal desgosto\nBanha de tristes lágrimas teu rosto?\nTu, que, ainda há brevíssimos instantes,\nTe aclamavas feliz entre os Amantes,\nLogrando mil carinhos, mil favores\nDe Urselina gentil, dos teus Amores,\nVens tão choroso, tão aflito agora!\nAh! Conta-me a paixão, que te devora,\nDas ânsias tuas o motivo explica:\nComunicado o mal, mais brando fica.\n\n::fala ELMANO\nAi de mim! Venho louco, estou perdido.\nOh peito ingrato! Coração fingido!\nOh desumana, oh bárbara Pastora!\nFementida Mulher enganadora!\nE tiveste valor para a mais feia\nTraição, que pode conceber a ideia?\nÉ possível! É certo! Oh Céus! Socorro.\nEu pasmo, eu desespero, eu ardo, eu morro.\n\n::fala FRANCINO\nAmigo, torna em ti, recobra alento,\nDeclara-me o teu íntimo tormento.\nDo cego frenesi, que te domina,\nQuem é causa, Pastor? É Urselina?\n\n::fala ELMANO\nQuem, senão ela (oh Céus!) me obrigaria\nA tão pasmoso extremo? A Sorte impía\nCom todo o seu poder nunca tem feito\nDesmaiar a constância de meu peito:\nQuem me abate é Amor, não o Destino.\nEu te conto o meu mal, eu vou, Francino,\nRetratar-te a mais negra, a mais horrível\nDe todas as traições. Não é possível\nNos Ermos encontrar da Líbia ardente\nMonstro, seja Leão, seja Serpente,\nQue possa comparar-se à Fera humana,\nQue com tanto rigor me desengana.\nQuantas vezes notaste, honrado Amigo,\nFinezas, que a traidora obrou comigo!\nQuantas vezes daqui presenciaste\nSeus gestos, seus afagos, e julgaste,\nQue o mais ardente amor, a fé mais pura\nPagavam minha cândida ternura!\nOuve, e conhecerás (ai de mim triste!)\nQue foi sonho, ilusão tudo o que viste.\nJá sabes, que no dia em que ligado\nA Márcia Jônio foi pelo sagrado,\nIndissolúvel nó, cantei louvores\nA tão ditosos, tão fiéis amores,\nE o número aumentei dos Convidados;\nJá sabes as meiguices, e os agrados,\nCom que a minha infiel me fez ditoso:\nAli, traçando um baile harmonioso,\nPor parceiro me quis; ali sentada\nJunto a mim, vezes mil a refalsada\nProtestou, que em sua alma eu só vivia,\nQue eu era de seus olhos a alegria,\nDando-me a bela mão furtivamente,\nQue, ardendo de paixão, beijei contente.\nPediu-me a desleal, que ali tornasse,\nQue tão doce prazer lhe não roubasse:\nGuiado por Amor, fui inda agora\nSeu desejo cumprir, que antes não fora,\nPorque não sentiria este martírio,\nEste ardor, esta raiva, este delírio.\nJônio, que estava à porta da Cabana,\nMe veio receber... ah! Quanto engana\nUma aparência alegre, e carinhosa!\nEntrei, pus logo os olhos n'aleivosa,\nQue, em vez de me tratar com meigo agrado,\nTinha nas faces o desdém pintado.\nPasmando da mudança repentina,\nLhe disse: amado bem, cara Urselina,\nTu comigo tão áspera? Eu ignoro\nEm que pude agravar quem tanto adoro.\nIsto dizendo, avizinhei-me a ela,\nQue estava ao pé da rústica janela,\nE da terna pergunta não fez caso,\nNem o rosto voltou, e olhando acaso\nÀ próxima Cabana de Nigela,\nVi encostado Inálio à porta dela\nOlhar para Urselina, a Deus dizer-lhe,\nE sem pejo a Cruel corresponder-lhe\nC'um doce riso, um gesto namorado,\nDe amantes expressões acompanhado.\nFervendo-me no peito o amor, e a ira,\nLogo, logo em pedaços fiz a Lira,\nE em mil imprecações, em mil queixumes\nO furor exalei dos meus ciúmes,\nAmeaçando a infiel, que eu me vingava\nNo odioso Rival, que me afrontava,\nSe uma satisfação, que Inálio visse,\nLogo o meu pundonor não ressarcisse.\nPrometeu-me, que sim, mas de repente\nA meus olhos se esconde, e vai contente\nO lerdo, o baixo Amante encher de glória,\nQue não cabia em si pela vitória,\nQue a pior das traições lhe tinha dado.\nFiquei louco, fiquei desesperado,\nContemplando este assombro nunca visto\nNem na imaginação. Não para nisto\nDaquela ingrata a pérfida baixeza:\nDe novas fúrias cruelmente acesa,\nProcura Aónio, inerte Pegureiro\nQue é o riso da gente no Terreiro\nQuando sai a bailar, e a cada passo\nSe esquece da harmonia, e do compasso,\nSendo falto de prendas, e de siso\nComo o louco Magálio, o rude Anfrizo.\nUrselina lhe diz, que me incitasse\nA que a Choça de Jônio abandonasse,\nPersuadindo-me, enfim, que não devia\nPresenciar a afronta, que sofria.\nAcreditei o indigno Conselheiro,\nE saí da Cabana, onde primeiro\nTinha logrado os mimos da perjura,\nQue assim desenganou minha ternura.\nAh gênio desleal, falaz, perverso!\nDaquilo, que pensei, como és diverso!\nAi! Não me alucinava o meu ciúme,\nEra mais do que justo o meu queixume,\nQuando (triste de mim!) quando julgava\nQue Inálio, inda que simples, te agradava!\nAcusei-te mil vezes de fingida,\nDe que a ele querias ver-te unida\nEm laços de Himeneu; mas tu negaste\nSempre o que hoje sem pejo declaraste.\nTraidora! Eu não dizia, eu não jurava,\nQue o meu sossego ao teu sacrificava!\nAh! Porque me não deste o desengano,\nQue eu te pedia, Coração tirano?\nSe Inálio, porque tem Campos, e Gados,\nNumerosos Casais, amplos Montados,\nAtrai esse teu gênio interesseiro,\nE eu, posto que leal, que verdadeiro,\nDe clara geração, de sangue honrado,\nCaducos, frágeis bens não devo ao Fado,\nE por isso não posso no teu peito\nProduzir da ternura o doce efeito;\nQue razão te obrigou a acarinhar-me,\nE de um fingido amor capacitar-me?\nCoração, em perfídias atolado,\nÍmpia, se o não tivesse inda criado\nA vingadora Mão de Jove Eterno,\nDevia para ti criar o Inferno.\n\n::fala FRANCINO\nConsola-te, Pastor; essa perjura\nNão deve motivar tua amargura;\nCastiga-lhe a traição, e o fingimento\nLançando-a n'um profundo esquecimento.\nQue mais satisfação, que mais vingança\nQueres da vil, da súbita mudança,\nQue ver exposta a pérfida Pastora\nAo ludíbrio geral? Uma traidora,\nUma fera, uma ingrata, inda que bela,\nNão merece a paixão, que tens por ela.\nPondera, que não foste injuriado\nDe seu duro desprezo inesperado,\nQue o feminil capricho extravagante\nNão te deslustra o mérito brilhante.\nNenhum, nenhum Pastor n'Aldeia ignora,\nQue essa, que te deixou, foi atégora\nCarinhosa contigo, e fez patente\nSua correspondência a toda a Gente:\nDemonstrações em público te dava\nDe amorosa paixão, mas não te amava:\nBaixo costume, natural fraqueza\nÉ que a fez parecer de amor acesa;\nAquela alma não arde, não se inflama,\nA todos corresponde, a ninguém ama.\nBem se viu com Bersálio, e com Laurênio\nSeu inconstante, seu volúvel gênio:\nTé no mais desprezível dos Pastores\nÉ capaz de empregar seus vis amores,\nNunca soube escolher, tudo lhe agrada,\nE inda que astutamente infatuada\nFaça crer aos Amantes o contrário,\nÉ já sabido seu caráter vário.\nIsto em teu coração gravado fique,\nE não queiras, Pastor, maior despique:\nSe atégora calei quanto te digo,\nFoi por não te afligir, prezado Amigo.\nPouco importa perder quem nada vale.\nContente-te, que toda a Aldeia fale\nContra a sua imprudente aleivosia,\nQue, se pensasse bem no que fazia,\nJamais o falso Monstro, que te deixa,\nFechara a tudo os olhos como feixa.\nDeveria lembrar-se a fementida\nDe que a sua afeição foi conhecida,\nDe que inda em tuas mãos tens os penhores\nDe seus furtivos, tácitos favores,\nPara não te obrigar com tal injúria\nA que dos zelos a violenta fúria\nDespedaçasse um véu misterioso,\nUm véu tão necessário como honroso.\nMas verás se mais hora menos hora\nNão é punida a infiel Pastora:\nDoiradas esperanças lisonjeiras\nNutrem-lhe ideias vãs, e interesseiras;\nMas Inálio é como ela ambicioso,\nE só deseja um Himeneu lucroso,\nQue lhe farte a cobiça, os bens lhe aumente:\nEle próprio mo disse, ele não mente,\nQue a sua natural simplicidade\nNão pode mascarar a sã verdade.\nEia, pois, cesse o pranto, enxuga o rosto,\nAdora a Providência em teu desgosto,\nNão delires, Pastor, não desesperes,\nQue és feliz em saber quem são Mulheres.\n\n::fala ELMANO\nSim, meu amado, meu leal Francino,\nEu dou mil graças ao Poder Divino\nPor me livrar do engano em que vivia,\nEu lutarei c'o a terna simpatia,\nQue me fez adorar uma inconstante,\nAos falsos Crocodilos semelhante.\nEmbora logre Inálio os seus agrados\nFingidos, mentirosos, estudados.\nO sórdido interesse é quem a inspira:\nSe da Fortuna o meu Rival sentira\nA triste, perniciosa variedade,\nSe a violência de horrível Tempestade\nLhe derribasse as férteis Oliveiras,\nSe o fogo lhe engolisse as Sementeiras,\nSe a Cheia lhe afogasse os nédios Gados,\nVerias em desdéns, e em desagrados\nMudar-se logo o amor, que finge a astuta,\nQue de negra cobiça a voz escuta:\nTu a verias outra vez comigo\nAs chamas assoprar do afeto antigo,\nMendigando razões para aplacar-me,\nPara me convencer, para enganar-me.\nMas ah paixão! Teu ímpeto reprime,\nE busque-se vingança igual ao crime.\nRitália bela, encanto dos Pastores,\nMerece meus suspiros, meus amores:\nCom ela fui mil vezes desatento,\nNegando-lhe o devido acatamento\nPor cumprir o preceito rigoroso\nDe Urselina infiel, que no enganoso,\nNo detestável peito encerra, e nutre\nDa venenosa Inveja o feio Abutre,\nPorque a meiga Ritália é mais do que ela\nBranda, risonha, delicada, e bela\nQuanto é mais agradável, mais formosa\nQue as outras flores a punícea rosa.\nRitália desde agora o lindo objeto\nSerá do meu fiel, constante afeto:\nArrebatado em êxtasis de gosto,\nLouvores de seus olhos, de seu rosto\nFarei voar nas asas da ternura,\nE assim me vingarei d'uma perjura.\nEla, por timbre meu, o escute, o saiba,\nE o Coração no peito lhe não caiba\nDe inveja, de furor: eu, entretanto,\nTroque em plácido riso o triste pranto,\nE a fria indiferença, com que intento\nRecompensar-lhe o torpe fingimento,\nAté tão alto grau nesta alma cresça,\nQue eu veja a desleal, e a não conheça."],"e":{"apresentacao":"**Publicação.** Queixumes do pastor Elmano contra a falsidade da pastora Urselina. Écloga (1791); na ed. de 1875, vol. II, Idílios e cantatas, 14.\n\n**Ortografia.** Atualizada (fonte: Queixumes do pastor Elmano, Lisboa, Officina de Simão Thaddeo Ferreira, 1791)\n\n**Forma.** Écloga dialogada (parelhas de decassílabos rimados)\n\n**Notas sobre o texto.**\n\nNo texto atualizado mantêm-se \"impía\" (im-pí-a, com o acento que a medida pede), \"feixa\" (= fecha, em rima com deixa), \"êxtasis\" (fonte: extasis), \"atégora\", \"Doiradas\" e \"dois\" (assim na 1.ª edição; a de 1875 traz dous)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Queixumes_do_Pastor_Elmano_Contra_a_Falsidade_da_Pastora_Urselina"}]}},
"bocage-ode-o-desengano": {"t":["Assaz temos cantado, assaz carpido\nOh lira, oh doce lira,\nOs bens e os males do comum tirano,\nQue nas almas derrama\nA dor, e o riso, o néctar, e o veneno.\nLonge a brilhante ideia\nDe olhos fagueiros, de aneladas tranças,\nDe angélicos sorrisos,\nDe momentâneos amorosos furtos;\nLonge a amarga lembrança\nDe vis perjúrios, de cruéis enganos,\nDe traições estudadas;\nLonge as memórias da infiel Marília.\nFeitiços perigosos,\nVerdugos da alterosa Liberdade;\nTu, dom da formosura,\nFatal aos corações, suave aos olhos;\nTu, que em meus pensamentos\nNo arbítrio meu despótico imperavas,\nTirano, impõe teu jugo,\nTeu férreo jugo na cerviz d'aqueles\nQue a sisuda Experiência\nPor entre pavorosos precipícios\nInda ao templo remoto\nNão guiou do profícuo Desengano.\nVencida a longa estrada,\nOnde o Erro elevou montes e montes\nPara estorvar ao homem\nSagaz instinto, que à Verdade o guia,\nVejo, saúdo os lares,\nLares augustos do terrível nume,\nAtento à voz do aflito\nQue ingênuas preces lhe dirige às aras,\nSurdo a rogos falazes\nDo cego escravo, que idolatra os ferros,\nLiberdade implorando...\nQue solidão, que plácida tristeza,\nQue profundo silêncio\nReina em torno do alcáçar venerando!\nOh sacro domicílio\nDa Verdade imortal!... Que! Tu n'um ermo!\nOs teus átrios desertos,\nSem culto, sem ministro os teus altares,\nEnquanto à vã grandeza\nServil caterva prostitui incensos,\nE a curvada Lisonja\nOs crimes doura, os vícios abrilhanta!\nAh! Eu te vingo, oh deusa!\nEu entro o franco pórtico espaçoso\nE às aras... Mas que sinto!\nQue gelo, que tremor, que sobressalto\nMe prende a voz, e a planta,\nMe abate as forças, me arrepia as carnes!\nCoração, que te assombra?\nQue temes, coração? Perder Marília?\nMarília acaso é tua?\nNão maculou traidora os puros votos,\nOs ternos juramentos?\nNão viste a desleal sem dor, sem pejo,\nCevar-se nos teus males,\nC'os lindos olhos em Fileno absortos?\nQue importa que em seus lábios,\nSeu ledo rosto, seu virgíneo seio,\nOs Amores, e as Graças\nPressintam mil imagens deleitosas,\nOnde os sentidos pascem,\nQue importa, se a traição surgiu do averno\nA corromper-lhe o peito?\nQue vale sem virtude a formosura?\nCede ao tempo, à desgraça;\nDo espírito a beleza é sempre nova.\nCoração, triunfemos,\nTriunfemos da pérfida Marília,\nE se a razão não basta,\nVença a vaidade o que a razão não vence.\nEnvergonha-te ao menos\nDe seres só feliz quando o permite\nO teu rival soberbo,\nQue enjoando os afagos importunos\nDa perjura, que adoras,\nÀs vezes com desprezo em ócio os deixa,\nE se a ti se dirigem,\nNão vêm do coração, vêm do costume.\nEia, mísero escravo,\nSacode o jugo, despedaça os ferros,\nA vaidade te anime:\nQuase tudo o que é raro, estranho, ilustre,\nDa vaidade procede,\nMóvel primeiro das ações pasmosas.\nTente-se a grande empresa,\nForcem-se os fados... Ai de mim! Palpitas?\nE em frequentes arrancos\nComo que exprimes o pavor da morte!\nCoração, não desmaies,\nAlenta-te, infeliz... Porém que escuto!\nQue ruído! que assombro!\nQue resplendor me cerca, e me deslumbra!\nTorvos dragões, batendo\nAsas de negra cor com duro estrondo,\nSe encontram, se atropelam,\nE quais noturnas aves, que amedronta\nO clarão matutino,\nEspavoridos pelos ares fogem\nAo fulgor cintilante\nDe rubro facho, que na destra empunha\nVenerável matrona,\nLibrada sobre os Zéfiros plumosos!\nAh! Quem és? Vens do Olimpo,\nPortentosa visão? Vens socorrer-me?\nOu és aéreo fruto\nDa enferma, delirante fantasia,\nQue entre ilusões vagueia?...\nNão; já me iluminaste a mente cega,\nReconheço-te, oh deusa,\nÉs a prole dos céus, és a Virtude,\nQue no benigno seio\nAcolhes os meus ais, os meus remorsos,\nIndulgente à demora\nQue tive em demandar teu santo asilo.\nEsses monstros, voando\nAnte o celeste resplendor, que espraias,\nSão pungentes saudades,\nFeias traições, frenéticos ciúmes,\nQue invisíveis té agora\nAs cálidas entranhas me ralavam.\nGraças, oh divindade,\nQue do sábio varão manténs o esforço\nQuando a volúvel sorte,\nInimiga do mérito, o sepulta\nNas solitárias sombras\nDe profunda masmorra aferrolhada,\nOnde por mãos infames\nDe aspérrimas correntes o carrega:\nMunido da inocência\nContigo ri o herói no cadafalso;\nContigo alegre observa\nDo carrancudo algoz na mão terrível\nO amolado cutelo\nExecutor da bárbara sentença;\nE contigo, oh deidade,\nOh alta benfeitora, encaro as portas\nDo formidável templo.\nTeu sagrado fervor de veia em veia\nMe agita, me transporta,\nEu te sigo, eu te sigo... Oh céus! Oh deuses!\nJá sou meu, já sou livre.\nÍdolo falso, que de altar profano\nDavas leis à minh'alma,\nRecebias meus votos, meus incensos,\nTributos da fraqueza;\nAleivosa Marília, horror e afronta\nTé do tropel de ingratas,\nDe astutas, de infiéis, que o mundo infamam,\nO escravo de teus olhos,\nA vítima infeliz de teus enganos\nJá tem rotos os ferros,\nSolta a vontade, o coração tranquilo.\nComo o sol, quando vibra\nNa cristalina esfera os raios d'ouro,\nGasta, desfaz, consome\nVapores, que exalou do seio a terra;\nTambém, falaz Marília,\nAs luzes, que a verdade em mim dardeja,\nAbsorvem, desvanecem\nA funesta ilusão, que na minh'alma\nTe assemelhava aos deuses.\nIngrata, consumiram-se os incensos,\nRetrataram-se os votos,\nForam-se as oblações, e os sacrifícios,\nCaiu o altar, e o númen!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Odes, I.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Ode (silva de decassílabos e hexassílabos alternados, sem rima)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-ode-anacreontica-veloz-borboleta": {"t":["Veloz Borboleta,\nQue leda girando\nPenosas ideias\nMe estás avivando:\n\nInseto mimoso,\nAos olhos tão grato,\nDa minha tirana\nTu és o retrato:\n\nA graça, que ostentas\nNas plumas brilhantes,\nTem ela nos olhos\nGentis, penetrantes;\n\nTu andas brincando\nDe flor para flor;\nAnarda vagueia\nD'amor em amor."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Odes anacreônticas, 1.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Ode anacreôntica (quadras de redondilha menor, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-ode-anacreontica-os-teus-prisioneiros": {"t":["Os teus prisioneiros,\nCupido, os que devem\nSaber definir-te,\nQue mal te descrevem!\n\nÉs áspide (afirmam)\nCoberto de flores,\nSedento d'estragos,\nAmigo de horrores:\n\nSustentam carpindo\nQue os feres, e enleias\nCom áureos virotes,\nCom férreas cadeias:\n\nEnganam-se, oh nume!\nTeus laços, teus tiros\nSão longas madeixas,\nSão ternos suspiros."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Odes anacreônticas, 2.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Ode anacreôntica (quadras de redondilha menor, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-ode-anacreontica-de-liquido-aljofar": {"t":["De líquido aljôfar\nAs faces bordadas,\nAo vento dispersas\nAs tranças douradas:\n\n«Vingança, meu filho\n(Clamava Ericina)\nQue a vil natureza\nSe atreve à divina:\n\n«Em dano de um ímpio\nMortal, que me afronta,\nVenenos prepara,\nTormentos apronta:\n\n«Elmano em seus hinos\nPrefere-me Isbela;\nDiz que é mais mimosa,\nMais loura, mais bela.\n\n«Os teus males todos\nMe vinguem, oh nume!...»\nAmor a interrompe:\n—Não basta o ciúme?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Odes anacreônticas, 3.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Ode anacreôntica (quadras de redondilha menor, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-ode-anacreontica-formosa-marilia": {"t":["Formosa Marília,\nModelo das Graças,\nQue mil pensamentos\nAcendes, e enlaças:\n\nÀquele, que animam\nTeus doces agrados,\nTerror dos amantes,\nMimoso dos fados,\n\nSe folgas de ouvi-lo\nPor ti suspirar,\nAo céu dos amores\nNão deixes voar.\n\nDos homens ignoras\nA índole errante?\nQuem é muito amado\nNão é muito amante."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Odes anacreônticas, 4.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Ode anacreôntica (quadras de redondilha menor, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-cancao-o-ciume": {"t":["Agora, que ninguém vos interrompe,\nLágrimas tristes, inundai-me o rosto,\nMais do que nunca; assim o quer meu fado:\nEnquanto o gume de mortal desgosto\nMe não retalha os amargosos dias,\nDebaixo d'estas árvores sombrias\nGrite meu coração desesperado,\nMeu coração cativo,\nQue só tem nos seus ais seu lenitivo.\n\nAlterosas, frutíferas palmeiras,\nVós, que na glória equivaleis aos louros,\nVós, que sois dos heróis mais cobiçadas\nQue áureos diademas, que reais tesouros,\nEscutai meus tormentos, meus queixumes,\nMeus venenosos, infernais ciúmes;\nOuvi mil penas, por Amor forjadas,\nMil suspiros, mais tristes\nQue todos esses, que até aqui me ouvistes.\n\nAqueles campos, aprazíveis campos,\nQue além verdejam, de meu mal souberam\nA desgraçada, mas suave origem:\nAli de uns olhos os meus ais nasceram;\nAli de um meigo, encantador sorriso,\nQue arremeda o sereno paraíso,\nBrotaram mil infernos, que me afligem,\nQue as entranhas me abrasam,\nQue meus olhos de lágrimas arrasam:\n\nAli de uns lábios, onde as Graças brincam,\nOuvi suspiros, granjeei favores,\nAli me disse Anarda o que eu não digo;\nAli, volvendo os ninhos dos Amores,\nCravou n'esta alma, para sempre acesa,\nAs perigosas frechas da beleza;\nAli do próprio mal me fez amigo,\nAli banhou meu rosto\nParte do coração, desfeita em gosto.\n\nNovas campinas testemunhas foram\nDe nova glória, de maior ventura,\nTal, que julguei, logrando-a, que sonhava:\nEntre as doces prisões da formosura,\nEntre os cândidos braços deleitosos,\nMeus crestados desejos amorosos\nNo alvo rosto, que o pejo afogueava,\nNo néctar... ah! que eu morro,\nSe em vós, furtivos êxtasis, discorro!\n\nAmor! Amor! Teus júbilos excedem\nDa loura abelha os engenhosos favos,\nMais gratos são que as flores teus sorrisos:\nGostei todos os bens, que aos teus escravos\nFazem tão leve a rígida cadeia,\nTão doce a chama, que no peito ondeia:\nMas oh! Cruéis teus dons, cruéis teus risos,\nPrincípio do tormento,\nQue já me tem delido o sofrimento.\n\nMiserável de mim! Qual o piloto,\nQue lera nos azuis, filtrados ares\nIndícios de uma sólida bonança,\nE eis que vê de repente inchar os mares,\nVestir-se o céu de nuvens, d'onde chove\nO fogo vingador, que vibra Jove;\nTal eu, quando supus mais segurança\nNo meu contentamento,\nO vi fugir nas asas de um momento.\n\nAnarda, Anarda pérfida, teus olhos,\nOnde Amor traz escrita a minha sorte,\nTeus mimos por mim só não são gozados!\nOh desesperação, pior que a morte!\nOh danados espíritos funestos,\nDe hórridos vultos, de terríveis gestos,\nModerai vossa queixa, e vossos brados,\nQue as penas do profundo\nTambém, também se encontram cá no mundo!\n\nVer outro disputar-me o caro objeto,\nEm cujas lindas mãos pus alma, e vida,\nNão me arranca suspiros: o tormento,\nQue no peito me faz mortal ferida,\nO maior dos tormentos, oh perjura,\nÉ ver, que de outrem sofres a ternura:\nÉ ver, que dás calor, que dás alento\nA seus mimos, e amores\nCo'um riso, percursor de mil favores.\n\nTu não foges de mim, tu não te esquivas\nD'estes olhos, que em ti cativos andam;\nDelícias, onde pasma o pensamento,\nDoces instantes meu ciúme abrandam:\nMas ah! Não é só minha esta ventura,\nMeu vaidoso rival a tem segura.\nQue indigna variedade! Em um momento\nTeus olhos inconstantes\nAcarinham sem pejo a dous amantes.\n\nHonra, Virtude, Agravo, e Desengano\nMe gritam n'alma, que sacuda os laços,\nQue tanto sofrimento é já vileza;\nOuço-os, protesto desdenhar teus braços,\nProtesto, ingrata, converter meus cultos\nEm mil desprezos, irrisões, e insultos:\nMas ah! Protestos vãos, baldada empresa!\nSou a amar-te obrigado;\nNão é loucura o meu amor, é fado.\n\nCanção, vai suspirar de Anarda aos lares;\nMas se não lhe firmares\nO instável coração, deixa a perjura,\nE iremos sossegar na sepultura."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Canções, 1 (publicada nas Rimas, tomo I, 1791)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Canção (onze estâncias de nove versos, decassílabos com o oitavo hexassílabo, rima ABCBDDCeE; remate aBCC)\n\n**Notas sobre o texto.**\n\nA ed. de Daniel Pires (2005), que segue as Rimas de 1791, lê \"venerosos\" no v. 15 (aqui \"venenosos\", como em 1875)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-cancao-o-desengano": {"t":["Alma ferida e cega,\nQue em grilhões vergonhosos\nAdoras a mão impía, que te entrega\nA males tão cruéis, e tão penosos,\nComo os que sentem no maldito averno\nOs condenados entre o lume eterno:\n\nAlma cega, e perdida,\nQue a doce liberdade,\nO gosto, as horas, o descanso, a vida\nConsagras à maligna divindade,\nAntes ao monstro, que produz, que gera\nVeneno inda pior que o de Megera:\n\nBasta, faze em pedaços\n(Porque a razão te grita)\nFaze, que é tempo, esses indignos laços,\nEssas cadeias vis: oh alma aflita,\nA virtude, a verdade, o céu te valha;\nVence a terrível, infernal batalha.\n\nConhece o baixo objeto,\nQue em triunfo te arrasta;\nCuidas que um meigo, deleitoso aspecto\nPara dourar os teus excessos basta?\nCuidas que um belo riso, um ar benigno,\nFilho da infâmia, de ternura é digno?\n\nQue engano! A formosura\nSem modéstia, sem pejo\nTédio, tédio merece, e não ternura;\nEia, pois, de um frenético desejo\nEnfreia, apaga os ímpetos, a chama,\nE lava a nódoa, com que Amor te infama.\n\nQue afronta! Que vileza!\nAlma triste, alma escrava\nDe uma profana, sensual beleza,\nDe uns olhos falsos, d'onde Amor te crava\nMil setas, cuja ponta aguda, e forte\nErvou no opaco inferno a mão da Morte:\n\nRasga o véu da cegueira\nFatal, que te alucina:\nObserva a criminosa, a lisonjeira,\nObserva a loba má, que te domina,\nVê seus dolosos beiços nacarados\nFartando peitos vis com vis agrados.\n\nContempla a desprezível:\nDe afagos nunca escassa,\nSem pudor, para todos é sensível;\nEste chama, outro amima, aquele abraça:\nEi-la com frouxos ais, úmidos beijos\nMatando n'um minuto a mil desejos.\n\nOlha aonde te abrasas:\nEm torno d'ela o Vício\nBate as lodosas, peçonhentas asas;\nE, qual submissa ovelha ao sacrifício,\nEle de Vênus ao altar nefando\nA leva pela mão de quando em quando.\n\nAs lágrimas, que viste\nNa pérfida, que adoras,\nSão gerais; os suspiros, que lhe ouviste,\nNão são teus, são comuns; alegres horas\nComo contigo, com mil outros passa:\nVê-lhe a baixeza, esquece-te da graça.\n\nPor gosto, e por costume,\nNão por domar a ardência\nDo teu negro, pestífero ciúme,\nTe sacrifica os teus rivais na ausência,\nQue, em favor das traições, com que trafica,\nN'ausência aos teus rivais te sacrifica.\n\nOh alma! Oh liberdade,\nEu vos sinto abaladas\nPelas vozes da rígida verdade:\nVossas cadeias, por Amor forjadas,\nDesejais sacudir... sim, já vos vejo\nOlhar os ferros com horror, com pejo:\n\nEstais já forcejando\nContra o peso insofrível,\nOh liberdade! Oh alma! Estais bramando\nCom ânsia, com furor, crendo impossível\nRomper, despedaçar tão fixos laços\nSem o socorro de celestes braços.\n\nA fraca humanidade\nPara tanto não basta,\nAssim é; mas implore-se a piedade\nDe um sacro velho, que os mortais afasta\nDo quase inevitável precipício,\nE ante quem treme o erro, e pasma o vício.\n\nVai pois, Canção, procura o Desengano:\nEle socorre aqueles, que o procuram,\nEle o bálsamo dá, com que se curam\nAs feridas, que faz Amor tirano."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Canções, 2.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Canção (catorze sextilhas de hexassílabos e decassílabos, esquema 6-6-10-10-10-10, rima aBAB CC; remate ABBA de decassílabos)\n\n**Notas sobre o texto.**\n\nV. 3, \"impia\": no texto atualizado grafa-se \"impía\" (im-pí-a), como na 1.ª edição dos Queixumes (1791), porque a medida (heroico 4-6-10) pede o acento na penúltima.","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-elegia-a-morte-do-principe-d-jose": {"t":["::epigrafe Levou a cruel Morte, sem ter pejo / Aquele belo moço, a quem tributo / Esperavam pagar o Indo, e o Tejo. (Bernardes, Ecl. I)\n\nEu vos saúdo, oh túmulos anosos,\nOnde a Tristeza c'o silêncio mora\nEntre cinzas, e espectros pavorosos:\n\nSalve, bosque medonho, onde a canora\nFilomela infeliz a injúria antiga\nNo curvo ramo solitária chora:\n\nOh Noute, cujo véu meus ais abriga,\nE vós, Manes, Fantasmas, sócios d'ela,\nVede a que extremos a paixão me obriga!\n\nPaixão louvável, justa, e não aquela,\nQue às almas a razão, e a liberdade\nDestrói, da vida na estação mais bela.\n\nMudos objetos, feia soledade,\nSó vós encheis meu sôfrego desejo:\nLonge, longe de nós a claridade.\n\nPorém que escuto, oh céus! Oh céus! Que vejo!\nAh Musa minha!... És tu? Vem, vem, pranteia\nO caso, que gelou de mágoa o Tejo.\n\nVelemos sobre a fria, agreste areia,\nEnquanto nos ornados aposentos\nVenturosos mortais o sono enleia.\n\nVê, se é próprio o lugar para lamentos,\nRepara: que espetáculo! Que espanto!\nMochos! Larvas! Ciprestes! Monumentos!\n\nCelebrem nossos ais, e nosso pranto\nO comum benfeitor (ah negra sorte!)\nO herói pio, em quem Lísia perdeu tanto:\n\nAquele fruto singular, que a morte\nArrancou de alta planta generosa,\nQue Deus abençoou no tronco forte;\n\nAquele, cuja face majestosa\nInda entre as mais gentis se distinguia,\nQual entre as flores se distingue a rosa;\n\nAquele, que te honrou, sabedoria,\nQue tantas, tantas vezes, oh pobreza,\nA víbora fartou, que te roía;\n\nAquele, que do cume da grandeza\nBaixava a consolar-nos, atentando\nQue todos somos uns por natureza;\n\nAquele gênio raro, afável, brando,\nQue está na etérea abóbada fulgente\nAstro novo, entre os astros cintilando;\n\nAquele, que era o pai da lusa gente,\nNosso bem, nosso amor, nossa esperança,\nPríncipe n'alma, príncipe excelente;\n\nJosé, que em doce paz no céu descansa,\nEnquanto o povo seu, já delirante,\nEm vãs, perdidas lágrimas se cansa.\n\nTriste povo! E mais triste eu, que distante\nNão pude acompanhar teu choro aflito\nN'aquele amargo, lutuoso instante!\n\nTriste povo! E mais mísero eu, que habito\nNo remoto Cantão, d'onde, Ulisseia,\nNão pode a ti voar meu débil grito!\n\nMisérrimo de mim, que em terra alheia,\nCá onde muge o mar da vasta China,\nVagabundo praguejo a morte feia!\n\nQue rigorosa lei, que horrível sina\nMe estorvou que escutasse os ais extremos\nD'aquela alma real, antes divina?\n\nD'aquele augusto peito, onde vivemos,\nD'aquele coração, que idolatramos,\nD'aquele benfeitor, que já perdemos!\n\nMas pois que nós, oh Musa, não logramos\nO doloroso bem de estar presentes\nAo fim do moço herói, que tanto amamos:\n\nJá que não vimos consternadas gentes\nFerindo os rostos, e ferindo os ares\nCom frenéticas mãos, com ais ardentes:\n\nJá que não vimos nos pomposos lares\nA meiga mãe, carpindo, ora ante o leito\nDo filho, ora do Imenso ante os altares;\n\nJá que não vimos de paixão desfeito\nO fiel coração da esposa amante\nEm lágrimas sair do ansioso peito;\n\nJá que não vimos o preclaro infante,\nPrezando mais o irmão, que a monarquia,\nTraçar a interna mágoa no semblante;\n\nE o bom príncipe, enfim, já na agonia,\nEstas vozes soltar, balbuciente,\nPondo os olhos na esposa, que o perdia:\n\n«A mão, que nos uniu tão docemente,\nOrdena, amada, que de ti me aparte:\nSeja feita a vontade omnipotente.\n\nDespindo o pó, minha alma alegre parte;\nMas crê, que, voluntária, só pudera,\nQuerida esposa, por um Deus trocar-te;\n\nNão chores, não suspires... ah! Pondera\nQue o teu amado, o teu contentamento\nNão morre, vai viver lá n'outra esfera;\n\nChamado ao sumo bem do firmamento,\nVou morar entre os justos, por clemência\nD'aquele, que subjuga o mar, e o vento.\n\nLouva, louva comigo a providência,\nA sacrossanta lei, que tem disposto\nEsta do mundo necessária ausência.\n\nNadando em mares de inefável gosto,\nVendo os coros angélicos sagrados,\nEm cada rosto lograrei teu rosto.\n\nPoder, que move os céus, que rege os fados,\nHá de aplacar a dor, que te flagela,\nAnuir a meus rogos inflamados...\n\nDeixa voar minha alma, oh alma bela,\nAdeus... Pai... Redentor... sê... sê comigo...\nAdeus...» Eis expirou nos braços d'ela.\n\nJá que não pude, oh Musa, este castigo,\nEste dano, fatal à humanidade,\nContigo ver, e deplorar contigo:\n\nPela imaginação, pela saudade\nA nós (tristes de nós!) se represente\nO efeito da geral calamidade.\n\nA mente o pinte; que não pode a mente?\nComo se goza o bem no pensamento,\nTambém no pensamento o mal se sente.\n\nOh colossos de aéreo fundamento!\nFantasmas, ilusões, que o mundo preza!\nDe que servis no fúnebre momento?\n\nPorque blasona a túmida grandeza,\nSe é vítima do abutre carniceiro,\nFilho do inferno, horror da natureza?\n\nQue bens herdamos nós do pai primeiro?\nA culpa? A morte? Abominosa herança!\nMal haja o negro monstro lisonjeiro.\n\nAi prole da magnânima Bragança,\nQuão cedo te sumiu na eternidade\nA pavorosa mão, que os raios lança!\n\nCometeste sacrílega maldade,\nPara... ah! Cessa, mortal, mortal insano,\nTreme, ajoelha, adora a divindade!\n\nNão pode (a Razão diz) ser um tirano\nEsse, que fez o barro inteligente,\nQue o filho deu por ti, gênero humano.\n\nO rei dos reis, o padre omnipotente\nAlma, que o mundo vil não merecia,\nConsigo quis no céu resplandecente.\n\nCala-te, oh dor!... Silêncio, oh agonia!...\nE vós, que os prantos da paixão mais nobre\nVerteis do morto herói na cinza fria;\n\nVós, que beijais o mausoléu, que o cobre,\nOh lusos! Consolai-vos: inda temos\nQuem preze o sábio, quem socorra o pobre.\n\nBasta, basta, não mais, não mais extremos:\nNo irmão vereis José ressuscitado,\nJoão restaurará quanto perdemos.\n\nInda há de ser por todos tão cantado\nO novo sucessor no trono augusto,\nQuanto José no túmulo é chorado.\n\nNação, fiel nação, desterra o susto:\nOutro herói, outro Atlante a monarquia\nNos firmes ombros susterá robusto.\n\nE tu, mãe do teu povo excelsa, e pia,\nQue inda desfeita em lágrimas contemplo\nNa revolta, enlutada fantasia:\n\nSobe, constante, da Memória ao templo;\nLá vale mais que um cetro uma alma forte,\nSê da conformidade o santo exemplo.\n\nÀ triste, cara irmã, que invoca a morte,\nVai docemente o pranto reprimindo;\nPinta-lhe a glória do feliz consorte,\n\nQue entre os anjos está, cantando, e rindo."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Elegias e epicédios, 2 (escrita em Macau)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Elegia (tercetos encadeados de decassílabos)\n\n**Notas sobre o texto.**\n\nV. 36, \"roía\": a ed. de 1875 imprime \"rola\", gralha evidente (a rima pede -ia: sabedoria, distinguia); o OCR da ed. de 1853 (Poesias, t. VI) dá \"rota\", compatível com \"roia\"","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-epistola-a-marcia": {"t":["Tu, de meus amorosos pensamentos\nSecretária fiel, tu, que mil vezes\nAfagas, adormeces os desgostos\nDe que semeia Amor meus tristes dias;\nOh lira, em que estes dedos preguiçosos\nGeram sem arte a lânguida harmonia,\nEfeito da ternura, e da saudade!\nHoje teus sons patéticos se apurem\nDa amizade leal no casto seio.\n\nCândida amiga do extremoso Elmano,\nMinha Márcia gentil, se eu a teu lado\nTe entretenho os ouvidos, e te influo\nPor eles no formoso, ebúrneo peito\nO encanto da suave melodia,\nA maga sensação das almas belas;\nSe te aprazem meus versos inocentes,\nSe teus olhos brilhantes como os astros\nVolves benignamente ao grato amigo,\nQue externas perfeições, de que és tão rica,\nQue o virgíneo candor te não profana\nCom torpes, sequiosos pensamentos;\nE nos dons da tua alma embelezado\nComo se ama no céu, no mundo te ama;\nSe a teus mimosos lábios, quando as Musas\nNas ternas aflições vêm consolá-lo,\nSorriso aprovador merece Elmano;\nSe no mole regaço deleitoso\nAcolhes do teu vate a doce lira\nQuando os sons lhe falseia a mão dormente;\nQue tenho com os mais, que têm comigo?\nQue me importam, querida, a voz da Fama,\nAs críticas do sábio, as invectivas\nDos Zoilos vis, dos Bávios de Ulisseia,\nGralhas, que entre pavões se não confundem,\nInda que astutas, iludindo os néscios,\nVestem pomposas, fulgurantes plumas?\nOu que me importa o público juízo?\nAmante, e não autor, desdenho, oh Márcia,\nUma inquieta glória, um árduo nome;\nNada sou: minha Musa às vezes leda,\nLeda, ou antes cansada de carpir-se,\nCuida somente em adoçar meus males,\nOs séculos por vir, e o seu não teme.\nPungidos de fantástica vaidade\nOutros lidem, padeçam, velem, suem,\nMatem-se por viver além da morte;\nQue eu não quero comprar como eles compram\nImaginários bens por males certos.\n\nFagueira, linda Márcia, quando o Fado\nVier co'a negra mão tocar meu rosto,\nSumir-me para sempre à luz do dia;\nQuando teus braços melindrosos derem\nSuave encosto à lânguida cabeça\nDo descorado moribundo amigo,\nE os frouxos olhos seus, metade abertos,\nTurvo clarão vital forem perdendo;\nQuando enfim minhas mãos em vão tentarem\nSecar teus prantos, serenar teus olhos,\nFitos no leito da benigna morte,\nE à boca o solto espírito acudindo\nColher n'essa, que adoro, o derradeiro\nÓsculo teu dulcíssimo, e piedoso;\nNão, não permitas que funérea pompa\nMe alumie a serena escuridade,\nNem que por mãos venais alvoroçado\nO bronze atroador publique a todos\nQue mais um dos mortais volveu à terra.\nNo meu asilo incógnito, e seguro,\nVivendo para os outros indif'rente,\nSobre as minhas ações um véu lhe corro:\nQual fui na vida quero ser na morte,\nContanto que a fiel, a afável Márcia\nDê honra às cinzas do amoroso Elmano,\nCom suspiros, com lágrimas, e habitem\nMemórias minhas na memória d'ela.\n\nTu, dos cuidados meus primeiro objeto,\nAnália desleal, encantadora,\nQue do vário Martinio te cegaste,\nOuvindo que morri, talvez que folgues!\nDepois que a Morte amiga houver talhado\nDe meus dias fatais a débil teia;\nDepois que mudo, e fúnebre jazigo\nMeus males encerrar, e os meus extremos,\nIde, Amores gentis, onde verdeja\nA amena, salutífera Colares,\nDe mil benignos zéfiros lavada,\nE ante a falsa, que adoro, ali pousando,\nDizei-lhe:—«Exulta, ingrata! Elmano é morto;\nMas o céu tem poder, justiça, e raios,\nO céu castigará teu vil perjúrio,\nO céu...» Não, sumo Jove, eu lhe perdoo,\nEu perdoo ao meu bem; não, não me vingues!\nAntes aos puros luminosos dias\nDe que ela goza em paz, antes, oh nume,\nUne os dias de gosto, e de ventura,\nQue eu desfrutara, se a cruel não fosse!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. II, Epístolas e sátiras, 1 (imitação de Parny)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epístola (decassílabos soltos, em parágrafos)\n\n**Notas sobre o texto.**\n\nOs vv. 19-23 e 32-36 vêm marcados com asterisco na edição (marca editorial, omitida aqui)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde02bocauoft"}]}},
"bocage-apologo-o-leao-vencido-pelo-homem": {"t":["Pôs-se em venda uma pintura,\nOnde estava figurado\nLeão de enorme estatura,\nPor mãos humanas prostrado.\n\nMirava a gente com glória\nO painel; eis senão quando\nUm leão, que ia passando,\nLhe diz: «É falsa a vitória.\n\n«Deveis o triunfo vosso\nÀ ficção, blasonadores;\nCom mais razão fora nosso,\nSe os leões fossem pintores.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 6 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (quadras de redondilha maior, rima ABAB)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-a-raposa-e-as-uvas": {"t":["Contam, que certa raposa,\nAndando muito esfaimada,\nViu roxos, maduros cachos\nPendentes de alta latada.\n\nDe bom grado os trincaria;\nMas, sem lhes poder chegar,\nDisse: «Estão verdes, não prestam,\nSó cães os podem tragar.»\n\nEis cai uma parra, quando\nProsseguia o seu caminho;\nE crendo que era algum bago\nVolta depressa o focinho."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 7 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-corvo-e-a-raposa": {"t":["É fama que estava o corvo\nSobre uma árvore pousado,\nE que no sôfrego bico\nTinha um queijo atravessado.\n\nPelo faro àquele sítio\nVeio a raposa matreira,\nA qual, pouco mais ou menos,\nLhe falou d'esta maneira:\n\n«Bons dias, meu lindo corvo;\nÉs glória d'esta espessura:\nÉs outra fênix, se acaso\nTens a voz, como a figura.»\n\nA tais palavras o corvo\nCom louca, estranha afouteza,\nPor mostrar que é bom solfista\nAbre o bico, e solta a presa.\n\nLança-lhe a mestra o gadenho,\nE diz: «Meu amigo, aprende\nComo vive o lisonjeiro\nÀ custa de quem o atende.\n\n«Esta lição vale um queijo,\nTem d'estas para teu uso.»\nRosna então consigo o corvo\nEnvergonhado, e confuso:\n\n—«Velhaca! Deixou-me em branco,\nFui tolo em fiar-me d'ela;\nMas este logro me livra\nDe cair n'outra esparrela.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 8 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-a-cigarra-e-a-formiga": {"t":["Tendo a cigarra em cantigas\nFolgado todo o verão,\nAchou-se em penúria extrema\nNa tormentosa estação.\n\nNão lhe restando migalha,\nQue trincasse, a tagarela\nFoi valer-se da formiga,\nQue morava perto d'ela.\n\nRogou-lhe, que lhe emprestasse,\nPois tinha riqueza, e brio,\nAlgum grão, com que manter-se\nTé voltar o aceso estio.\n\n«Amiga (diz a cigarra)\nPrometo à fé de animal\nPagar-vos antes de Agosto\nOs juros, e o principal.»\n\nA formiga nunca empresta,\nNunca dá, por isso ajunta:\n—«No verão em que lidavas?»\nÀ pedinte ela pergunta.\n\nResponde a outra: «Eu cantava\nNoute e dia, a toda a hora.»\n«Oh bravo! (torna a formiga)\nCantavas? Pois dança agora.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 9 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-a-montanha-que-pare": {"t":["Começou a berrar com dor de parto\nCerta montanha, e fez tamanho estrondo,\nQue acudiu muita gente, a qual supondo\nQue d'ali nasceria uma cidade\nMaior do que Paris, eis nasce um rato.\nQuando por esta fábula discorro,\nE observo que o sentido é verdadeiro,\nLogo se me afigura autor inchado,\nQue diz: «Eu cantarei a horrível guerra,\nCom que os filhos da terra\nSacrílega invasão nos céus tentaram,\nE a Jove assoberbaram.»\nPromete grandes cousas, cousas belas;\nQue produz?—Bagatelas."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 10 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (silva de decassílabos e hexassílabos, com rimas esparsas)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-leao-velho": {"t":["Decrépito o leão, terror dos bosques,\nE saudoso da antiga fortaleza,\nViu-se atacado pelos outros brutos,\nQue intrépidos tornou sua fraqueza.\nEis o lobo c'os dentes o maltrata,\nO cavalo c'os pés, o boi co'as pontas,\nE o mísero leão, rugindo apenas,\nPaciente digere estas afrontas:\nNão se queixa dos fados; porém vendo\nVir o burro, animal de ínfima sorte,\n«Ah vil raça! (lhe diz) morrer não temo,\nMas sofrer-te uma injúria é mais que morte.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 11 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (decassílabos, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-leao-cacando-com-o-burro": {"t":["Fez anos o leão, quis ir à caça,\nE a d'ele não costuma ser escassa:\nNão consiste em pardais, em bagatelas,\nMas em bons javalis, e em corças belas.\nO rei dos bosques próvido, e discreto,\nPara sortir efeito o seu projeto,\nChama o burro, animal de voz não fina,\nE o burro vai servir-lhe de buzina.\nEle ao posto o conduz, cobre-o de ramos,\nOrdena-lhe que zurre, e a seus reclamos\nCrê que inda os mesmos brutos, que dão provas\nDe atroz braveza, fugirão das covas.\nNão era aquela tropa ainda usada\nAo fragor de asinina trovoada:\nNo ar o espantoso orneio enfim ressoa,\nVaga o terror, e as grutas despovoa:\nTremendo, a turba agreste alonga o passo;\nFoge tudo, e fugindo, eis cai no laço,\nOnde os espera a garra penetrante.\n«Então, que tal, que tal? Não sou chibante?»\n(Diz o burro ao leão, co'a fronte alçada,\nArrogando-se a glória da caçada.)\n—«Troas (volta o leão) troas deveras,\nE se não conhecesse quem tu eras,\nEu mesmo com teus zurros me assombrava.»\nO burro, se pudesse, resmungava,\nE tínhamos arenga, inda que havia\nMotivo para aquela zombaria;\nPois quem há de sofrer, quieto, e mudo\nQue um, que não vale nada, arrote em tudo?\nQuem sofrerá que audácia o burro afete?\nCaráter fanfarrão não lhe compete."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 12 (traduzido de La Fontaine)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (parelhas de decassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-cao-e-a-cadela": {"t":["Tinha de uma cadela um cão fome canina,\nEle bom perdigueiro, ela de casta fina:\nMil foscas lhe fazia o terno maganão,\nMas gastava o seu tempo, o seu carinho em vão.\nDando no chichisbéu dentada, e mais dentada\nA fêmea parecia uma cadela honrada,\nE incapaz de ceder às pretensões de amor:\nMas o amante infeliz enfim foi sabedor\nDe que a mesma em que via ações tão desabridas\nEra co'um torpe cão fagueira às escondidas.\nSe és sagaz, meu leitor, talvez que tenhas visto\nCadelas de dous pés, que também fazem isto."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 13.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (parelhas de alexandrinos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-corvo-e-o-pavao": {"t":["Passeando o pavão com ufania,\nÉ fama que dissera ao corvo um dia:\n«Repara quanto devo à natureza,\nOlha que lindas cores, que viveza!\nQue adorno, que matiz! Olha este rabo!\nEm mim não há senão; e tu, diabo,\nNegro como um carvão, como um besouro,\nInda és, de mais a mais, ave de agouro!»\nO corvo, que na língua não tem papas,\nLhe responde:—«Essas penas são mui guapas;\nMas, para refrear teu desvario,\nObserva d'essas pernas o feitio.»\nAinda (quem dará crédito a isto?)\nAs pernas o pavão não tinha visto;\nMas que muito, se há gente, e gente grave,\nQue em seus olhos não vê nem uma trave?"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 14.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (parelhas de decassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-apologo-o-cao-de-fralda-e-a-raposa": {"t":["N'um dos pés arranhado um cão fraldeiro\nTemeu chegar ao transe derradeiro;\nO médico chamou, pôs-se de cama,\nE a dor encareceu como uma dama;\n(Porque n'este melindre, ou n'esta balda,\nUma dama equivale a um cão de fralda.)\nEra então a raposa arteira, e fina,\nEntre os brutos doutora em medicina.\nEntrou n'um passo grave, um ar sisudo,\nE em tom de quem dizia:—Eu saro tudo!—\nTendo-lhe visto o pé, que lhe doía,\nPerguntou ao doente o que sentia.\nDepois de se esfalfar com fofa prosa,\nConcluiu: «A doença é perigosa;\nMas hei de conseguir a grande empresa\nDe ajudar, ou vencer a natureza.»\nÉ certo que logrou tão alta sorte,\nÉ certo que a venceu, mas foi co'a morte.\nTendo emplastros, e purgas decretado,\nE com mil beberagens misturado\nMil gordos aforismos de Avicena,\nOu de Averróis, seguiu-se-lhe a gangrena,\nQue tornando mortal a arranhadura,\nO cãozinho encaixou na sepultura.\nAssim que o duro médico feroz\nO mandou visitar a seus avós,\nSem pejo, sem temor, sem pranto, ou ais,\nA paga foi pedir aos tristes pais.\nClamaram:—«Inda a terra te não traga!\nO filho nos mataste, e queres paga!...»\n—Que! (responde a raposa) Ora essa é bela!\nE o trabalho, que eu tive, é bagatela?\nDar vida não está na nossa mão;\nTanto nos rende o morto como o são.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Apólogos, 15.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Apólogo (parelhas de decassílabos)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-canconeta-a-armania": {"t":["Armânia, de alvo rosto,\nEncantador, divino,\nVagava junto à margem\nDo Tejo cristalino:\n\nEm torno à branda ninfa\nSe ria a Natureza,\nUfana em ter criado\nTão nova gentileza:\n\nZéfiro, enchendo as rosas\nDe mágoa, e de ciúme,\nIa nos lábios d'ela\nGozar melhor perfume:\n\nLindos, sutis insetos\nÀ roda lhe adejavam\nE os louros Amorinhos\nDe inveja os enxotavam:\n\nSobre o matiz dos prados\nO deleitoso Abril\nTornava-se de vê-la\nMais ledo, e mais gentil:\n\nA flor, que pelo vento\nJazera debruçada,\nErguia o tenro colo,\nDos tenros pés tocada:\n\nCom rápidos gorjeios\nO rouxinol, que encanta,\nPara seguir-lhe os passos\nIa de planta em planta:\n\nÀ ninfa, que o pisava,\nO chão se amolecia;\nCada sorriso d'ela\nAbrilhantava o dia:\n\nDobrando a graça, o lustre\nDo azul, etéreo véu,\nNo maior bem da terra\nSe recreava o céu:\n\nO Tejo namorado\nCedera a urna de ouro,\nSe Amor lhe desse em troca\nTão singular tesouro:\n\nTudo prazer sentia\nAo ver um tal portento;\nO céu, a terra, as aves,\nO rio, o sol, e o vento:\n\nMas o amoroso Elmano\nNotando oculto a bela,\nColhia outros efeitos\nDos atrativos d'ela;\n\nVibram-se-lhe seus olhos\nEnvenenado tiro;\nPor onde a frecha entrava\nSaía-lhe um suspiro:\n\nEis que o menino Idálio,\nQue aos tristes amadores\nCruentas serpes guarda\nEntre mimosas flores;\n\nAo som de um ai, que exala\nO mavioso amante,\nEncara, voa, e diz-lhe\nCom ríspido semblante:\n\n«Dos Fados no volume\nEste decreto está:\n—Quem for mais extremoso\nMais infeliz será.—\n\nN'isto revoa o nume\nDa ninfa para o lado,\nDeixando em amarguras\nSubmisso o desgraçado.\n\nAh lastimoso Elmano!\nO que ao traidor ouviste\nDesterra vãos desejos\nPara o silêncio triste.\n\nMas sempre ardor interno,\nMuda paixão te rale,\nQue a perfeição de Armânia\nOs teus martírios vale.\n\nE se entre agudas garras\nDe acerbos desprazeres\nA mil fatais combates\nTeu coração renderes,\n\nA linda mão, que adoras,\nEnfim compadecida,\nTalvez te doure a morte,\nSe te escurece a vida.\n\nPode a teu ponto extremo\nIluminar o horror,\nA bela a doce Armânia,\nAstro do céu de amor,\n\nDize-lhe então, soltando\nOs derradeiros ais,\nQue antes morrer por ela,\nDo que viver co'as mais."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Cançonetas, 1.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cançoneta (quadras de hexassílabos, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-canconeta-a-rosa": {"t":["Tu, flor de Vênus,\nCorada Rosa,\nLeda, fragrante,\nPura, mimosa;\n\nTu, que envergonhas\nAs outras flores,\nTens menos graça,\nQue os meus amores.\n\nTanto ao diurno\nSol coruscante\nCede a noturna\nLua inconstante;\n\nQuanto a Marília\nTé na pureza\nTu, que és o mimo\nDa Natureza.\n\nO buliçoso,\nCândido Amor\nPôs-lhe nas faces\nMais viva cor;\n\nTu tens agudos,\nCruéis espinhos,\nEla suaves,\nBrandos carinhos;\n\nTu não percebes\nTernos desejos,\nEm vão Favônio\nTe dá mil beijos:\n\nMarília bela\nSente, respira,\nMeus doces versos\nOuve, e suspira.\n\nA mãe das flores,\nA Primavera\nFica vaidosa,\nQuando te gera:\n\nPorém Marília\nNo mago riso\nTraz as delícias\nDo paraíso.\n\nAmor que diga\nQual é mais bela,\nQual é mais pura,\nSe tu, ou ela;\n\nQue diga Vênus...\nEla aí vem...\nAi! Enganei-me,\nQue é o meu bem."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Cançonetas, 3.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cançoneta (quadras de tetrassílabos, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-canconeta-filis-e-amor": {"t":["N'um denso bosque\nPouco trilhado,\nE a ternos crimes\nAcomodado;\n\nPor entre a rama\nFresca, e sombria\nDe tenro arbusto,\nQue me encobria,\n\nVi sem aljava\nJazer Cupido,\nJunto de Fílis\nÀ mãe fugido.\n\nEntre as nevadas\nMãos melindrosas\nTinha um fragrante\nFestão de rosas.\n\nA mais brilhante\nD'ele afastando,\nDizia a Fílis\nCom riso brando:\n\n«Mimosa ninfa,\nGlória de Amor,\nDás-lhe um beijinho\nPor esta flor?\n\n«Sou criancinha,\nNão tenhas pejo.»\nSorriu-se Fílis,\nE deu-lhe o beijo;\n\nMas o travesso\nLogo outro pede\nÀ simples ninfa,\nQue lh'os concede:\n\nQue por matar-lhe\nDoces desejos\nA cada instante\nRepete os beijos.\n\nAssim brincavam\nFílis, e Amor,\nEis que o menino,\nSempre traidor,\n\nCo'a pequenina\nBoca risonha\nLhe comunica\nSua peçonha.\n\nDescora Fílis,\nE de repente\nSolta um suspiro\nD'alma inocente.\n\nMal que o gemido\nFérvido soa\nO mau Cupido\nCom ele voa.\n\n«Ninguém, oh ninfa,\n(Diz a adejar)\nBrinca comigo\nSem suspirar.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Cançonetas, 4.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Cançoneta (quadras de tetrassílabos, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-endecha-a-gruta-do-ciume": {"t":["Há um cerrado bosque\nAquém do abismo eterno,\nVê-se o vapor do inferno\nNos ares negrejar;\n\nAli rebentam, crescem\nMil plantas venenosas,\nMil serpes tortuosas\nOuvem-se ali silvar;\n\nRochedos escabrosos\nAs nuvens ameaçam;\nRios por eles passam,\nMedrosos de os tocar;\n\nAli tremula a rama\nDo teixo, e do cipreste,\nFermenta estígia peste,\nQue as almas vem danar;\n\nDe infestas, roucas aves\nO bando ali se acouta,\nQue está de mouta em mouta\nDesastres a agourar;\n\nAs asas não meneias,\nAli, Favônio brando,\nTufões de quando em quando\nSó se ouvem rebramar.\n\nAli umas com outras\nAs árvores se fecham,\nDe sorte que não deixam\nDo dia a luz entrar;\n\nA custo ali respira,\nCercada a Natureza\nDe horror, e de tristeza,\nCapaz de a sufocar;\n\nAli, sempre aclarado\nPelo tartáreo lume,\nJaz do cruel Ciúme\nO temeroso lar.\n\nNa aborrecida entrada\nVela a mordaz Suspeita,\nContinuamente afeita\nA crer, e a recear;\n\nNo seio da caverna\nA torpe Inveja escura\nFrenética murmura,\nVenenos a espumar:\n\nSente-se lá no fundo\nDa estância sinuosa\nCaterva pavorosa\nDe monstros ulular:\n\nN'um férreo trono em brasa\nReina o Ciúme horrendo,\nAngústias mil tecendo,\nPara os mortais tragar:\n\nNa mão tem negra taça\nCheia do fel da morte,\nCom rábido transporte\nNão cessa de arquejar;\n\nAra fatal ao mundo\nTerror n'um canto inspira,\nSulfúrea, ardente pira\nN'ela se vê fumar;\n\nN'ela milhões d'amantes\nVão por destino infausto\nSer mísero holocausto,\nAs veias esgotar;\n\nMinistro carrancudo\nFrio cutelo amola,\nE as vítimas degola\nSobre o medonho altar.\n\nVós deveis crer, humanos,\nQue a descrição, que ouvistes,\nÉ de quem foi tão tristes\nObjetos contemplar.\n\nAh! Sim, já tenho sido\nPelo tirano alado\nMil vezes arrastado\nAo hórrido lugar;\n\nE se eu, mortais, não pude\nComo puderam tantos,\nEm sangue, em ais, em prantos\nO espírito soltar;\n\nFoi porque Amor cruento\nNão quis que extinto eu fosse:\nAchou que era mais doce\nMorrer do que penar."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Endechas, 2.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Endecha (quadras de hexassílabos, rima ABBC com o quarto verso agudo em -ar)\n\n**Notas sobre o texto.**\n\nV. 31, \"tristeza\": letras centrais apagadas na digitalização (lê-se \"triste..a\"; a rima com Natureza confirma)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-epigrama-pediu-pelo-amor-de-deus": {"t":["Pediu pelo amor de Deus\nDez réis um mendigo a um nobre:\nRespondeu-lhe o cavalheiro:\n«Que nunca trazia cobre.»\n\nEis por «excelência» o triste\nSúplica nova começa;\nEnternece-se o fidalgo,\nPõe-lhe nas mãos uma peça."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Epigramas, 1.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epigrama (duas quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-epigrama-dizem-que-o-caldas-glotao": {"t":["Dizem que o Caldas glotão\nEm Bocage aferra o dente:\nOra é forte admiração\nVer um cão morder na gente!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Epigramas, 2.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epigrama (quadra de redondilha maior, rima ABAB)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-epigrama-concluiu-pintor-famoso": {"t":["Concluiu pintor famoso\nUm certo retrato humano,\nE a taful sequaz de Apolo\nO foi mostrar muito ufano.\n\nPara o painel apontando\nLhe disse: «Amigo, que tal?\nDeveis gabá-lo, que vós\nConheceis o original.\n\n«Foi ditosa a pincelada;\nNunca retratei tão bem,\nNunca pintei como agora!...»\nPergunta o poeta:—«A quem?»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Epigramas, 3.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epigrama (três quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-epigrama-levando-um-velho-avarento": {"t":["Levando um velho avarento\nUma pedrada n'um olho,\nPôs-se-lhe no mesmo instante\nTamanho como um repolho.\n\nCerto doutor, não das dúzias,\nMas sim médico perfeito,\nDez moedas lhe pedia\nPara o livrar do defeito.\n\n«Dez moedas! (diz o avaro)\nMeu sangue não desperdiço:\nDez moedas por um olho!\nO outro dou eu por isso.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Epigramas, 5.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epigrama (três quadras de redondilha maior, rima nos versos pares)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-epigrama-estando-enfermo-um-poeta": {"t":["Estando enfermo um poeta\nFoi visitá-lo um doutor,\nE em rigorosa dieta\nLogo, logo o mandou pôr.\n\n«Regule-se, coma pouco»\nDiz-lhe o médico eminente:\n«Ai senhor! (acode o louco)\nPor isso é que estou doente.»"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Epigramas, 8.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Epigrama (duas quadras de redondilha maior, rima ABAB)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-madrigal-eu-tinha-prometido-a-minha-amada": {"t":["Eu tinha prometido à minha amada\nConstância até morrer; e esta promessa\nFoi na folha de um álamo gravada,\nMas quebrou-se depressa:\nErgueu-se um pé de vento,\nAdeus folha, é com ela o juramento!"],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Madrigais, 1 (traduzido)\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Madrigal (decassílabos e hexassílabos, rima AbAbcC)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}},
"bocage-madrigal-zefiros-que-brincais": {"t":["Zéfiros, que brincais co'as tranças belas\nDa minha doce Anália,\nVoai às flores da viçosa Idália,\nBem que na graça e cor são menos que elas.\nNão é por vós, Favônios, que a frescura\nTrazeis ao níveo seio,\nE à face melindrosa em que deliro:\nÉ só porque receio\nQue de astuto rival, de audaz ternura\nConvosco se disfarce algum suspiro."],"e":{"apresentacao":"**Publicação.** Obras poéticas de Bocage (1875), vol. III, Madrigais, 2.\n\n**Ortografia.** Atualizada (fonte: Obras poéticas de Bocage, ed. Teófilo Braga, Porto, 1875)\n\n**Forma.** Madrigal (decassílabos e hexassílabos rimados)","fontes":[{"nome":"Internet Archive (fac-símile)","url":"https://archive.org/details/obraspoticasde03bocauoft"}]}}
});
